def _colorref_to_hex(value: int) -> str:
    # Windows registry accent values are commonly stored in BGR/COLORREF-like order.
    r = value & 0xFF
    g = (value >> 8) & 0xFF
    b = (value >> 16) & 0xFF
    return f"#{r:02x}{g:02x}{b:02x}"


def detect_system_theme() -> dict[str, str | bool]:
    """Best-effort system color detection for Windows and Linux.

    No external dependency is required. If the platform does not expose a usable
    value, the GUI falls back to a sane light palette.
    """
    system = platform.system().lower()
    result: dict[str, str | bool] = {
        "platform": system or "unknown",
        "mode": "light",
        "is_dark": False,
        "accent": "#3584e4",
        "source": "fallback",
    }

    if system == "windows":
        try:
            import winreg  # type: ignore
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")
            apps_use_light, _ = winreg.QueryValueEx(key, "AppsUseLightTheme")
            result["is_dark"] = apps_use_light == 0
            result["mode"] = "dark" if result["is_dark"] else "light"
            result["source"] = "windows_registry"
        except Exception:
            pass
        try:
            import winreg  # type: ignore
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\DWM")
            accent_value, _ = winreg.QueryValueEx(key, "AccentColor")
            result["accent"] = _colorref_to_hex(int(accent_value))
        except Exception:
            try:
                import winreg  # type: ignore
                key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Explorer\Accent")
                accent_value, _ = winreg.QueryValueEx(key, "AccentColorMenu")
                result["accent"] = _colorref_to_hex(int(accent_value))
            except Exception:
                pass
        return result

    if system == "linux":
        color_scheme = _run_command(["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"])
        gtk_theme = _run_command(["gsettings", "get", "org.gnome.desktop.interface", "gtk-theme"])
        accent = _run_command(["gsettings", "get", "org.gnome.desktop.interface", "accent-color"])
        combined = f"{color_scheme} {gtk_theme}".lower()
        if "dark" in combined or os.environ.get("COLORFGBG", "").split(";")[-1:] == ["0"]:
            result["is_dark"] = True
            result["mode"] = "dark"
        if accent:
            result["accent"] = SYSTEM_ACCENT_MAP.get(accent.lower(), result["accent"])
        result["source"] = "linux_gsettings" if color_scheme or gtk_theme or accent else "linux_fallback"
        return result

    if system == "darwin":
        mode = _run_command(["defaults", "read", "-g", "AppleInterfaceStyle"])
        if "dark" in mode.lower():
            result["is_dark"] = True
            result["mode"] = "dark"
            result["source"] = "macos_defaults"
        return result

    return result


def palette_from_theme(theme: dict[str, str | bool]) -> dict[str, str]:
    accent = str(theme.get("accent") or "#3584e4")
    if theme.get("is_dark"):
        return {
            "bg": "#1e1f22",
            "panel": "#2b2d31",
            "field": "#151619",
            "fg": "#f2f3f5",
            "muted": "#b8bcc6",
            "accent": accent,
            "select_bg": accent,
            "select_fg": "#ffffff",
        }
    return {
        "bg": "#f6f7f9",
        "panel": "#ffffff",
        "field": "#ffffff",
        "fg": "#1f2328",
        "muted": "#57606a",
        "accent": accent,
        "select_bg": accent,
        "select_fg": "#ffffff",
    }


