    def destroy(self) -> None:
        self._cleanup_create_temp_tree(force=True)
        try:
            self._cleanup_successful_create_builds()
        except Exception:
            pass
        try:
            self._stop_create_terminal_session()
        except Exception:
            pass
        super().destroy()

    def _configure_system_theme(self) -> None:
        """Apply a best-effort native light/dark/accent palette to ttk and Tk widgets.

        This method must never prevent the GUI from starting. Windows/Linux/macOS
        color APIs are inconsistent, so every platform-specific failure falls back
        to a safe built-in palette.
        """
        try:
            palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
            self.configure(bg=palette["bg"])
            self.option_add("*Background", palette["bg"])
            self.option_add("*Foreground", palette["fg"])
            self.option_add("*selectBackground", palette["select_bg"])
            self.option_add("*selectForeground", palette["select_fg"])

            style = ttk.Style(self)
            try:
                style.theme_use("clam")
            except tk.TclError:
                pass

            style.configure(".", background=palette["bg"], foreground=palette["fg"], fieldbackground=palette["field"])
            style.configure("TFrame", background=palette["bg"])
            style.configure("TLabel", background=palette["bg"], foreground=palette["fg"])
            style.configure("TButton", background=palette["panel"], foreground=palette["fg"], padding=6)
            style.map("TButton", background=[("active", palette["accent"]), ("pressed", palette["accent"])], foreground=[("active", palette["select_fg"])])
            style.configure("TCheckbutton", background=palette["bg"], foreground=palette["fg"])
            style.configure("TRadiobutton", background=palette["bg"], foreground=palette["fg"])
            style.configure("TLabelframe", background=palette["bg"], foreground=palette["fg"], bordercolor=palette["accent"])
            style.configure("TLabelframe.Label", background=palette["bg"], foreground=palette["fg"])
            style.configure("TNotebook", background=palette["bg"], borderwidth=0)
            style.configure("TNotebook.Tab", background=palette["panel"], foreground=palette["fg"], padding=(10, 5))
            style.map("TNotebook.Tab", background=[("selected", palette["accent"])], foreground=[("selected", palette["select_fg"])])
            style.configure("TEntry", fieldbackground=palette["field"], foreground=palette["fg"], insertcolor=palette["fg"])
            style.configure("TCombobox", fieldbackground=palette["field"], foreground=palette["fg"], background=palette["panel"], arrowcolor=palette["fg"])
            style.map("TCombobox", fieldbackground=[("readonly", palette["field"])], foreground=[("readonly", palette["fg"])])
            style.configure("Treeview", background=palette["field"], fieldbackground=palette["field"], foreground=palette["fg"], bordercolor=palette["panel"], rowheight=24)
            style.configure("Treeview.Heading", background=palette["panel"], foreground=palette["fg"])
            style.map("Treeview", background=[("selected", palette["select_bg"])], foreground=[("selected", palette["select_fg"])])
            user_input_bg = "#3a2f12" if bool(getattr(self, "system_theme", {}).get("is_dark")) else "#fff8d6"
            style.configure("UserInput.TEntry", fieldbackground=user_input_bg, foreground=palette["fg"], insertcolor=palette["fg"], bordercolor=palette["accent"])
            style.configure("UserInput.TCombobox", fieldbackground=user_input_bg, foreground=palette["fg"], background=palette["panel"], arrowcolor=palette["fg"], bordercolor=palette["accent"])
            style.map("UserInput.TCombobox", fieldbackground=[("readonly", user_input_bg)], foreground=[("readonly", palette["fg"])])
            style.configure("UserInput.Treeview", background=user_input_bg, fieldbackground=user_input_bg, foreground=palette["fg"], bordercolor=palette["accent"], rowheight=24)
            style.map("UserInput.Treeview", background=[("selected", palette["select_bg"])], foreground=[("selected", palette["select_fg"])])
            style.configure("TPanedwindow", background=palette["bg"])
            style.configure("Sash", background=palette["panel"])
        except Exception:
            # Theme errors must never break startup.
            pass

    def _apply_text_widget_theme(self) -> None:
        """Apply theme, editor affordances and visible user-input highlighting."""
        palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
        is_dark = bool(getattr(self, "system_theme", {}).get("is_dark"))
        user_input_bg = "#3a2f12" if is_dark else "#fff8d6"
        user_input_texts = {
            "schema_text", "prompt_text", "project_scope_text", "reference_edit_text", "custom_prompt_text",
            "create_details_text", "create_catalog_entry_text", "create_timeline_text", "create_project_tree_text",
            "create_placeholder_text", "create_token_value_text", "create_dependency_text", "create_project_mapping_text",
            "create_file_editor_text", "micro_tasks_output_text", "ai_callback_text", "info_donation_body_text", "info_disclaimer_text",
        }
        for name in (
            "schema_text", "hook_preview", "output_text", "prompt_text", "project_scope_text",
            "project_file_preview_text", "reference_preview", "reference_edit_text", "custom_prompt_text",
            "create_details_text", "create_catalog_entry_text", "create_timeline_text", "create_project_tree_text",
            "create_placeholder_text", "create_token_value_text", "create_dependency_text", "create_project_mapping_text",
            "create_contract_preview", "create_terminal_text", "create_file_editor_text", "micro_tasks_output_text", "ai_callback_text", "info_donation_body_text", "info_disclaimer_text", "info_donation_body_text", "info_disclaimer_text",
        ):
            widget = getattr(self, name, None)
            if widget is None:
                continue
            is_user_input = name in user_input_texts
            try:
                widget.configure(
                    background=user_input_bg if is_user_input else palette["field"],
                    foreground=palette["fg"],
                    insertbackground=palette["fg"],
                    selectbackground=palette["select_bg"],
                    selectforeground=palette["select_fg"],
                    relief="flat",
                    borderwidth=1,
                    highlightthickness=1,
                    highlightbackground=palette["accent"] if is_user_input else palette["panel"],
                    highlightcolor=palette["accent"],
                )
            except Exception:
                pass
            self._setup_text_editor_features(widget, name=name, user_input=is_user_input)
        self._highlight_user_input_controls()
        self._configure_create_terminal_tags()
        self._configure_create_contract_preview_tags()

    def _highlight_user_input_controls(self) -> None:
        """Give editable ttk fields a subtle VCS-like user-input background."""
        def walk(widget):
            try:
                children = widget.winfo_children()
            except Exception:
                return
            for child in children:
                try:
                    if isinstance(child, ttk.Entry):
                        state = set(str(item) for item in child.state())
                        if "disabled" not in state and "readonly" not in state:
                            child.configure(style="UserInput.TEntry")
                    elif isinstance(child, ttk.Combobox):
                        state = set(str(item) for item in child.state())
                        if "disabled" not in state:
                            child.configure(style="UserInput.TCombobox")
                except Exception:
                    pass
                walk(child)
        walk(self)

    def _setup_text_editor_features(self, widget: tk.Text, *, name: str = "text", user_input: bool = False) -> None:
        """Attach undo/redo, current-line highlighting and a scoped editor menu."""
        if widget is None or id(widget) in getattr(self, "_ui_text_editor_widgets", set()):
            return
        try:
            self._ui_text_editor_widgets.add(id(widget))
        except Exception:
            pass
        try:
            widget.configure(undo=True, autoseparators=True, maxundo=250)
        except Exception:
            pass
        self._configure_text_line_tags(widget, user_input=user_input)
        for sequence in ("<KeyRelease>", "<ButtonRelease-1>", "<FocusIn>"):
            try:
                widget.bind(sequence, lambda _event, w=widget: self._refresh_text_current_line(w), add="+")
            except Exception:
                pass
        try:
            widget.bind("<Button-3>", lambda event, w=widget, n=name: self._show_text_editor_context_menu(event, w, n), add="+")
        except Exception:
            pass
        self._refresh_text_current_line(widget)

    def _configure_text_line_tags(self, widget: tk.Text, *, user_input: bool = False) -> None:
        palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
        is_dark = bool(getattr(self, "system_theme", {}).get("is_dark"))
        line_bg = "#203247" if is_dark else ("#fff0a6" if user_input else "#eef6ff")
        try:
            widget.tag_configure("current_line", background=line_bg)
        except Exception:
            pass

    def _refresh_text_current_line(self, widget: tk.Text) -> None:
        try:
            widget.tag_remove("current_line", "1.0", "end")
            line_start = widget.index("insert linestart")
            line_end = widget.index("insert lineend+1c")
            widget.tag_add("current_line", line_start, line_end)
        except Exception:
            pass

    def _text_line_col_label(self, widget: tk.Text) -> str:
        try:
            line, col = widget.index("insert").split(".", 1)
            return f"Line {line}, Col {int(col) + 1}"
        except Exception:
            return "Line ?"

    def _text_widget_editable(self, widget: tk.Text) -> bool:
        try:
            return str(widget.cget("state")) != "disabled"
        except Exception:
            return True

    def _show_text_editor_context_menu(self, event, widget: tk.Text, name: str = "text") -> str:
        self._refresh_text_current_line(widget)
        menu = tk.Menu(self, tearoff=0)
        editable = self._text_widget_editable(widget)
        menu.add_command(label=f"{name} · {self._text_line_col_label(widget)}", state="disabled")
        menu.add_separator()
        menu.add_command(label="Undo", command=lambda: self._safe_text_edit(widget, "edit_undo"), state="normal" if editable else "disabled")
        menu.add_command(label="Redo", command=lambda: self._safe_text_edit(widget, "edit_redo"), state="normal" if editable else "disabled")
        menu.add_separator()
        menu.add_command(label="Cut", command=lambda: widget.event_generate("<<Cut>>"), state="normal" if editable else "disabled")
        menu.add_command(label="Copy", command=lambda: widget.event_generate("<<Copy>>"))
        menu.add_command(label="Paste", command=lambda: widget.event_generate("<<Paste>>"), state="normal" if editable else "disabled")
        menu.add_command(label="Replace selection…", command=lambda: self._replace_text_selection(widget), state="normal" if editable else "disabled")
        menu.add_separator()
        menu.add_command(label="Duplicate line", command=lambda: self._duplicate_text_current_line(widget), state="normal" if editable else "disabled")
        menu.add_command(label="Delete line", command=lambda: self._delete_text_current_line(widget), state="normal" if editable else "disabled")
        menu.add_command(label="Go to line…", command=lambda: self._goto_text_line(widget))
        menu.add_separator()
        menu.add_command(label="Select all", command=lambda: self._select_all_text(widget))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass
        return "break"

    def _safe_text_edit(self, widget: tk.Text, command_name: str) -> None:
        try:
            getattr(widget, command_name)()
            self._refresh_text_current_line(widget)
        except tk.TclError:
            pass
        except Exception:
            pass

    def _replace_text_selection(self, widget: tk.Text) -> None:
        if not self._text_widget_editable(widget):
            return
        try:
            current = widget.get("sel.first", "sel.last")
        except tk.TclError:
            current = ""
        replacement = tkinter.simpledialog.askstring("Replace selection", "New text:", initialvalue=current)
        if replacement is None:
            return
        try:
            widget.edit_separator()
        except Exception:
            pass
        try:
            widget.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        widget.insert("insert", replacement)
        self._refresh_text_current_line(widget)

    def _duplicate_text_current_line(self, widget: tk.Text) -> None:
        if not self._text_widget_editable(widget):
            return
        try:
            start = widget.index("insert linestart")
            end = widget.index("insert lineend")
            line = widget.get(start, end)
            widget.edit_separator()
            widget.insert(f"{end}+1c", "\n" + line)
            self._refresh_text_current_line(widget)
        except Exception:
            pass

    def _delete_text_current_line(self, widget: tk.Text) -> None:
        if not self._text_widget_editable(widget):
            return
        try:
            widget.edit_separator()
            widget.delete("insert linestart", "insert lineend+1c")
            self._refresh_text_current_line(widget)
        except Exception:
            pass

    def _goto_text_line(self, widget: tk.Text) -> None:
        line = tkinter.simpledialog.askinteger("Go to line", "Line number:", minvalue=1)
        if not line:
            return
        try:
            widget.mark_set("insert", f"{int(line)}.0")
            widget.see("insert")
            widget.focus_set()
            self._refresh_text_current_line(widget)
        except Exception:
            pass

    def _select_all_text(self, widget: tk.Text) -> None:
        try:
            widget.tag_add("sel", "1.0", "end-1c")
            widget.mark_set("insert", "1.0")
            widget.see("insert")
        except Exception:
            pass

    def _configure_create_terminal_tags(self) -> None:
        """Give the Create terminal a light-blue chat-like base and task-aware tags."""
        widget = getattr(self, "create_terminal_text", None)
        if widget is None:
            return
        palette = getattr(self, "palette", palette_from_theme({"is_dark": True, "accent": "#3584e4"}))
        # The Create terminal is intentionally stable/dark regardless of the
        # surrounding theme so logs stay readable and color semantics remain
        # predictable during long task runs.
        base_bg = "#222222"
        base_fg = "#bfe8ff"
        colors = {
            "terminal_default": (base_fg, base_bg),
            "terminal_user": ("#7dd3fc", base_bg),
            "terminal_meta": ("#93c5fd", base_bg),
            "terminal_task": ("#c4b5fd", base_bg),
            "terminal_success": ("#86efac", base_bg),
            "terminal_warn": ("#fcd34d", base_bg),
            "terminal_error": ("#fca5a5", base_bg),
            "terminal_skip": ("#cbd5e1", base_bg),
        }
        try:
            widget.configure(
                background=base_bg,
                foreground=base_fg,
                insertbackground=base_fg,
                selectbackground="#0f4c81",
                selectforeground="#ffffff",
                font=("TkFixedFont", 10),
            )
            for tag, (fg, bg) in colors.items():
                widget.tag_configure(tag, foreground=fg, background=bg)
            widget.tag_configure("terminal_task", font=("TkFixedFont", 10, "bold"))
            widget.tag_configure("terminal_success", font=("TkFixedFont", 10, "bold"))
            widget.tag_configure("terminal_error", font=("TkFixedFont", 10, "bold"))
        except Exception:
            pass

    def _configure_create_contract_preview_tags(self) -> None:
        """Tag manual/user-injected Create preview content like a VCS diff."""
        widget = getattr(self, "create_contract_preview", None)
        if widget is None:
            return
        palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
        is_dark = bool(getattr(self, "system_theme", {}).get("is_dark"))
        manual_bg = "#3b3218" if is_dark else "#fff3bf"
        manual_fg = palette.get("fg", "#1f2328")
        try:
            widget.tag_configure("manual_inserted", background=manual_bg, foreground=manual_fg, spacing1=2, spacing3=2)
            widget.tag_configure("manual_header", background=manual_bg, foreground=manual_fg, font=("TkFixedFont", 10, "bold"))
        except Exception:
            pass

    def _tag_create_contract_block(self, header: str, next_headers: tuple[str, ...] = ()) -> None:
        widget = getattr(self, "create_contract_preview", None)
        if widget is None:
            return
        try:
            start = widget.search(header, "1.0", "end")
            if not start:
                return
            header_end = f"{start} lineend"
            end = "end-1c"
            for next_header in next_headers:
                found = widget.search(next_header, header_end, "end")
                if found:
                    end = found
                    break
            widget.tag_add("manual_header", start, header_end)
            widget.tag_add("manual_inserted", f"{start}+1line", end)
        except Exception:
            pass

    def _highlight_create_contract_manual_blocks(self) -> None:
        """Highlight Create Ctr sections that come from user edits/injected tokens."""
        widget = getattr(self, "create_contract_preview", None)
        if widget is None:
            return
        try:
            widget.tag_remove("manual_inserted", "1.0", "end")
            widget.tag_remove("manual_header", "1.0", "end")
        except Exception:
            pass
        self._configure_create_contract_preview_tags()
        self._tag_create_contract_block("Manual/user-injected state:", ("Project mapping:", "Dependency groups:"))
        self._tag_create_contract_block("Editable token map:", ("Chainable mode boilerplates:",))
        self._tag_create_contract_block("User details:", ())

    def _terminal_tag_for_line(self, line: str) -> str:
        value = str(line or "")
        lower = value.lower()
        if value.startswith(">"):
            return "terminal_user"
        if "[create-task:" in value and ":exit=0" in value:
            return "terminal_success"
        if "[create-task:" in value and ":exit=" in value and ":exit=0" not in value:
            return "terminal_error"
        if "error" in lower or "failed" in lower or "syntaxfehler" in lower or "traceback" in lower:
            return "terminal_error"
        if "warn" in lower or "missing" in lower or "manual" in lower:
            return "terminal_warn"
        if "skip" in lower or "skipped" in lower or "noop" in lower:
            return "terminal_skip"
        if "[create-task:" in value:
            return "terminal_task"
        if value.startswith("[term]") or value.startswith("[create]") or value.startswith("[chr]") or lower.startswith("temp cwd") or lower.startswith("preview target") or lower.startswith("apply path") or lower.startswith("export:"):
            return "terminal_meta"
        return "terminal_default"

    def _make_scrollable_checklist(self, parent, title: str, height: int = 180):
        """Return (container, content_frame) for long checkbox lists.

        Tkinter canvases do not get reliable wheel scrolling for child
        checkbuttons automatically, especially on Linux. Bind the wheel only
        while the pointer is inside this checklist so Target Editor lists remain
        usable even when the schema grows large.
        """
        container = ttk.LabelFrame(parent, text=title, padding=4)
        palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
        canvas = tk.Canvas(container, highlightthickness=0, height=height, background=palette["field"])
        scrollbar = ttk.Scrollbar(container, orient="vertical", command=canvas.yview)
        content = ttk.Frame(canvas)
        window_id = canvas.create_window((0, 0), window=content, anchor="nw")

        def _sync_scrollregion(_event=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception:
                pass

        def _sync_width(event):
            try:
                canvas.itemconfigure(window_id, width=event.width)
            except Exception:
                pass

        def _on_mousewheel(event):
            try:
                if getattr(event, "num", None) == 4:
                    delta = -1
                elif getattr(event, "num", None) == 5:
                    delta = 1
                else:
                    delta = -1 * int(event.delta / 120) if event.delta else 0
                if delta:
                    canvas.yview_scroll(delta, "units")
            except Exception:
                pass
            return "break"

        def _bind_wheel(_event=None):
            canvas.bind_all("<MouseWheel>", _on_mousewheel)
            canvas.bind_all("<Button-4>", _on_mousewheel)
            canvas.bind_all("<Button-5>", _on_mousewheel)

        def _unbind_wheel(_event=None):
            canvas.unbind_all("<MouseWheel>")
            canvas.unbind_all("<Button-4>")
            canvas.unbind_all("<Button-5>")

        content.bind("<Configure>", _sync_scrollregion)
        canvas.bind("<Configure>", _sync_width)
        canvas.bind("<Enter>", _bind_wheel)
        canvas.bind("<Leave>", _unbind_wheel)
        content.bind("<Enter>", _bind_wheel)
        content.bind("<Leave>", _unbind_wheel)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        container._scroll_canvas = canvas  # type: ignore[attr-defined]
        return container, content

    def _pack_text_with_scrollbars(self, parent, *, wrap: str = "none", height: int | None = None) -> tk.Text:
        frame = ttk.Frame(parent)
        frame.pack(fill="both", expand=True)
        options = {"wrap": wrap, "undo": True, "autoseparators": True, "maxundo": 250}
        if height is not None:
            options["height"] = height
        text = tk.Text(frame, **options)
        yscroll = ttk.Scrollbar(frame, orient="vertical", command=text.yview)
        xscroll = ttk.Scrollbar(frame, orient="horizontal", command=text.xview)
        text.configure(yscrollcommand=yscroll.set, xscrollcommand=xscroll.set)
        text.grid(row=0, column=0, sticky="nsew")
        yscroll.grid(row=0, column=1, sticky="ns")
        xscroll.grid(row=1, column=0, sticky="ew")
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)
        return text

    def _make_tree_manual_tags(self, tree: ttk.Treeview) -> None:
        try:
            palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
            is_dark = bool(getattr(self, "system_theme", {}).get("is_dark"))
            user_bg = "#3a2f12" if is_dark else "#fff8d6"
            structure_bg = "#17324a" if is_dark else "#e8f3ff"
            dependency_bg = "#3a1f1f" if is_dark else "#fff0e5"
            tree.tag_configure("user_input", background=user_bg, foreground=palette.get("fg", "#1f2328"))
            tree.tag_configure("structure_detected", background=structure_bg, foreground=palette.get("fg", "#1f2328"))
            tree.tag_configure("dependency_storage", background=dependency_bg, foreground=palette.get("fg", "#1f2328"))
        except Exception:
            pass

    def _visual_dependency_storage_entries(self, base: Path) -> list[str]:
        """Return dependency/cache folders for visual-only Project Tree review.

        The normal Project Tree remains .gitignore-clean. This opt-in list is
        deliberately directory-only and is excluded from selection/export by
        _project_tree_path_selection(). It is for checking where dependency
        storage exists, not for editing or AI scope expansion.
        """
        dependency_names = {
            "node_modules", ".venv", "venv", "env", ".pnpm-store", ".yarn",
            "vendor", "Pods", ".gradle", "build", "dist", ".next", ".nuxt",
            "target", "DerivedData",
        }
        result: list[str] = []
        try:
            root = Path(base).expanduser().resolve()
        except Exception:
            return result
        if not root.exists() or not root.is_dir():
            return result
        max_items = 220
        for current, dirs, _files in os.walk(root):
            dirs[:] = sorted(dirs)
            current_path = Path(current)
            rel_current = "."
            try:
                rel_current = current_path.relative_to(root).as_posix() or "."
            except Exception:
                rel_current = "."
            if ".git" in dirs:
                dirs.remove(".git")
            # Add dependency folders but do not recurse into them.
            for name in list(dirs):
                if name in dependency_names:
                    dep_rel = name if rel_current == "." else f"{rel_current}/{name}"
                    result.append(dep_rel)
                    dirs.remove(name)
                    if len(result) >= max_items:
                        return sorted(set(result))
            # Keep traversal bounded for very large repos.
            if rel_current.count("/") > 5:
                dirs[:] = []
        return sorted(set(result))

    def _code_structure_catalog(self) -> list[dict]:
        values = self.schema.get("code_structures", []) if isinstance(getattr(self, "schema", {}), dict) else []
        return [item for item in values if isinstance(item, dict)]

    def _create_tree_known_paths(self) -> set[str]:
        paths: set[str] = set()
        if not hasattr(self, "create_preview_tree"):
            return paths
        for meta in self._create_tree_metadata.values():
            rel = self._normalize_create_tree_rel(meta.get("path", ""))
            if rel:
                paths.add(rel)
        return paths

    def _create_code_structure_match_for_path(self, rel_path: str) -> dict | None:
        rel = self._normalize_create_tree_rel(rel_path)
        known_paths = self._create_tree_known_paths()
        best: tuple[int, dict] | None = None
        for entry in self._code_structure_catalog():
            indicators = [str(item).replace("\\", "/").strip("/") for item in entry.get("indicators", []) if str(item).strip()]
            if not indicators:
                continue
            score = 0
            for indicator in indicators:
                candidate = indicator if rel == "." else f"{rel.rstrip('/')}/{indicator}"
                if candidate in known_paths or any(path.startswith(candidate.rstrip("/") + "/") for path in known_paths):
                    score += 1
            # Two indicators are strong; one high-signal manifest + matching path type is still useful.
            path_type = str(entry.get("path_type") or "").lower()
            role_hint = str(self.create_tree_node_role.get() if hasattr(self, "create_tree_node_role") else "").lower()
            threshold = 2 if len(indicators) > 1 else 1
            if score >= threshold or (score >= 1 and path_type and path_type in {"backend", "frontend", "wrapper", "assets"} and path_type in role_hint):
                if best is None or score > best[0]:
                    best = (score, entry)
        return dict(best[1]) if best else None

    def _recognize_create_code_structures(self, show_message: bool = False) -> int:
        if not hasattr(self, "create_preview_tree"):
            return 0
        count = 0
        for item, meta in list(self._create_tree_metadata.items()):
            if str(meta.get("kind") or "folder") != "folder":
                continue
            match = self._create_code_structure_match_for_path(str(meta.get("path") or "."))
            if not match:
                meta.pop("code_structure", None)
                meta.pop("code_structure_label", None)
            else:
                meta["code_structure"] = str(match.get("id") or "")
                meta["code_structure_label"] = str(match.get("label") or match.get("id") or "code structure")
                count += 1
            self._update_create_tree_item_display(item)
        if hasattr(self, "create_code_structure_status"):
            self.create_code_structure_status.set(f"Code structures: {count} detected" if count else "Code structures: no matches")
        if show_message:
            messagebox.showinfo("Code structures", f"{count} Struktur-Knoten erkannt. Exp/Col klappt den aktuellen Struktur-Kontext ein oder aus.")
        self._refresh_create_project_mapping()
        self._schedule_create_preview_refresh()
        return count

    def _toggle_create_structure_open(self, open_state: bool) -> None:
        if not hasattr(self, "create_preview_tree"):
            return
        selected = self._selected_create_tree_item() if hasattr(self, "_selected_create_tree_item") else ""
        roots = [selected] if selected else list(self.create_preview_tree.get_children(""))
        def walk(item: str) -> None:
            try:
                self.create_preview_tree.item(item, open=open_state)
            except Exception:
                pass
            for child in self.create_preview_tree.get_children(item):
                walk(child)
        for root in roots:
            walk(root)

    def _operator_flow_contract(self) -> dict:
        mode_var = getattr(self, "ai_operator_execution_mode", None)
        research_var = getattr(self, "ai_research_schemas_boilerplates", None)
        mode = str(mode_var.get() if mode_var is not None else "confirm_then_execute")
        # Operator Flow is the single point of truth for start/confirmation behavior.
        # The old Export-tab checkbox "AI must confirm operators first" was removed
        # because it duplicated this mode and could drift from Prompt Builder output.
        confirm = mode in {"confirm_then_execute", "sequential_roles"}
        research = bool(research_var.get() if research_var is not None else False)
        if mode == "start_immediately":
            confirm = False
        return {
            "confirm_operators_before_start": confirm,
            "execution_mode": mode,
            "allowed_modes": ["confirm_then_execute", "start_immediately", "sequential_roles"],
            "export_instruction": (
                "AI must first list the active operator roles and wait for confirmation before implementation."
                if confirm else
                "AI may start immediately with the selected operator roles."
            ),
            "sequential_role_processing": mode == "sequential_roles",
            "sequential_schema_boilerplate_research": research,
            "research_instruction": (
                "Before implementation, process every active operation role and reference one by one. For each item, research current schemas, boilerplate patterns and official/source documentation on the internet, cite findings, then update the Create context for that item before continuing."
                if research else
                "No mandatory per-role/reference internet research step requested."
            ),
        }

    def _schema_item_by_id(self, key: str, item_id: str) -> dict:
        for item in self.schema.get(key, []):
            if isinstance(item, dict) and str(item.get("id") or "") == str(item_id):
                return item
        return {}

    def _create_operator_research_plan(self, config: dict | None = None) -> dict:
        """Build a prompt-time internet research plan for active Create roles/references.

        This does not browse from the GUI. It exports an instruction contract so
        the receiving AI can research each selected role/reference sequentially
        before implementing or refactoring.
        """
        config = config or self._current_create_config()
        enabled = bool(getattr(self, "ai_research_schemas_boilerplates", tk.BooleanVar(value=False)).get())
        roles = self._dedupe_create_list(config.get("roles", []))
        references = self._dedupe_create_list(config.get("references", []))
        steps: list[dict] = []

        for index, role_id in enumerate(roles, 1):
            role = self._schema_item_by_id("operation_roles", role_id)
            role_refs = self._dedupe_create_list(role.get("reference_domains", []) if role else [])
            steps.append({
                "step": len(steps) + 1,
                "type": "operation_role",
                "id": role_id,
                "label": role.get("label") or role_id,
                "category": role.get("category") or "role",
                "linked_references": role_refs,
                "research_prompt": (
                    f"Research current schemas, boilerplate patterns, validation practices and official documentation for operation role '{role_id}'. "
                    "Summarize only findings relevant to this Create target, cite sources, then update the prompt context before moving to the next role/reference."
                ),
            })

        for reference_id in references:
            reference = self._schema_item_by_id("reference_domains", reference_id)
            source_refs = []
            for source in reference.get("source_refs", []) if reference else []:
                if isinstance(source, dict):
                    source_refs.append({
                        "label": source.get("label"),
                        "url": source.get("url"),
                        "authority": source.get("authority"),
                    })
            steps.append({
                "step": len(steps) + 1,
                "type": "reference_domain",
                "id": reference_id,
                "label": reference.get("label") or reference_id,
                "category": reference.get("category") or "reference",
                "source_refs": source_refs,
                "research_prompt": (
                    f"Research current source truth, schema guidance and boilerplate implications for reference domain '{reference_id}'. "
                    "Prefer official/public authority documentation when available, cite sources, and record what changed in the Create context."
                ),
            })

        return {
            "enabled": enabled,
            "scope": "active_create_roles_and_references",
            "sequence_required": enabled,
            "internet_required_when_enabled": enabled,
            "apply_to_prompt_context": enabled,
            "stop_condition": (
                "Do not implement until every active role/reference research step has either a cited finding or an explicit 'not found / not needed' note."
                if enabled else
                "Research gate disabled."
            ),
            "steps": steps if enabled else [],
        }

    def _format_create_operator_research_plan(self, config: dict | None = None) -> list[str]:
        plan = self._create_operator_research_plan(config)
        if not plan.get("enabled"):
            return ["- disabled"]
        lines = [
            "- enabled: yes",
            "- sequence: active operation roles first, then active reference domains",
            f"- stop condition: {plan.get('stop_condition')}",
        ]
        for step in plan.get("steps", []):
            lines.append(f"{step.get('step')}) [{step.get('type')}] {step.get('label')} ({step.get('id')})")
            lines.append(f"   - {step.get('research_prompt')}")
        return lines

    def _set_tree_open_recursive(self, tree: ttk.Treeview, open_state: bool, parent: str = "") -> None:
        for item in tree.get_children(parent):
            try:
                tree.item(item, open=open_state)
            except Exception:
                pass
            self._set_tree_open_recursive(tree, open_state, item)

    def _expand_tree(self, tree: ttk.Treeview) -> None:
        self._set_tree_open_recursive(tree, True)

    def _collapse_tree(self, tree: ttk.Treeview) -> None:
        self._set_tree_open_recursive(tree, False)

    def _refresh_schema_outline(self) -> None:
        tree = getattr(self, "schema_outline_tree", None)
        text = getattr(self, "schema_text", None)
        if tree is None or text is None:
            return
        tree.delete(*tree.get_children(""))
        raw = text.get("1.0", "end").strip()
        if not raw:
            return
        try:
            payload = json.loads(raw)
        except Exception:
            tree.insert("", "end", text="JSON outline unavailable", values=("invalid JSON",))
            return
        def add(parent: str, key: str, value, depth: int = 0) -> None:
            label = str(key)
            if isinstance(value, dict):
                node = tree.insert(parent, "end", text=label, values=(f"object · {len(value)} fields",), open=(depth < 1))
                for child_key, child_value in value.items():
                    add(node, child_key, child_value, depth + 1)
            elif isinstance(value, list):
                node = tree.insert(parent, "end", text=label, values=(f"array · {len(value)} items",), open=(depth < 1))
                for index, child_value in enumerate(value[:250]):
                    add(node, f"[{index}]", child_value, depth + 1)
                if len(value) > 250:
                    tree.insert(node, "end", text="…", values=(f"{len(value) - 250} more items",))
            else:
                preview = str(value)
                if len(preview) > 80:
                    preview = preview[:77] + "..."
                tree.insert(parent, "end", text=label, values=(preview,))
        add("", "root", payload)

    def _attach_tree_context_menu(self, tree: ttk.Treeview, *, context_key: str, title: str, actions: list[tuple[str, object]] | None = None) -> None:
        """Attach a scoped context menu to one Treeview only.

        The context_key decides which undo/redo stack is used, so a Create list
        never leaks menu actions or history into another tab.
        """
        if tree is None or id(tree) in getattr(self, "_ui_tree_context_widgets", set()):
            return
        try:
            self._ui_tree_context_widgets.add(id(tree))
            tree.configure(style="UserInput.Treeview")
        except Exception:
            pass
        self._make_tree_manual_tags(tree)
        actions = list(actions or [])

        def _show(event):
            try:
                row = tree.identify_row(event.y)
                if row:
                    tree.selection_set(row)
                    tree.focus(row)
            except Exception:
                pass
            menu = tk.Menu(self, tearoff=0)
            menu.add_command(label=title, state="disabled")
            menu.add_separator()
            for label, callback in actions:
                menu.add_command(label=label, command=callback)
            if actions:
                menu.add_separator()
            menu.add_command(label="Undo list change", command=lambda: self._undo_ui_list_change(context_key))
            menu.add_command(label="Redo list change", command=lambda: self._redo_ui_list_change(context_key))
            menu.add_separator()
            menu.add_command(label="Copy selected row", command=lambda: self._copy_tree_selected_row(tree))
            try:
                menu.tk_popup(event.x_root, event.y_root)
            finally:
                try:
                    menu.grab_release()
                except Exception:
                    pass
            return "break"
        try:
            tree.bind("<Button-3>", _show, add="+")
        except Exception:
            pass

    def _copy_tree_selected_row(self, tree: ttk.Treeview) -> None:
        try:
            item = tree.selection()[0]
            text = str(tree.item(item, "text") or "")
            values = [str(value) for value in tree.item(item, "values")]
            payload = " | ".join([part for part in [text, *values] if part])
            self.clipboard_clear()
            self.clipboard_append(payload)
        except Exception:
            pass

    def _snapshot_ui_list_state(self, context_key: str) -> dict:
        if context_key == "create_compiler_rows":
            return {"rows": copy.deepcopy(self._create_compiler_rows)}
        if context_key == "create_dependency_rows":
            return {"rows": copy.deepcopy(self._create_dependency_rows)}
        if context_key == "create_preview_tree":
            return self._snapshot_create_preview_tree_state()
        return {}

    def _restore_ui_list_state(self, context_key: str, state: dict) -> None:
        if context_key == "create_compiler_rows":
            self._create_compiler_rows = copy.deepcopy(state.get("rows", []))
            self._render_create_compiler_rows()
            return
        if context_key == "create_dependency_rows":
            self._create_dependency_rows = copy.deepcopy(state.get("rows", []))
            self._render_dependency_rows()
            return
        if context_key == "create_preview_tree":
            self._restore_create_preview_tree_state(state)
            return

    def _push_ui_list_undo(self, context_key: str) -> None:
        state = self._snapshot_ui_list_state(context_key)
        if not state:
            return
        undo = self._ui_list_undo_stacks.setdefault(context_key, [])
        undo.append(state)
        if len(undo) > 80:
            del undo[0]
        self._ui_list_redo_stacks.setdefault(context_key, []).clear()

    def _undo_ui_list_change(self, context_key: str) -> None:
        undo = self._ui_list_undo_stacks.setdefault(context_key, [])
        if not undo:
            return
        current = self._snapshot_ui_list_state(context_key)
        state = undo.pop()
        self._ui_list_redo_stacks.setdefault(context_key, []).append(current)
        self._restore_ui_list_state(context_key, state)

    def _redo_ui_list_change(self, context_key: str) -> None:
        redo = self._ui_list_redo_stacks.setdefault(context_key, [])
        if not redo:
            return
        current = self._snapshot_ui_list_state(context_key)
        state = redo.pop()
        self._ui_list_undo_stacks.setdefault(context_key, []).append(current)
        self._restore_ui_list_state(context_key, state)

    def _snapshot_create_preview_tree_state(self) -> dict:
        tree = getattr(self, "create_preview_tree", None)
        if tree is None:
            return {}
        def walk(parent: str) -> list[dict]:
            rows = []
            for item in tree.get_children(parent):
                rows.append({
                    "iid": item,
                    "text": tree.item(item, "text"),
                    "values": list(tree.item(item, "values")),
                    "open": bool(tree.item(item, "open")),
                    "children": walk(item),
                })
            return rows
        try:
            selected = tree.selection()[0] if tree.selection() else ""
        except Exception:
            selected = ""
        return {"items": walk(""), "metadata": copy.deepcopy(self._create_tree_metadata), "selected": selected}

    def _restore_create_preview_tree_state(self, state: dict) -> None:
        tree = getattr(self, "create_preview_tree", None)
        if tree is None:
            return
        try:
            tree.delete(*tree.get_children(""))
        except Exception:
            return
        self._create_tree_metadata = copy.deepcopy(state.get("metadata", {}))
        def restore(parent: str, rows: list[dict]) -> None:
            for row in rows:
                iid = str(row.get("iid") or "")
                kwargs = {"text": row.get("text", ""), "values": row.get("values", [])}
                try:
                    if iid:
                        item = tree.insert(parent, "end", iid=iid, **kwargs)
                    else:
                        item = tree.insert(parent, "end", **kwargs)
                except Exception:
                    item = tree.insert(parent, "end", **kwargs)
                try:
                    tree.item(item, open=bool(row.get("open")))
                except Exception:
                    pass
                restore(item, row.get("children", []))
        restore("", state.get("items", []))
        selected = str(state.get("selected") or "")
        try:
            if selected and tree.exists(selected):
                tree.selection_set(selected)
                tree.see(selected)
        except Exception:
            pass
        self._refresh_create_project_mapping()
        self._render_item_dependency_rows()
        self._schedule_create_preview_refresh()

    def _reload_system_theme(self) -> None:
        """Re-read the OS theme and apply it without restarting the app."""
        self.system_theme = detect_system_theme()
        self.palette = palette_from_theme(self.system_theme)
        self._configure_system_theme()
        self._apply_text_widget_theme()
        try:
            messagebox.showinfo(
                "System colors reloaded",
                f"Theme: {self.system_theme.get('platform')} / {self.system_theme.get('mode')} / {self.system_theme.get('source')}",
            )
        except Exception:
            pass

    def _set_progress(self, label: str, current: int | None = None, total: int = 0) -> None:
        """Update progress only from real counters.

        ``total <= 0`` means the operation has no known denominator yet. In that
        case the bar becomes indeterminate and the text shows a counter/status,
        never a percentage. Percentages are shown only for exact
        ``current / total`` progress.
        """
        status = self._localized_status_label(str(label))
        has_real_total = current is not None and total is not None and int(total or 0) > 0
        if hasattr(self, "progress_bar"):
            try:
                if has_real_total:
                    self.progress_bar.stop()
                    self.progress_bar.configure(mode="determinate")
                else:
                    self.progress_bar.configure(mode="indeterminate")
                    self.progress_bar.start(12)
            except Exception:
                pass
        if has_real_total and hasattr(self, "progress_value"):
            safe_total = max(int(total or 1), 1)
            safe_current = max(0, min(int(current or 0), safe_total))
            percent = max(0, min(100, int((safe_current / safe_total) * 100)))
            self.progress_value.set(percent)
            status = f"{status} — {safe_current}/{safe_total} — {percent}%"
        elif hasattr(self, "progress_value"):
            self.progress_value.set(0)
        if hasattr(self, "progress_status"):
            self.progress_status.set(status)

    def _set_busy(self, task_name: str | None) -> None:
        self._active_task = task_name
        self._task_started_at = time.monotonic() if task_name else None
        try:
            self.configure(cursor="watch" if task_name else "")
        except Exception:
            pass

    def _progress_callback(self, label: str, current: int | None, total: int = 0) -> None:
        # generate_files can call this from a worker thread. Tk must only be
        # touched on the UI thread, so background progress is routed through the
        # queue like an XHR progress event.
        if threading.get_ident() == getattr(self, "_ui_thread_id", None):
            self._set_progress(label, current, total)
            try:
                self.update_idletasks()
            except Exception:
                pass
            return
        self._task_queue.put(("progress", label, current, total))

    def _run_background_task(self, task_name: str, worker, on_success, on_error=None) -> None:
        if self._active_task:
            messagebox.showwarning("Task already running", f"{self._active_task} is still running. Please wait until it finishes.")
            return
        self._set_busy(task_name)
        self._set_progress(f"{task_name}: started", None, 0)

        def runner() -> None:
            try:
                result = worker()
            except Exception as exc:
                self._task_queue.put(("error", task_name, exc, on_error))
            else:
                self._task_queue.put(("success", task_name, result, on_success))

        threading.Thread(target=runner, name=f"ai-json-generator-{task_name}", daemon=True).start()

    def _poll_task_queue(self) -> None:
        processed_events = 0
        max_events_per_tick = 120
        try:
            while processed_events < max_events_per_tick:
                event = self._task_queue.get_nowait()
                processed_events += 1
                kind = event[0]
                if kind == "progress":
                    _, label, current, total = event
                    self._set_progress(label, current, total)
                elif kind == "success":
                    _, task_name, result, on_success = event
                    self._set_busy(None)
                    completion = on_success(result)
                    if completion != "progress_pending":
                        self._set_progress(f"{task_name}: complete", 1, 1)
                elif kind == "error":
                    _, task_name, exc, on_error = event
                    self._set_busy(None)
                    self._set_progress(f"{task_name}: failed", None, 0)
                    if on_error:
                        on_error(exc)
                    else:
                        messagebox.showerror(f"{task_name} failed", str(exc))
                elif kind == "import_success":
                    _, generation, payload = event
                    if generation == self._import_match_generation:
                        self._import_worker_running = False
                        if self._active_task == "Import matching":
                            self._set_busy(None)
                        if not payload.get("cancelled"):
                            self._apply_import_match_result(payload)
                elif kind == "import_error":
                    _, generation, exc = event
                    if generation == self._import_match_generation:
                        self._import_worker_running = False
                        if self._active_task == "Import matching":
                            self._set_busy(None)
                        self._set_progress(f"Imports: failed: {exc}", 0)
                elif kind == "import_index_success":
                    _, generation, payload = event
                    if generation == self._import_index_generation:
                        self._import_index_worker_running = False
                        self._apply_import_index_result(payload)
                elif kind == "import_index_error":
                    _, generation, exc = event
                    if generation == self._import_index_generation:
                        self._import_index_worker_running = False
                        self._last_import_index_error = str(exc)
                        self._set_progress(f"Import index failed: {exc}", 0)
                elif kind == "create_terminal_output":
                    _, text = event
                    self._append_create_terminal(text, apply_theme=False)
                    try:
                        self._handle_create_terminal_progress_event(text)
                    except Exception:
                        pass
                elif kind == "create_terminal_status":
                    _, text = event
                    self.create_terminal_status.set(text)
                elif kind == "create_nvm_probe_result":
                    _, generation, version, status, duration_ms = event
                    self._apply_nvm_probe_result(generation, version, status, duration_ms)
                elif kind == "create_gradle_probe_result":
                    _, generation, version, status, duration_ms = event
                    self._apply_gradle_probe_result(generation, version, status, duration_ms)
                elif kind == "create_project_root_runtime_scan_result":
                    _, generation, payload = event
                    self._apply_project_root_runtime_scan_result(generation, payload)
                elif kind == "create_ecosystem_probe_result":
                    _, generation, payload = event
                    self._apply_ecosystem_probe_result(generation, payload)
        except queue.Empty:
            pass
        # Do not drain an unbounded terminal-output queue in one Tk tick. Long
        # npm/pip/build output can otherwise monopolize the UI thread and make
        # the window look frozen even though the subprocess is still alive.
        self.after(20 if processed_events >= max_events_per_tick else 80, self._poll_task_queue)

    def _app_asset_path(self, *parts: str) -> Path:
        try:
            return Path(__file__).resolve().parent / "assets" / Path(*parts)
        except Exception:
            return Path("assets") / Path(*parts)

    def _apply_window_icon(self) -> None:
        """Apply the bundled app logo as the Tk window icon when available."""
        icon_path = self._app_asset_path(f"{APP_LOGO_STEM}.png")
        try:
            if icon_path.exists():
                self._app_icon_image = tk.PhotoImage(file=str(icon_path))
                self.iconphoto(True, self._app_icon_image)
        except Exception:
            self._app_icon_image = None

    def _apply_response_policy_to_metadata(self, metadata: dict) -> dict:
        metadata = dict(metadata)
        metadata["response_policy"] = {
            "changed_files_only": bool(self.changed_files_only.get()),
            "ai_instruction": "Return only changed files plus concise validation notes; do not paste unchanged files." if self.changed_files_only.get() else "Normal scoped answer mode.",
        }
        return metadata

