    def _is_project_tree_tab_active(self) -> bool:
        if not hasattr(self, "notebook") or not hasattr(self, "project_tree_tab"):
            return False
        try:
            return self.notebook.select() == str(self.project_tree_tab)
        except Exception:
            return False

    def _is_create_tab_active(self) -> bool:
        if not hasattr(self, "notebook") or not hasattr(self, "create_tab"):
            return False
        try:
            return self.notebook.select() == str(self.create_tab)
        except Exception:
            return False

    def _is_patch_tab_active(self) -> bool:
        if not hasattr(self, "notebook") or not hasattr(self, "patch_tab"):
            return False
        try:
            return self.notebook.select() == str(self.patch_tab)
        except Exception:
            return False

    def _create_source_mount_signature_value(self) -> str:
        """Stable Create mount identity.

        This intentionally does *not* include per-file mtimes/sizes. A Start
        tree is cloned once into Create and then treated as the mounted editable
        Create base until Unmount / project reload / working-tree change clears
        it. Normal Worktree scans may notice file changes, but they must not
        silently recreate the Create clone.
        """
        base = str((self._create_project_source_base or Path("")).resolve()) if self._create_project_source_base else ""
        payload = {
            "base": base,
            "mode": self.create_mode.get(),
            "stack": self.create_stack.get(),
            "target_path": self.create_target_path.get(),
            "build_target": self.create_build_target.get(),
        }
        try:
            raw = json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str)
        except Exception:
            raw = repr(payload)
        return hashlib.sha1(raw.encode("utf-8", errors="ignore")).hexdigest()[:16]

    def _create_source_clone_ready(self) -> bool:
        root = self._create_temp_root()
        manifest_path = root / "CREATE_SOURCE_CLONE_MANIFEST.json"
        mount_signature = self._create_source_mount_signature_value()
        if not mount_signature:
            return False
        if mount_signature and mount_signature == getattr(self, "_create_source_loaded_signature", ""):
            if root.exists() and (manifest_path.exists() or isinstance(getattr(self, "_create_source_clone_manifest", None), dict)):
                return True
        if manifest_path.exists():
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
                if str(manifest.get("source_mount_signature") or "") == mount_signature:
                    self._create_source_clone_manifest = manifest
                    self._create_source_loaded_signature = mount_signature
                    self._create_source_mount_signature = mount_signature
                    self._create_last_source_clone_signature = str(manifest.get("source_scope_signature") or "")
                    return True
            except Exception:
                pass
        return False

    def _apply_create_runtime_hints_from_cached_source_scope(self, reason: str = "create_source_scope") -> None:
        """Reuse the existing Project Tree scope reader result for Create runtime hints.

        This intentionally does not crawl the project again. If the Create working
        directory was already scanned by the normal Create-source load path, the
        cached scope is passed into the existing NVM/Gradle hint application.
        """
        try:
            root = self._create_temp_root().resolve()
            signature = ("create_working_dir", str(root))
            scope = self._project_tree_scope_cache.get(signature)
            if isinstance(scope, dict):
                self._apply_runtime_hints_from_project_tree_scope(root, scope, reason)
                self._schedule_create_stack_runtime_check(reason, delay_ms=120)
        except Exception:
            pass

    def _ensure_create_source_loaded_on_create_tab(self) -> None:
        """Clone/read the Start working tree only when the user opens Create.

        Normal Working Tree is read-only evidence. It must never clone while the
        Export tree source is `normal_working_tree`. The Create source is cloned
        exactly once per mounted project into the Create temp root, then reused
        until Unmount / working-tree change / explicit reload clears the mount.
        The heavy clone runs in a background worker so the loading bar keeps
        repainting during long copies.
        """
        if not self._is_create_tab_active():
            return
        if not self._use_project_first_tree_preview():
            return
        if self._active_successful_create_build_for_current_stack():
            self._restore_completed_create_build_root_for_current_stack()
            return
        if self._create_source_clone_ready():
            try:
                self.create_source_clone_status.set("Source clone: mounted from cache")
            except Exception:
                pass
            self._apply_create_runtime_hints_from_cached_source_scope("create_source_cache_ready")
            self._refresh_create_tree_preview()
            return
        if getattr(self, "_create_source_load_requested", False) or getattr(self, "_create_source_clone_running", False):
            return
        if self._active_task:
            # Do not stack clone jobs behind another worker. The next Create-tab
            # focus/change will retry once the UI is idle.
            return

        base = self._create_project_source_base.resolve() if self._create_project_source_base else None
        scope = copy.deepcopy(self._create_project_scope_snapshot) if isinstance(self._create_project_scope_snapshot, dict) else None
        if base is None or not isinstance(scope, dict):
            return
        root = self._create_temp_root()
        export_dir = self._worktree_export_dir(base)
        create_export_dir = self._create_export_path().resolve()
        source_scope_signature = self._create_source_scope_signature()
        mount_signature = self._create_source_mount_signature_value()
        create_mode = self.create_mode.get()
        create_stack = self.create_stack.get()
        self._create_source_load_requested = True
        self._create_source_clone_running = True
        try:
            self.create_source_clone_status.set("Source clone: waiting for worker")
        except Exception:
            pass

        def worker() -> dict:
            self._progress_callback("Create Source Clone: preparing clone", None, 0)
            root.mkdir(parents=True, exist_ok=True)
            manifest_path = root / "CREATE_SOURCE_CLONE_MANIFEST.json"
            if manifest_path.exists():
                try:
                    existing = json.loads(manifest_path.read_text(encoding="utf-8"))
                    if str(existing.get("source_mount_signature") or "") == mount_signature:
                        self._progress_callback("Create Source Clone: reusing existing mount", 1, 1)
                        self._progress_callback("Create Working Dir Scan: reading existing mount immediately", None, 0)
                        create_scope = build_project_scope(root, export_dir=create_export_dir, progress_callback=self._progress_callback)
                        create_fingerprint = self._scope_filesystem_fingerprint(root, create_scope, progress_label="Create Working Dir Scan-Signatur")
                        return {"manifest": existing, "root": str(root), "source_scope_signature": source_scope_signature, "mount_signature": mount_signature, "reused": True, "create_scope": create_scope, "create_fingerprint": create_fingerprint}
                except Exception:
                    pass
            self._progress_callback("Create Source Clone: cloning Start working tree", None, 0)
            manifest = clone_project_scope_to_directory(
                base,
                root,
                scope,
                export_dir=export_dir,
                include_dependency_manifests=True,
                write_manifest=True,
                progress_callback=self._progress_callback,
            )
            manifest["source_scope_signature"] = source_scope_signature
            manifest["source_mount_signature"] = mount_signature
            manifest["create_mode"] = create_mode
            manifest["create_stack"] = create_stack
            manifest_path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            self._progress_callback("Create Source Clone: clone complete, scanning Create Working Dir immediately", None, 0)
            create_scope = build_project_scope(root, export_dir=create_export_dir, progress_callback=self._progress_callback)
            create_fingerprint = self._scope_filesystem_fingerprint(root, create_scope, progress_label="Create Working Dir Scan-Signatur")
            return {"manifest": manifest, "root": str(root), "source_scope_signature": source_scope_signature, "mount_signature": mount_signature, "reused": False, "create_scope": create_scope, "create_fingerprint": create_fingerprint}

        def success(payload: dict) -> None:
            manifest = dict(payload.get("manifest") or {})
            self._create_source_clone_manifest = manifest
            self._create_last_source_clone_signature = str(payload.get("source_scope_signature") or "")
            self._create_source_loaded_signature = str(payload.get("mount_signature") or "")
            self._create_source_mount_signature = self._create_source_loaded_signature
            self._create_source_clone_running = False
            self._create_source_load_requested = False
            try:
                copied = manifest.get("copied_file_count", manifest.get("file_count", 0))
                status = "reused" if payload.get("reused") else "mounted"
                self.create_source_clone_status.set(f"Source clone: {status}, {copied} file(s) → {payload.get('root')}")
            except Exception:
                pass
            create_scope = payload.get("create_scope")
            if isinstance(create_scope, dict):
                create_root = Path(payload.get("root") or root).resolve()
                create_signature = ("create_working_dir", str(create_root))
                self._project_tree_scope_cache[create_signature] = dict(create_scope)
                self._project_tree_scope_fingerprint_cache[create_signature] = str(payload.get("create_fingerprint") or "")
                self._project_tree_cache_check_result_cache[create_signature] = (time.monotonic(), False)
                try:
                    self._apply_runtime_hints_from_project_tree_scope(create_root, create_scope, "create_working_dir_scan")
                    self._schedule_create_stack_runtime_check("create_working_dir_scan", delay_ms=120)
                except Exception:
                    pass
            self._refresh_project_tree_source_options()
            # Do not materialize a large project tree on the Tk callback thread.
            # The source clone itself is the editable Create base; missing scaffold
            # files are created lazily by terminal timeline tasks after confirm.
            try:
                self._refresh_create_tree_preview()
            except Exception as exc:
                try:
                    self.create_source_clone_status.set(f"Source clone mounted, Preview refresh failed: {exc}")
                except Exception:
                    pass
            self._set_progress("Create: clone/scan ready; preview materializes in the terminal when needed", 1, 1)
            if self._is_project_tree_tab_active() and self._use_create_working_dir_for_project_tree():
                self._refresh_project_tree(force_scan=False, reason="create_clone_ready")

        def failed(exc: Exception) -> None:
            self._create_source_clone_running = False
            self._create_source_load_requested = False
            self._set_progress(f"Create: clone/read failed: {exc}", 0)
            try:
                self.create_source_clone_status.set(f"Source clone failed: {exc}")
            except Exception:
                pass

        self._run_background_task("Create Source Clone", worker, success, failed)

    def _on_notebook_tab_changed(self, _event=None) -> None:
        if self._is_create_tab_active():
            self._refresh_create_project_mapping()
            try:
                self._schedule_create_stack_runtime_check("create_tab_activated", delay_ms=100)
            except Exception:
                pass
            self._ensure_create_source_loaded_on_create_tab()
            self._ensure_create_tab_git_status_scan(reason="create_tab_activated", force=False)
            self._auto_join_create_terminal_if_needed()
        if getattr(self, "notebook", None) is not None and self.notebook.select() == str(self.generator_tab):
            try:
                self._sync_generator_targets_from_current_evidence("generator_tab_activated")
            except Exception as exc:
                self._set_progress(f"Generator targets: sync skipped: {exc}", 0)
        if self._is_patch_tab_active():
            # Opening Patch must preload status, but it remains Create/Temp-only.
            self._refresh_patch_status()
        if self._is_project_tree_tab_active():
            self._refresh_project_tree_source_options()
            if self._project_tree_scope_loaded:
                self._set_progress("Project Tree: Export tab uses existing snapshot", 1, 1)
                # Opening the Export tab must not start cache validation, Include Imports,
                # or a Create clone. Manual Refresh is the only export-tab rescan trigger.
            elif not self._active_task:
                self._refresh_project_tree(reason="export_tab_initial_read")


