    def _is_stack_specific_new_abstraction_entry(self, entry: dict | None) -> bool:
        """Return True for stack-owned New Abstraction entries.

        Entries like 3D-Tool, Blender-Viewer or AI-Prompt image tools are stack
        choices.  They must stay in the Stack/Category selectors and must not be
        presented as separate mode plans in the Create header Entry selector.
        """
        if not isinstance(entry, dict):
            return False
        mode_values = self._create_chain_entry_modes(entry) if hasattr(self, "_create_chain_entry_modes") else {str(entry.get("mode") or "")}
        mode_text = str(entry.get("mode") or "").strip()
        category_text = " ".join(str(entry.get(key) or "") for key in ("category", "stack_category", "catalog_category", "group")).strip()
        return (
            "new_project_abstraction" in mode_values
            or mode_text == "new_project_abstraction"
        ) and (
            bool(str(entry.get("stack_node_id") or "").strip())
            or category_text.startswith("Create New Abstraction /")
        )

    def _new_abstraction_catalog_entries(self, config: dict | None = None, chain_schema: dict | None = None) -> list[dict]:
        """Return the user-visible Create header Entry list for New Abstraction.

        Stack-specific ideas are deliberately not duplicated here.  The header
        entry is one stable, generic contract that composes the selected Stack,
        Category, Build target, tokens and chain schema into the prompt.
        """
        config = config or {}
        chain_schema = chain_schema or {}
        stack_label = str(config.get("label") or self.create_stack.get() or "selected stack").strip()
        category = str(config.get("category") or self.create_stack_category.get() or "selected category").strip()
        fields = [dict(item) for item in chain_schema.get("fields", []) if isinstance(item, dict)]
        tokens = self._dedupe_create_list([
            "@root", "@wrapper", "@generated", "@assets",
            "{$create_mode}", "{$selected_stack}", "{$build_target}", "{$custom_export_path}",
            *[str(item) for item in chain_schema.get("tokens", []) if str(item).strip()],
        ])
        return [{
            "id": "new_project_abstraction_selected_stack",
            "label": "Create New Abstraction from selected Stack",
            "display_name": "Create New Abstraction from selected Stack",
            "context_hint": f"Stack: {stack_label} · Category: {category}",
            "mode": "new_project_abstraction",
            "routine": "create_new_abstraction",
            "group": "New Abstraction",
            "category": "Create Mode / New Abstraction",
            "stack_category": category,
            "stack_node_id": str(config.get("node_id") or "").strip(),
            "order": 10,
            "intent": "Create a new abstraction from the currently selected Stack/Category without duplicating stack choices as separate plans.",
            "template": "Create a new project abstraction from the selected Stack '{$selected_stack}' using the active Create mapping, timeline, dependency layer, Build.complete handoff and manifest export contract.",
            "fields": fields,
            "tokens": tokens,
            "timeline_tokens": self._dedupe_create_list([str(item) for item in chain_schema.get("timeline_tokens", []) if str(item).strip()]),
            "validation_focus": ["selected stack/category", "target tree", "dependency layer", "Build.complete handoff", "export manifest"],
            "output_contract": ["abstraction_blueprint", "target_tree", "dependency_layer", "validation_plan", "known_gaps"],
            "non_goals": [
                "Do not duplicate 3D/Blender/AI/PDF stack choices as catalog plans.",
                "Do not patch an existing project in New Project Abstraction mode.",
                "Do not switch to Feature/Refactor until Build.complete or Start project evidence exists.",
            ],
            "rules": [
                "Use Stack and Stack category as the source of truth for project type.",
                "Keep Catalog Entry visible in new_project_abstraction, but expose only the generic selected-stack contract.",
                "After Build.complete, continue in Feature/Refactor mode for project changes.",
            ],
        }]

    def _new_abstraction_plan_entries(self, config: dict | None = None) -> list[dict]:
        """Return selectable create_new_abstraction plan metadata.

        These entries belong to New Project Abstraction itself. They are not
        Feature or Refactor plans; those modes continue only from Build.complete
        or verified Start-tab project evidence.
        """
        result: list[dict] = []
        for raw in self.schema.get("create_abstraction_pipeline_extensions", []):
            if not isinstance(raw, dict):
                continue
            if self._is_stack_specific_new_abstraction_entry(raw):
                # Stack-owned abstractions are selected via Stack/Category, not
                # duplicated as Create header catalog plans.
                continue
            entry_id = str(raw.get("id") or raw.get("chain_boilerplate_id") or "").strip()
            if not entry_id:
                continue
            if config:
                chain_ids = {str(item).strip() for item in config.get("chain_boilerplate_ids", []) if str(item).strip()}
                node_id = str(config.get("node_id") or "").strip()
                raw_stack_id = str(raw.get("stack_node_id") or "").strip()
                if chain_ids and entry_id not in chain_ids and raw_stack_id != node_id:
                    continue
            result.append({
                "id": entry_id,
                "label": str(raw.get("label") or entry_id).strip(),
                "user_goal": str(raw.get("intent") or "").strip(),
                "mode": "new_project_abstraction",
                "routine": "create_new_abstraction",
                "group": str(raw.get("group") or raw.get("catalog_category") or raw.get("stack_category") or "New Abstraction").strip(),
                "category": str(raw.get("category") or raw.get("stack_category") or raw.get("group") or "New Abstraction").strip(),
                "stack_category": str(raw.get("stack_category") or raw.get("category") or raw.get("group") or "New Abstraction").strip(),
                "catalog_category": str(raw.get("catalog_category") or raw.get("category") or raw.get("group") or "New Abstraction").strip(),
                "stack_node_id": str(raw.get("stack_node_id") or "").strip(),
                "chain_boilerplate_id": str(raw.get("chain_boilerplate_id") or entry_id).strip(),
                "validation_focus": [str(item) for item in raw.get("validation_focus", []) if str(item).strip()],
                "output_contract": [str(item) for item in raw.get("output_contract", []) if str(item).strip()],
                "handoff_rule": str(raw.get("handoff_rule") or "After Build.complete, continue in Feature/Refactor mode.").strip(),
            })
        if result:
            return result
        return [
            {
                "id": "new_project_abstraction_generic",
                "label": "New Project Abstraction",
                "user_goal": "Create a new target abstraction from the selected stack and manifest evidence.",
                "mode": "new_project_abstraction",
                "routine": "create_new_abstraction",
                "group": "New Abstraction",
                "validation_focus": ["target tree", "dependency layer", "timeline", "export manifest"],
                "output_contract": ["abstraction_blueprint", "target_tree", "validation_plan", "known_gaps"],
                "handoff_rule": "After Build.complete, continue in Feature/Refactor mode.",
            }
        ]

    def _create_mode_catalog(self, config: dict | None = None) -> dict:
        config = config or {}
        target = config.get("build_target", self.create_build_target.get())
        target_relations = self._create_target_root_relations() if hasattr(self, "create_preview_tree") else {}
        shortcut_roots = {key: str(value) for key, value in self._create_context_roots().items() if key.startswith("@")}
        dependency_layer = self._effective_dependency_layer(config)
        new_chain_schema = self._create_chain_schema("new_project_abstraction", ["generic_project"], config)
        new_catalog_entries = self._new_abstraction_catalog_entries(config, new_chain_schema)
        stack_entry = {
            "entry_mode": "new_project_abstraction",
            "catalog_type": "stack_entry",
            "stack": self.create_stack.get(),
            "category": config.get("category", self.create_stack_category.get()),
            "target": target,
            "path": config.get("path", self.create_target_path.get()),
            "tree": list(config.get("tree", [])),
            "target_relations": target_relations,
            "shortcut_roots": shortcut_roots,
            "dependencies": config.get("dependency_groups", config.get("dependencies", "")),
            "dependency_layer": dependency_layer,
            "timeline": self._base_create_timeline_lines(config) if config else [],
            "artifacts": list(config.get("artifacts", [])),
            "plans": self._new_abstraction_plan_entries(config),
            "chain_schema": new_chain_schema,
            "stack_bound_boilerplates": new_chain_schema.get("boilerplates", []),
            "boilerplates": new_catalog_entries,
            "schema_boilerplate_source": "schema_create_stack_catalog owns stack-specific abstractions; Create header Entry exposes the generic selected-stack contract; Feature/Refactor chains require existing-project mode gates",
            "prompt_rules": [
                "Create the project abstraction from the selected stack only.",
                "Do not use Start-tab synthetic temp paths as existing-project evidence.",
                "After Build.complete, switch to feature_for_existing_project for further work.",
                "New Abstraction catalog entries are not Feature/Refactor plans and do not patch existing projects.",
            ],
        }
        evidence = self._create_project_evidence_payload(config)
        feature_catalog = self._feature_plan_catalog(evidence, config)
        refactor_catalog = self._refactor_plan_catalog(evidence, config)
        mode = self.create_mode.get()
        if mode == "feature_for_existing_project":
            active_entry = feature_catalog
        elif mode == "refactor_existing_stack":
            active_entry = refactor_catalog
        else:
            active_entry = stack_entry
        return {
            "active_mode": mode,
            "available_modes": self._create_available_modes(),
            "active_catalog": active_entry,
            "new_project_abstraction": stack_entry,
            "feature_for_existing_project": feature_catalog,
            "refactor_existing_stack": refactor_catalog,
            "chain_schema": active_entry.get("chain_schema", self._create_chain_schema(mode, [], config)),
            "parameter_context": active_entry.get("parameter_context") or self._create_parameter_context_priority(config.get("create_mode_parameters", self._create_mode_parameter_profile()) if isinstance(config, dict) else None),
            "parameter_boilerplates": active_entry.get("parameter_boilerplates") or self._create_mode_parameter_boilerplates(config.get("create_mode_parameters", self._create_mode_parameter_profile()) if isinstance(config, dict) else None),
            "mode_gate": {
                "default_start_worktree_is_synthetic": True,
                "new_project_hidden_when_start_target_match": self._has_start_tab_target_match(),
                "feature_refactor_require": "Build.complete or real Start-tab target match",
            },
        }

    def _prompt_builder_context_variable_map(self) -> dict[str, str]:
        # The Prompt Builder reuses the Create shortcut compiler. After
        # Build.complete, _create_context_roots() points at the completed build;
        # before that it still exposes safe current Create mapping values.
        return self._create_context_variable_map()

    def _prompt_builder_build_complete_token_rows(self, text: str = "", build_record: dict | None = None, limit: int = 40) -> list[dict]:
        """Return available Build.complete/@ tokens for Own Weighted Prompt context."""
        token_map = self._prompt_builder_context_variable_map()
        rows: list[dict] = []
        used_tokens = {row.get("token") for row in self._create_shortcut_reference_rows(text, build_record)} if text else set()
        for token in sorted(token_map.keys()):
            try:
                resolved = self._resolve_create_context_token(token, build_record)
            except Exception:
                resolved = str(token_map.get(token) or "")
            exists = False
            kind = "value"
            try:
                path = Path(str(resolved))
                exists = path.exists()
                kind = "dir" if path.is_dir() else ("file" if path.is_file() else "path")
            except Exception:
                pass
            rows.append({
                "token": token,
                "resolved": resolved,
                "exists": exists,
                "kind": kind,
                "used_in_own_prompt": token in used_tokens,
                "source": "Build.complete" if self._active_successful_create_build_for_current_stack() else "Create mapping",
            })
            if len(rows) >= limit:
                break
        return rows

    def _prompt_builder_build_complete_token_lines(self, text: str = "", build_record: dict | None = None, profile: dict | None = None) -> list[str]:
        profile = profile or self._export_intelligence_profile(self._create_export_intelligence_value())
        rows = self._prompt_builder_build_complete_token_rows(text, build_record, limit=12 if str(profile.get("id") or "") == "hoch" else 6)
        lines = [
            "### Build.complete Tokens / Own Weighted Prompt",
            "- These tokens belong above the Own Prompt or inside the Own Weighted Prompt and are resolved against Build.complete/Create mapping before the build.",
        ]
        if not rows:
            lines.append("- No Build.complete/Create mapping tokens available.")
            return lines
        for row in rows:
            resolved = str(row.get("resolved") or "")
            preview = resolved if len(resolved) <= 160 else resolved[:157] + "..."
            marker = "used" if row.get("used_in_own_prompt") else "available"
            lines.append(f"- `{row.get('token')}` → {preview} ({row.get('kind')}, {marker})")
        return lines

    def _refresh_prompt_builder_context_variable_menu(self) -> None:
        values = sorted(self._prompt_builder_context_variable_map().keys())
        box = getattr(self, "prompt_builder_context_box", None)
        if box is not None:
            try:
                box.configure(values=values)
            except Exception:
                pass
        current = str(getattr(self, "prompt_builder_context_variable", tk.StringVar(value="")).get() or "").strip()
        if not current and values:
            try:
                self.prompt_builder_context_variable.set(values[0])
            except Exception:
                pass
        self._show_prompt_builder_context_preview()

    def _show_prompt_builder_context_preview(self) -> None:
        key = str(getattr(self, "prompt_builder_context_variable", tk.StringVar(value="")).get() or "").strip()
        try:
            value = self._resolve_create_context_token(key) if key else ""
        except Exception:
            value = ""
        preview = value if len(value) <= 180 else value[:177] + "..."
        try:
            self.prompt_builder_context_preview.set(f"{key} → {preview}")
        except Exception:
            pass

    def _focused_prompt_builder_text_widget(self):
        try:
            focused = self.focus_get()
        except Exception:
            focused = None
        for name in ("custom_prompt_text", "prompt_text"):
            widget = getattr(self, name, None)
            if focused is widget:
                return widget
        return getattr(self, "custom_prompt_text", None)

    def _insert_prompt_builder_context_variable(self) -> None:
        key = str(getattr(self, "prompt_builder_context_variable", tk.StringVar(value="")).get() or "").strip()
        if not key:
            return
        widget = self._focused_prompt_builder_text_widget()
        if widget is None:
            return
        try:
            widget.insert("insert", key)
            widget.focus_set()
            self._show_prompt_builder_context_preview()
        except Exception:
            pass

    def _compile_prompt_builder_shortcuts(self, target: str = "custom") -> None:
        widget = getattr(self, "custom_prompt_text", None) if target == "custom" else getattr(self, "prompt_text", None)
        if widget is None:
            return
        try:
            source = widget.get("1.0", "end")
            compiled = self._resolve_create_context_shortcuts(source)
            source_kind = "shortcut_compile_custom" if target == "custom" else "shortcut_compile_generated"
            overlay_task = self._prompt_builder_custom_task_text() if target != "custom" else self._extract_prompt_builder_task_overlay(source)
            compiled = self._wrap_human_prompt_builder_output(source_kind, compiled, custom_task=overlay_task, already_compiled=True)
            widget.delete("1.0", "end")
            widget.insert("1.0", compiled.rstrip() + "\n")
            self._show_prompt_builder_context_preview()
            self._apply_text_widget_theme()
            self._set_progress("Prompt Builder: @ shortcuts human-compiled", 1, 1)
        except Exception as exc:
            messagebox.showerror("Compile shortcuts", str(exc))

    def _refresh_create_context_variable_menu(self) -> None:
        values = sorted(self._create_context_variable_map().keys())
        box = getattr(self, "create_context_variable_box", None)
        if box is not None:
            try:
                box.configure(values=values)
            except Exception:
                pass
        if self.create_context_variable.get() not in values and values:
            # Do not overwrite a typed @backend/utils.py; only initialize empty values.
            current = self.create_context_variable.get().strip()
            if not current:
                self.create_context_variable.set(values[0])
        self._show_create_context_variable_preview()
        if hasattr(self, "prompt_builder_context_box"):
            self._refresh_prompt_builder_context_variable_menu()

    def _show_create_context_variable_preview(self) -> None:
        key = self.create_context_variable.get().strip()
        value = self._resolve_create_context_token(key) if key else ""
        preview = value if len(value) <= 180 else value[:177] + "..."
        self.create_context_variable_preview.set(f"{key} → {preview}")

    def _insert_create_context_token(self, token: str) -> None:
        self.create_context_variable.set(str(token or "").strip())
        self._insert_create_context_variable()

    def _insert_create_context_variable(self) -> None:
        key = self.create_context_variable.get().strip()
        if not key:
            return
        widget = getattr(self, "create_details_text", None)
        if widget is None:
            return
        try:
            widget.insert("insert", key)
            widget.focus_set()
            self._show_create_context_variable_preview()
            self._schedule_create_preview_refresh()
        except Exception:
            pass

    def _create_catalog_scope_keys(self) -> list[str]:
        # One user-facing catalog selector exists: the active Create header Entry.
        # It follows the active mode. New Project Abstraction exposes its own
        # new-abstraction plans here; Feature/Refactor expose existing-project
        # chain entries only after the mode gate allows those modes.
        return ["active"]

    def _selected_create_catalog_payload(self, config: dict | None = None) -> dict:
        config = config or self._current_create_config()
        mode_catalog = self._create_mode_catalog(config)
        self.create_catalog_scope.set("active")
        return dict(mode_catalog.get("active_catalog") or {})

    def _create_catalog_entry_label(self, entry: dict) -> str:
        entry_id = str(entry.get("id") or "").strip()
        label = str(entry.get("display_name") or entry.get("label") or entry_id or "Entry").strip()
        context = str(entry.get("context_hint") or entry.get("quick_context") or "").strip()
        visible = label if not context else f"{label} · {context}"
        return f"{visible} [{entry_id}]" if entry_id else visible

    def _create_catalog_entry_options(self, config: dict | None = None) -> list[str]:
        catalog = self._selected_create_catalog_payload(config)
        entries = [entry for entry in list(catalog.get("boilerplates") or catalog.get("chain_schema", {}).get("boilerplates", []) or []) if isinstance(entry, dict)]
        entries.sort(key=lambda entry: (str(entry.get("group") or ""), int(entry.get("order") or 999), str(entry.get("display_name") or entry.get("label") or entry.get("id") or "")))
        return [self._create_catalog_entry_label(entry) for entry in entries]

    def _selected_create_catalog_entry_id(self) -> str:
        value = str(self.create_catalog_entry.get() or "").strip()
        if value.endswith("]") and "[" in value:
            return value.rsplit("[", 1)[1][:-1].strip()
        if " — " in value:
            return value.split(" — ", 1)[0].strip()
        return value.strip()

    def _find_create_catalog_entry(self, entry_id: str | None = None, config: dict | None = None) -> dict | None:
        entry_id = str(entry_id or self._selected_create_catalog_entry_id()).strip()
        if not entry_id:
            return None
        config = config or self._current_create_config()
        catalogs = [self._selected_create_catalog_payload(config)]
        mode_catalog = self._create_mode_catalog(config)
        catalogs.extend([
            mode_catalog.get("active_catalog") or {},
            mode_catalog.get("new_project_abstraction") or {},
            mode_catalog.get("feature_for_existing_project") or {},
            mode_catalog.get("refactor_existing_stack") or {},
        ])
        seen: set[str] = set()
        for catalog in catalogs:
            entries = list(catalog.get("boilerplates") or catalog.get("chain_schema", {}).get("boilerplates", []) or [])
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                current_id = str(entry.get("id") or "").strip()
                if current_id in seen:
                    continue
                seen.add(current_id)
                if current_id == entry_id or self._create_catalog_entry_label(entry) == entry_id:
                    return dict(entry)
        return None

    def _create_essential_boilerplate_details(self, value: object, *, max_depth: int = 5, max_items: int = 80) -> object:
        """Recursively extract feature/refactor-relevant schema/boilerplate facts.

        This avoids copying Project Root settings wholesale. The overlay keeps only
        ids, labels, mode/routing, fields/tokens, dependencies, timeline,
        validation, operators/roles/references and target hints needed to build a
        Feature/Refactor prompt from the selected entry.
        """
        keep_keys = {
            "id", "label", "display_name", "mode", "modes", "group", "category", "intent", "template", "example",
            "fields", "tokens", "timeline_tokens", "validation_focus", "success_criteria", "steps", "rules",
            "operators", "roles", "references", "weights", "applies_to_domains", "applies_to_targets", "applies_to_path_types",
            "target", "path", "path_type", "build_target", "file_types", "dependencies", "dependency_layer", "artifacts",
            "parameter_context", "parameter_profile", "parameter_boilerplates", "chain_schema", "boilerplates",
            "schema_family", "specialization", "specialization_label", "overlay_scale", "overlay_scale_id",
            "overlay_contract_id", "chain_scope", "selector_policy", "source_policy", "resolution_order",
            "essential_extractors", "create_feature_refactor_specializations", "scale_values", "non_goals",
            "project_credit_contract", "project_credit_infoboxes", "credit_policy", "editable_fields", "comment_style", "insertion_policy", "duplicate_policy",
            "ptb_schema_alignment", "doc_structure", "update_plan_contract", "test_strategy", "resource_reuse_policy", "local_resource_detection",
            "software_documentation_ptb_schema", "test_plan_schema", "resource_reuse_schema",
        }
        scalar_types = (str, int, float, bool, type(None))
        seen = 0

        def visit(obj: object, depth: int) -> object:
            nonlocal seen
            if seen >= max_items:
                return "<truncated>"
            if isinstance(obj, scalar_types):
                return obj
            if depth <= 0:
                return "<max_depth>"
            if isinstance(obj, dict):
                seen += 1
                result: dict[str, object] = {}
                for key, item in obj.items():
                    key_s = str(key)
                    if key_s not in keep_keys and not any(key_s.endswith(suffix) for suffix in ("_id", "_ids", "_tokens", "_focus")):
                        continue
                    result[key_s] = visit(item, depth - 1)
                return result
            if isinstance(obj, (list, tuple, set)):
                seen += 1
                result = []
                for item in list(obj)[:max_items]:
                    result.append(visit(item, depth - 1))
                    if seen >= max_items:
                        result.append("<truncated>")
                        break
                return result
            return str(obj)

        return visit(value, max_depth)

    def _feature_refactor_overlay_scale(self) -> str:
        # Weight controls context budget/risk posture only. It must not multiply
        # catalog entries into pseudo-scale variants.
        return "bounded_change"

    def _create_feature_refactor_stack_overlay(self, entry: dict, config: dict | None = None) -> dict:
        config = config or self._current_create_config()
        evidence = self._create_project_evidence_payload(config)
        domains = self._create_plan_domains(evidence, config)
        chain_schema = config.get("create_chain_schema") or self._create_chain_schema(self.create_mode.get(), domains, config)
        stack_essentials = self._create_essential_boilerplate_details(config)
        entry_essentials = self._create_essential_boilerplate_details(entry)
        schema_essentials = self._create_essential_boilerplate_details(chain_schema)
        specialization_id = str(entry.get("specialization") or "").strip()
        specialization_schema = {}
        try:
            specialization_root = (self.schema.get("metadata", {}) or {}).get("create_feature_refactor_specializations", {}) or {}
            for item in specialization_root.get("specializations", []) or []:
                if isinstance(item, dict) and str(item.get("id") or "").strip() == specialization_id:
                    specialization_schema = item
                    break
        except Exception:
            specialization_schema = {}
        return {
            "schema_version": "feature-refactor-stack-overlay.v1",
            "mode": self.create_mode.get(),
            "scale": self._feature_refactor_overlay_scale(),
            "selected_entry_id": str(entry.get("id") or ""),
            "selected_entry_label": str(entry.get("display_name") or entry.get("label") or entry.get("id") or ""),
            "specialization": specialization_id,
            "specialization_label": str(entry.get("specialization_label") or specialization_schema.get("label") or ""),
            "overlay_scale": str(entry.get("overlay_scale") or self._feature_refactor_overlay_scale()),
            "overlay_contract_id": str(entry.get("overlay_contract_id") or ""),
            "source_policy": "Use Build.complete or Start/Create scanned project evidence; do not reuse Project Root settings from the stack boilerplate as write authority.",
            "add_selected_entry_integration": "This overlay is injected by Add selected entry into the Create Prompt tab and extends the selected template.",
            "domains": domains,
            "essential_stack_details": stack_essentials,
            "essential_entry_details": entry_essentials,
            "essential_chain_schema_details": schema_essentials,
            "essential_specialization_schema_details": self._create_essential_boilerplate_details(specialization_schema, max_depth=4, max_items=50),
            "project_evidence_summary": self._create_essential_boilerplate_details(evidence, max_depth=4, max_items=60),
            "required_resolution_order": [
                "resolve create parameters",
                "resolve selected entry fields/tokens",
                "resolve @target shortcuts from mapping/Build.complete manifest",
                "sort context by parameter intensity and domain relevance",
                "then generate changed-files-only Feature/Refactor instructions",
            ],
        }

    def _format_create_catalog_entry_for_prompt(self, entry: dict) -> str:
        fields = entry.get("fields") or []
        field_lines: list[str] = []
        for field in fields:
            if not isinstance(field, dict):
                continue
            field_id = str(field.get("id") or "").strip()
            if not field_id:
                continue
            default = field.get("default", "")
            options = field.get("options") or []
            if options:
                field_lines.append("- {$" + field_id + "}: " + "|".join(str(option) for option in options) + ((" | default=" + str(default)) if default != "" else ""))
            elif default != "":
                field_lines.append("- {$" + field_id + "}: default=" + str(default))
            else:
                field_lines.append("- {$" + field_id + "}: <setzen>")
        parts = [
            f"\n[CREATE CATALOG ENTRY: {entry.get('id')}]",
            f"Name: {entry.get('display_name') or entry.get('label') or entry.get('id')}",
            f"Mode: {self.create_mode.get()}",
            f"Context: {entry.get('context_hint') or '-'}",
            f"Intent: {entry.get('intent') or '-'}",
            "Template:",
            str(entry.get("template") or entry.get("example") or "").strip() or "-",
        ]
        for label, key in (
            ("User goal", "user_goal"),
            ("User-friendly summary", "user_friendly_summary"),
            ("Context alignment", "context_alignment"),
            ("Resolution order", "context_resolution_order"),
            ("Acceptance criteria", "acceptance_criteria"),
            ("Output contract", "output_contract"),
            ("Non-goals", "non_goals"),
            ("Professional guardrails", "professional_guardrails"),
            ("Source policy", "source_policy"),
            ("PTB schema alignment", "ptb_schema_alignment"),
            ("Documentation structure", "doc_structure"),
            ("Update plan contract", "update_plan_contract"),
            ("Test strategy", "test_strategy"),
            ("Resource reuse policy", "resource_reuse_policy"),
            ("Local resource detection", "local_resource_detection"),
        ):
            value = entry.get(key)
            if isinstance(value, list) and value:
                parts.append(label + ":")
                parts.extend("- " + str(item) for item in value[:10])
            elif isinstance(value, dict) and value:
                parts.append(label + ":")
                parts.append(json.dumps(value, indent=2, ensure_ascii=False))
            elif isinstance(value, str) and value.strip():
                parts.append(label + ": " + value.strip())
        if field_lines:
            parts.extend(["Fields:", *field_lines])
        tokens = [str(token) for token in entry.get("tokens", []) if str(token).strip()]
        if tokens:
            parts.append("Tokens: " + ", ".join(tokens))
        credit_contract = self._project_credit_contract_payload(self._current_create_config())
        if credit_contract and (str(entry.get("schema_family") or "") == "credits_to_project" or "credit" in str(entry.get("id") or "").lower()):
            parts.extend([
                "Project Credit Infobox Contract:",
                json.dumps(credit_contract, indent=2, ensure_ascii=False),
            ])
        if self.create_mode.get() in {"feature_for_existing_project", "refactor_existing_stack"}:
            try:
                overlay = self._create_feature_refactor_stack_overlay(entry)
                parts.extend([
                    "Feature/Refactor Stack Overlay:",
                    json.dumps(overlay, indent=2, ensure_ascii=False),
                ])
            except Exception as exc:
                parts.extend(["Feature/Refactor Stack Overlay:", f"overlay_unavailable: {exc}"])
        parts.append("[/CREATE CATALOG ENTRY]\n")
        return "\n".join(parts)

    def _ensure_last_git_commit_scan_for_current_selection(self, reason: str = "catalog_selection") -> None:
        try:
            entry = self._find_create_catalog_entry()
            include_last_git = self._entry_requires_last_git_commit_export(entry)
            if include_last_git:
                self._sync_last_git_commit_export_checkbox(True, reason=reason)
                self._ensure_create_last_git_commit_reference(reason=reason, force=False)
            else:
                # A Git/Last-Commit catalog entry is an auto-selected export hook.
                # When the user switches to a normal feature/refactor entry the
                # Export-tab checkbox must be cleared again so stale
                # LAST_GIT_COMMIT.json artifacts are not carried into unrelated
                # prompts/exports. Manual checkbox changes are still possible after
                # the selection settles.
                self._sync_last_git_commit_export_checkbox(False, reason=reason)
                self._update_create_git_reference_status(getattr(self, "_create_git_reference_payload", {}))
        except Exception as exc:
            try:
                self.create_git_reference_status.set(f"Last Git Commit: scan skipped ({exc})")
            except Exception:
                pass

    def _on_create_catalog_entry_selected(self, _event=None) -> None:
        self._ensure_last_git_commit_scan_for_current_selection("catalog_entry_selected")
        self._show_create_catalog_entry_preview()
        # LAST-GIT-COMMIT plan selection must be visible in Prompt Builder before
        # the next compile/preview, not only in the Create catalog details.
        self._schedule_prompt_builder_flow_refresh()
        self._schedule_create_preview_refresh()

    def _show_create_catalog_entry_preview(self) -> None:
        entry = self._find_create_catalog_entry()
        if self._entry_requires_last_git_commit_export(entry):
            self._sync_last_git_commit_export_checkbox(True, reason="catalog_entry_preview")
            self._ensure_create_last_git_commit_reference(reason="catalog_entry_preview", force=False)
        summary = "Catalog entry: none selected"
        preview = ""
        if entry:
            fields = ", ".join(str(field.get("id")) for field in entry.get("fields", []) if isinstance(field, dict) and field.get("id")) or "no fields"
            summary = f"Entry: {entry.get('display_name') or entry.get('label') or entry.get('id')} · {entry.get('context_hint') or entry.get('intent') or ''} | fields: {fields}"
            preview = json.dumps({
                "id": entry.get("id"),
                "label": entry.get("label"),
                "display_name": entry.get("display_name"),
                "context_hint": entry.get("context_hint"),
                "mode": self.create_mode.get(),
                "template": entry.get("template"),
                "fields": entry.get("fields", []),
                "tokens": entry.get("tokens", []),
                "timeline_tokens": entry.get("timeline_tokens", []),
                "validation_focus": entry.get("validation_focus", []),
                "specialization": entry.get("specialization"),
                "specialization_label": entry.get("specialization_label"),
                "overlay_scale": entry.get("overlay_scale"),
                "rules": entry.get("rules", []),
                "user_goal": entry.get("user_goal"),
                "user_friendly_summary": entry.get("user_friendly_summary"),
                "context_alignment": entry.get("context_alignment", []),
                "context_resolution_order": entry.get("context_resolution_order", []),
                "acceptance_criteria": entry.get("acceptance_criteria", []),
                "output_contract": entry.get("output_contract", []),
                "non_goals": entry.get("non_goals", []),
                "professional_guardrails": entry.get("professional_guardrails", []),
                "source_policy": entry.get("source_policy"),
                "ptb_schema_alignment": entry.get("ptb_schema_alignment", {}),
                "doc_structure": entry.get("doc_structure", []),
                "update_plan_contract": entry.get("update_plan_contract", {}),
                "test_strategy": entry.get("test_strategy", {}),
                "resource_reuse_policy": entry.get("resource_reuse_policy", {}),
                "local_resource_detection": entry.get("local_resource_detection", []),
                "project_credit_contract": self._project_credit_contract_payload(self._current_create_config()) if (str(entry.get("schema_family") or "") == "credits_to_project" or "credit" in str(entry.get("id") or "").lower()) else {},
            }, indent=2, ensure_ascii=False)
        self.create_catalog_entry_preview.set(summary[:280])
        widget = getattr(self, "create_catalog_entry_text", None)
        if widget is not None:
            try:
                widget.delete("1.0", "end")
                widget.insert("1.0", preview or "No mode-specific catalog entry selected.")
            except Exception:
                pass

    def _refresh_create_catalog_entry_menu(self) -> None:
        # No second catalog selector: the header Entry list always follows the active mode.
        self.create_catalog_scope.set("active")
        values = self._create_catalog_entry_options()
        box = getattr(self, "create_catalog_entry_box", None)
        if box is not None:
            try:
                box.configure(values=values, state=("readonly" if values else "disabled"))
            except Exception:
                pass
        for button_name in ("create_catalog_add_button", "create_catalog_token_button", "create_catalog_remove_button"):
            button = getattr(self, button_name, None)
            if button is not None:
                try:
                    button.configure(state=("normal" if values else "disabled"))
                except Exception:
                    pass
        if values and self.create_catalog_entry.get() not in values:
            self.create_catalog_entry.set(values[0])
            self._ensure_last_git_commit_scan_for_current_selection("catalog_entry_default")
            self._schedule_prompt_builder_flow_refresh()
        elif not values:
            self.create_catalog_entry.set("")
            self.create_catalog_entry_preview.set("Entry: no mode-specific catalog entries resolved")
            return
        self._show_create_catalog_entry_preview()

    def _insert_text_into_create_prompt(self, value: str) -> None:
        widget = getattr(self, "create_details_text", None)
        if widget is None or not value:
            return
        try:
            current = widget.get("1.0", "end-1c")
            prefix = "" if not current or current.endswith("\n") else "\n"
            widget.insert("end", prefix + value)
            widget.focus_set()
            self._schedule_create_preview_refresh()
        except Exception:
            pass

    def _insert_selected_create_catalog_entry(self) -> None:
        entry = self._find_create_catalog_entry()
        if not entry:
            self.create_catalog_entry_preview.set("Catalog entry: none selected")
            return
        self._insert_text_into_create_prompt(self._format_create_catalog_entry_for_prompt(entry))
        self._load_selected_catalog_entry_into_token_editor(seed=False)

    def _remove_selected_create_catalog_entry_from_prompt(self) -> None:
        entry = self._find_create_catalog_entry()
        if not entry:
            self.create_catalog_entry_preview.set("Catalog entry: none selected")
            return
        widget = getattr(self, "create_details_text", None)
        entry_id = str(entry.get("id") or "").strip()
        if widget is None or not entry_id:
            return
        marker_start = f"[CREATE CATALOG ENTRY: {entry_id}]"
        marker_end = "[/CREATE CATALOG ENTRY]"
        try:
            text = widget.get("1.0", "end-1c")
            start = text.rfind(marker_start)
            if start < 0:
                self.create_catalog_entry_preview.set(f"Entry not found in prompt: {entry_id}")
                return
            remove_start = text.rfind("\n", 0, start)
            if remove_start < 0:
                remove_start = 0
            end_marker = text.find(marker_end, start)
            if end_marker < 0:
                self.create_catalog_entry_preview.set(f"Entry block end missing: {entry_id}")
                return
            remove_end = end_marker + len(marker_end)
            while remove_end < len(text) and text[remove_end] in "\r\n":
                remove_end += 1
            new_text = text[:remove_start].rstrip() + (("\n" + text[remove_end:].lstrip("\r\n")) if text[:remove_start].strip() and text[remove_end:].strip() else text[remove_end:].lstrip("\r\n"))
            widget.delete("1.0", "end")
            widget.insert("1.0", new_text)
            widget.focus_set()
            self.create_catalog_entry_preview.set(f"Removed entry from prompt: {entry_id}")
            self._schedule_create_preview_refresh()
        except Exception as exc:
            self.create_catalog_entry_preview.set(f"Remove failed: {exc}")

    def _field_to_create_token(self, field: dict) -> str:
        field_id = str(field.get("id") or "").strip()
        if not field_id:
            return ""
        options = [str(option) for option in field.get("options", []) if str(option).strip()]
        if str(field.get("type") or "").lower() == "boolean":
            return "{$" + field_id + ":true|false}"
        if options:
            return "{$" + field_id + ":" + "|".join(options) + "}"
        return "{$" + field_id + "}"

    def _load_selected_catalog_entry_into_token_editor(self, seed: bool = True) -> None:
        entry = self._find_create_catalog_entry()
        if not entry:
            return
        preferred = ""
        for token in entry.get("tokens", []):
            token = str(token).strip()
            if token.startswith("{$"):
                preferred = token
                break
        if not preferred:
            for field in entry.get("fields", []):
                preferred = self._field_to_create_token(field) if isinstance(field, dict) else ""
                if preferred:
                    break
        if not preferred and entry.get("tokens"):
            preferred = str(entry.get("tokens", [""])[0]).strip()
        if preferred:
            self.create_token_key.set(preferred)
            value = str(entry.get("template") or entry.get("example") or entry.get("intent") or "").strip()
            self._set_create_token_value(value)
            if seed:
                self._save_create_token_editor_entry()
        self._refresh_create_token_editor(keep_current=True)

    def _normalize_create_token_key(self, value: str) -> str:
        token = str(value or "").strip()
        if not token:
            return ""
        if token.startswith("@"):
            return token
        if token.startswith("{$") and token.endswith("}"):
            return token
        token = token.strip("{} ")
        if token.startswith("$"):
            token = token[1:]
        return "{$" + token + "}"

    def _get_create_token_value(self) -> str:
        widget = getattr(self, "create_token_value_text", None)
        if widget is None:
            return ""
        try:
            return widget.get("1.0", "end").strip()
        except Exception:
            return ""

    def _set_create_token_value(self, value: str) -> None:
        widget = getattr(self, "create_token_value_text", None)
        if widget is None:
            return
        try:
            widget.delete("1.0", "end")
            widget.insert("1.0", str(value or ""))
        except Exception:
            pass

    def _create_placeholder_lines_with_update(self, key: str, value: str | None) -> list[str]:
        key = self._normalize_create_token_key(key)
        lines: list[str] = []
        replaced = False
        for line in self._editable_text_lines("create_placeholder_text", {}):
            if "=" not in line:
                if line.strip():
                    lines.append(line)
                continue
            old_key, old_value = line.split("=", 1)
            if old_key.strip() == key:
                replaced = True
                if value is not None:
                    lines.append(f"{key} = {value.strip()}")
            else:
                lines.append(f"{old_key.strip()} = {old_value.strip()}")
        if not replaced and value is not None and key:
            lines.append(f"{key} = {value.strip()}")
        return lines

    def _available_create_token_keys(self) -> list[str]:
        keys = set(self._create_placeholder_map().keys())
        config = self._current_create_config()
        mode_catalog = self._create_mode_catalog(config)
        schema = mode_catalog.get("chain_schema") or {}
        for token in schema.get("tokens", []) + schema.get("timeline_tokens", []):
            token = str(token).strip()
            if token:
                keys.add(token)
        for field in schema.get("fields", []):
            if isinstance(field, dict):
                token = self._field_to_create_token(field)
                if token:
                    keys.add(token)
        for entry in (mode_catalog.get("active_catalog", {}).get("boilerplates") or []):
            if isinstance(entry, dict):
                for token in entry.get("tokens", []) + entry.get("timeline_tokens", []):
                    token = str(token).strip()
                    if token:
                        keys.add(token)
        for hook in self._current_create_hook_rows():
            hook_id = str(hook.get("id") or "").strip()
            if hook_id:
                keys.add("{$hook[" + hook_id + "]}")
        return sorted(keys)

    def _refresh_create_token_editor(self, keep_current: bool = False) -> None:
        values = self._available_create_token_keys()
        box = getattr(self, "create_token_key_box", None)
        if box is not None:
            try:
                box.configure(values=values)
            except Exception:
                pass
        current = self.create_token_key.get().strip()
        if not keep_current and values and current not in values:
            self.create_token_key.set(values[0])
            self._load_selected_create_token()
        self._render_create_hook_tree()
        self.create_token_status.set(f"Token editor ready — {len(values)} token(s), {len(self._current_create_hook_rows())} hook(s)")

    def _load_selected_create_token(self) -> None:
        key = self._normalize_create_token_key(self.create_token_key.get())
        self.create_token_key.set(key)
        value = self._create_placeholder_map().get(key, "")
        if not value and key.startswith("@"):
            value = self._resolve_create_context_token(key)
        self._set_create_token_value(value)
        self.create_token_status.set(f"Loaded {key or 'token'}")

    def _suggest_create_token_key(self) -> None:
        # Keep free typing possible; do not auto-wrap until Save/Prompt.
        self.create_token_status.set("Token tip: type name, {$name}, @target/path or choose a catalog/hook token.")

    def _save_create_token_editor_entry(self) -> None:
        key = self._normalize_create_token_key(self.create_token_key.get())
        if not key:
            self.create_token_status.set("Token save skipped: key missing")
            return
        value = self._get_create_token_value()
        self.create_token_key.set(key)
        self._set_text_widget_lines("create_placeholder_text", self._create_placeholder_lines_with_update(key, value))
        self.create_token_status.set(f"Saved {key}")
        self._refresh_create_token_editor(keep_current=True)
        self._schedule_create_preview_refresh()

    def _delete_create_token_editor_entry(self) -> None:
        key = self._normalize_create_token_key(self.create_token_key.get())
        if not key:
            return
        self._set_text_widget_lines("create_placeholder_text", self._create_placeholder_lines_with_update(key, None))
        self._set_create_token_value("")
        self.create_token_status.set(f"Deleted {key}")
        self._refresh_create_token_editor()
        self._schedule_create_preview_refresh()

    def _insert_selected_create_token_to_prompt(self) -> None:
        key = self._normalize_create_token_key(self.create_token_key.get())
        if not key:
            return
        self.create_token_key.set(key)
        self._insert_text_into_create_prompt(key + " ")
        self.create_token_status.set(f"Injected {key} into Prompt")

    def _auto_seed_create_tokens(self) -> None:
        config = self._current_create_config()
        mode_catalog = self._create_mode_catalog(config)
        schema = mode_catalog.get("chain_schema") or {}
        updates = 0
        lines = self._editable_text_lines("create_placeholder_text", config.get("placeholders", {}))
        existing = self._create_placeholder_map()
        def add(key: str, value: str) -> None:
            nonlocal updates
            key = self._normalize_create_token_key(key)
            if key and key not in existing:
                lines.append(f"{key} = {value}")
                existing[key] = value
                updates += 1
        for field in schema.get("fields", []):
            if not isinstance(field, dict):
                continue
            key = self._field_to_create_token(field)
            default = field.get("default", "")
            desc = str(field.get("description") or field.get("type") or "set in prompt before export")
            add(key, str(default if default != "" else desc))
        for token in schema.get("timeline_tokens", []):
            add(str(token), "timeline token resolved by Create compiler when selected")
        for entry in schema.get("boilerplates", []):
            if isinstance(entry, dict):
                for token in entry.get("tokens", []):
                    if str(token).startswith("{$"):
                        add(str(token), str(entry.get("intent") or entry.get("label") or "catalog token"))
        self._set_text_widget_lines("create_placeholder_text", lines)
        self.create_token_status.set(f"Auto-created {updates} token(s) from active catalog")
        self._refresh_create_token_editor(keep_current=True)
        self._schedule_create_preview_refresh()

    def _current_create_hook_rows(self) -> list[dict]:
        config = self._current_create_config()
        profiles = {str(item) for item in config.get("profiles", [])}
        file_types = {str(item) for item in config.get("file_types", [])}
        path_type = str(config.get("path_type") or config.get("build_target") or self.create_build_target.get() or "wrapper")
        ai_target = str(config.get("ai_target") or "ChatGPT")
        rows: list[dict] = []
        fallback: list[dict] = []
        for hook in self.schema.get("hooks", []):
            if not isinstance(hook, dict):
                continue
            hook_ai = {str(item) for item in hook.get("ai_targets", [])}
            hook_paths = {str(item) for item in hook.get("target_path_types", [])}
            hook_profiles = {str(item) for item in hook.get("boilerplate_profiles", [])}
            hook_files = {str(item) for item in hook.get("file_types", [])}
            if hook_ai and ai_target not in hook_ai:
                continue
            item = dict(hook)
            fallback.append(item)
            matches = (not hook_paths or path_type in hook_paths) and (not hook_profiles or bool(profiles & hook_profiles) or "Create" in hook_profiles) and (not hook_files or bool(file_types & hook_files))
            if matches:
                rows.append(item)
        rows = rows or fallback[:30]
        return sorted(rows, key=lambda hook: (str(hook.get("lifecycle_phase") or ""), -int(hook.get("priority") or 0), str(hook.get("id") or "")))

    def _render_create_hook_tree(self) -> None:
        tree = getattr(self, "create_hook_tree", None)
        if tree is None:
            return
        rows = self._current_create_hook_rows()
        try:
            tree.delete(*tree.get_children())
            for hook in rows:
                hook_id = str(hook.get("id") or "").strip()
                label = str(hook.get("label") or hook_id)
                phase = str(hook.get("lifecycle_phase") or "")
                targets = ",".join(str(item) for item in hook.get("target_path_types", [])[:2]) or "any"
                tree.insert("", "end", iid=hook_id, text=hook_id, values=(phase, targets, label))
        except Exception:
            pass

    def _selected_create_hook(self) -> dict | None:
        tree = getattr(self, "create_hook_tree", None)
        if tree is None:
            return None
        try:
            selected = tree.selection()
        except Exception:
            selected = ()
        if not selected:
            return None
        hook_id = str(selected[0])
        for hook in self._current_create_hook_rows():
            if str(hook.get("id") or "") == hook_id:
                return dict(hook)
        return None

    def _hook_to_create_token_payload(self, hook: dict) -> tuple[str, str]:
        hook_id = str(hook.get("id") or "").strip()
        key = "{$hook[" + hook_id + "]}"
        value = json.dumps({
            "id": hook_id,
            "label": hook.get("label"),
            "lifecycle_phase": hook.get("lifecycle_phase"),
            "inject_into": hook.get("inject_into", []),
            "rules": hook.get("rules", []),
        }, ensure_ascii=False)
        return key, value

    def _load_selected_create_hook_into_editor(self) -> None:
        hook = self._selected_create_hook()
        if not hook:
            return
        key, value = self._hook_to_create_token_payload(hook)
        self.create_token_key.set(key)
        self._set_create_token_value(self._create_placeholder_map().get(key, value))
        self.create_token_status.set(f"Hook loaded: {hook.get('id')}")

    def _inject_selected_create_hook_token(self) -> None:
        hook = self._selected_create_hook()
        if not hook:
            self.create_token_status.set("No hook selected")
            return
        key, value = self._hook_to_create_token_payload(hook)
        self.create_token_key.set(key)
        self._set_create_token_value(value)
        self._save_create_token_editor_entry()
        self.create_token_status.set(f"Injected hook token {key}")

    def _compact_create_chain_schema_for_export(self, chain_schema: dict | None) -> dict:
        """Return the Create chain contract without dumping full boilerplate bodies."""
        schema = chain_schema if isinstance(chain_schema, dict) else {}
        fields: list[dict] = []
        for field in schema.get("fields", []) if isinstance(schema.get("fields"), list) else []:
            if not isinstance(field, dict):
                continue
            item = {
                "id": field.get("id"),
                "type": field.get("type"),
                "required": bool(field.get("required", False)),
            }
            if field.get("options"):
                item["options"] = list(field.get("options", []))
            if field.get("default") not in (None, ""):
                item["default"] = field.get("default")
            if field.get("description"):
                item["description"] = field.get("description")
            fields.append(item)
        controls_payload = schema.get("parameter_controls", {}) if isinstance(schema.get("parameter_controls"), dict) else {}
        controls: list[dict] = []
        for control in controls_payload.get("controls", []) if isinstance(controls_payload.get("controls"), list) else []:
            if isinstance(control, dict):
                controls.append({
                    "id": control.get("id"),
                    "label": control.get("label"),
                    "value": control.get("value"),
                    "min": control.get("min"),
                    "max": control.get("max"),
                    "enabled": bool(control.get("enabled", True)),
                })
        parameter_boilerplates: list[dict] = []
        for boilerplate in schema.get("parameter_boilerplates", []) if isinstance(schema.get("parameter_boilerplates"), list) else []:
            if isinstance(boilerplate, dict):
                parameter_boilerplates.append({
                    "id": boilerplate.get("id"),
                    "parameter_id": boilerplate.get("parameter_id"),
                    "label": boilerplate.get("label"),
                    "value": boilerplate.get("value"),
                    "max": boilerplate.get("max"),
                    "normalized": boilerplate.get("normalized"),
                    "context_bucket": boilerplate.get("context_bucket"),
                    "reference_id": boilerplate.get("reference_id") or boilerplate.get("active_reference_id"),
                    "operator_role_id": boilerplate.get("operator_role_id") or boilerplate.get("active_operator_role_id"),
                    "weight_operator_id": boilerplate.get("weight_operator_id") or boilerplate.get("active_weight_operator_id"),
                })
        compact_boilerplates: list[dict] = []
        for boilerplate in schema.get("boilerplates", []) if isinstance(schema.get("boilerplates"), list) else []:
            if not isinstance(boilerplate, dict):
                continue
            compact_boilerplates.append({
                "id": boilerplate.get("id"),
                "label": boilerplate.get("label"),
                "type": boilerplate.get("type"),
                "tokens": boilerplate.get("tokens", [])[:12] if isinstance(boilerplate.get("tokens"), list) else [],
                "timeline_tokens": boilerplate.get("timeline_tokens", [])[:12] if isinstance(boilerplate.get("timeline_tokens"), list) else [],
            })
            if len(compact_boilerplates) >= 24:
                break
        result = {
            "schema_version": schema.get("schema_version"),
            "mode": schema.get("mode"),
            "domains": schema.get("domains", []),
            "token_syntax": schema.get("token_syntax", {}),
            "fields": fields,
            "parameter_controls": {
                "mode": controls_payload.get("mode"),
                "enabled": bool(controls_payload.get("enabled", False)),
                "values": controls_payload.get("values", {}),
                "controls": controls,
            },
            "parameter_boilerplates": parameter_boilerplates,
            "project_credit_contract": schema.get("project_credit_contract", {}),
            "boilerplate_index": compact_boilerplates,
            "boilerplate_index_truncated": len(schema.get("boilerplates", []) if isinstance(schema.get("boilerplates"), list) else []) > len(compact_boilerplates),
        }
        return {key: value for key, value in result.items() if value not in (None, {}, [])}

    def _compact_create_mapping_for_export(self, mapping: dict | None) -> dict:
        mapping = mapping if isinstance(mapping, dict) else {}
        tree = mapping.get("tree_blueprint", []) if isinstance(mapping.get("tree_blueprint"), list) else []
        dependency = mapping.get("dependency_abstraction", []) if isinstance(mapping.get("dependency_abstraction"), list) else []
        return {
            "mode": mapping.get("mode"),
            "stack": mapping.get("stack"),
            "category": mapping.get("category"),
            "working_path": mapping.get("working_path"),
            "target_path": mapping.get("target_path"),
            "create_export_dir": mapping.get("create_export_dir"),
            "project_source_path": mapping.get("project_source_path"),
            "project_first": bool(mapping.get("project_first", False)),
            "path_type": mapping.get("path_type"),
            "build_target": mapping.get("build_target"),
            "ai_target": mapping.get("ai_target"),
            "file_types": mapping.get("file_types", []),
            "profiles": mapping.get("profiles", []),
            "references": mapping.get("references", []),
            "roles": mapping.get("roles", []),
            "detected_targets": mapping.get("detected_targets", []),
            "timeline": mapping.get("timeline", []),
            "expected_manifests": mapping.get("expected_manifests", []),
            "existing_manifests": mapping.get("existing_manifests", []),
            "package_control": mapping.get("package_control", {}),
            "operator_flow": mapping.get("operator_flow", {}),
            "operator_research_plan": mapping.get("operator_research_plan", {}),
            "terminal": mapping.get("terminal", {}),
            "tree_blueprint_count": len(tree),
            "tree_blueprint_preview": [
                {
                    "path": item.get("path"),
                    "kind": item.get("kind"),
                    "role": item.get("role"),
                    "effective_target": item.get("effective_target"),
                }
                for item in tree[:80]
                if isinstance(item, dict)
            ],
            "tree_blueprint_truncated": len(tree) > 80,
            "dependency_abstraction_count": len(dependency),
            "dependency_abstraction_preview": [
                {
                    "id": item.get("id"),
                    "label": item.get("label"),
                    "target": item.get("target"),
                    "ecosystem": item.get("ecosystem"),
                    "manifest_files": item.get("manifest_files", []),
                    "dependencies": item.get("dependencies", []),
                }
                for item in dependency[:20]
                if isinstance(item, dict)
            ],
        }

    def _compact_create_mode_catalog_for_export(self, catalog: dict | None) -> dict:
        """Keep Create export prompts bounded to actual selected/configured state."""
        catalog = catalog if isinstance(catalog, dict) else {}
        active = catalog.get("active_catalog", {}) if isinstance(catalog.get("active_catalog"), dict) else {}
        evidence = active.get("evidence", {}) if isinstance(active.get("evidence"), dict) else {}
        active_catalog = {
            "entry_mode": active.get("entry_mode"),
            "catalog_type": active.get("catalog_type"),
            "base_required": active.get("base_required"),
            "stack_boilerplate_allowed": active.get("stack_boilerplate_allowed"),
            "feature_refactor_overlay": active.get("feature_refactor_overlay"),
            "plans": active.get("plans", [])[:20] if isinstance(active.get("plans"), list) else [],
            "timeline": active.get("timeline", []),
            "weights": active.get("weights", []),
            "operators": active.get("operators", []),
            "prompt_rules": active.get("prompt_rules", []),
            "parameter_profile": active.get("parameter_profile", {}),
            "parameter_context": active.get("parameter_context", []),
            "boilerplate_count": len(active.get("boilerplates", []) if isinstance(active.get("boilerplates"), list) else []),
        }
        active_catalog = {key: value for key, value in active_catalog.items() if value not in (None, {}, [])}
        evidence_payload = {
            "source": evidence.get("source"),
            "source_base": evidence.get("source_base"),
            "has_build_complete": bool(evidence.get("has_build_complete", False)),
            "build_id": evidence.get("build_id"),
            "target_relations": evidence.get("target_relations", {}),
            "mapping": self._compact_create_mapping_for_export(evidence.get("mapping", {})),
        }
        return {
            "active_mode": catalog.get("active_mode"),
            "available_modes": catalog.get("available_modes", []),
            "active_catalog": active_catalog,
            "evidence": evidence_payload,
            "chain_schema": self._compact_create_chain_schema_for_export(catalog.get("chain_schema", {})),
            "parameter_context": catalog.get("parameter_context", []),
            "parameter_boilerplate_count": len(catalog.get("parameter_boilerplates", []) if isinstance(catalog.get("parameter_boilerplates"), list) else []),
            "mode_gate": catalog.get("mode_gate", {}),
        }

    def _ui_locale(self) -> str:
        raw = str(getattr(self, "ui_language", tk.StringVar(value="ENGLISH")).get() if hasattr(getattr(self, "ui_language", None), "get") else "ENGLISH").strip().upper()
        return "GERMAN" if raw.startswith("DE") or raw.startswith("GER") else "ENGLISH"

    def _locale_dir(self) -> Path:
        """Return the folder used for UI locale files.

        UI translations are intentionally loaded from locale/{LANG}.json so the
        interface can change language without touching AI_LANGUAGE or the
        export/generated English contract.
        """
        try:
            return Path(__file__).resolve().parent / "locale"
        except Exception:
            return Path("locale")

    def _load_ui_locale_bundle(self, language: str | None = None) -> dict:
        locale = str(language or self._ui_locale() or "ENGLISH").strip().upper()
        if locale.startswith("DE") or locale.startswith("GER"):
            locale = "GERMAN"
        elif locale != "ENGLISH":
            locale = "ENGLISH"
        cache = getattr(self, "_ui_locale_cache", None)
        if cache is None:
            self._ui_locale_cache = {}
            cache = self._ui_locale_cache
        if locale in cache:
            return cache[locale]
        path = self._locale_dir() / f"{locale}.json"
        bundle: dict = {"language": locale, "texts": {}}
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                bundle.update(loaded)
                if not isinstance(bundle.get("texts"), dict):
                    bundle["texts"] = {}
        except Exception:
            # Missing or malformed locale files must not break startup. ENGLISH
            # fallback stays identity-based.
            bundle = {"language": locale, "texts": {}}
        cache[locale] = bundle
        return bundle

    def _reload_ui_locale(self) -> None:
        self._ui_locale_bundle = self._load_ui_locale_bundle(self._ui_locale())

    def _ui_text(self, key: str, fallback: str | None = None) -> str:
        bundle = getattr(self, "_ui_locale_bundle", None)
        if not isinstance(bundle, dict) or str(bundle.get("language") or "").upper() != self._ui_locale():
            bundle = self._load_ui_locale_bundle(self._ui_locale())
            self._ui_locale_bundle = bundle
        texts = bundle.get("texts", {}) if isinstance(bundle, dict) else {}
        if isinstance(texts, dict) and key in texts:
            return str(texts.get(key) or fallback or key)
        return str(fallback if fallback is not None else key)

    def _localized_status_label(self, label: str) -> str:
        """Translate dynamic UI status/progress strings by locale keys.

        Loading-bar and worker messages are UI text, not generated/exported
        content. They are translated with exact keys first and then by stable
        phrase fragments so counters, paths and runtime details stay intact.
        """
        text = str(label or "")
        bundle = getattr(self, "_ui_locale_bundle", None)
        if not isinstance(bundle, dict) or str(bundle.get("language") or "").upper() != self._ui_locale():
            bundle = self._load_ui_locale_bundle(self._ui_locale())
            self._ui_locale_bundle = bundle
        texts = bundle.get("texts", {}) if isinstance(bundle, dict) else {}
        if not isinstance(texts, dict) or not text:
            return text
        exact = texts.get(text)
        if exact:
            return str(exact)
        # Translate common phrase fragments inside dynamic messages. Longest
        # fragments win so e.g. "tree-source switch complete" is handled
        # before the generic "complete" suffix.
        for source in sorted((str(k) for k in texts.keys() if isinstance(k, str) and len(str(k)) >= 4), key=len, reverse=True):
            try:
                target = str(texts.get(source) or "")
                if target and source in text and target != source:
                    text = text.replace(source, target)
            except Exception:
                continue
        return text

    def _ui(self, english: str, german: str | None = None) -> str:
        # Legacy helper retained for older call sites. New UI text should come
        # from locale/{LANG}.json via _ui_text().
        if self._ui_locale() == "GERMAN" and german is not None:
            return str(german)
        return self._ui_text(english, english)

    def _translate_single_widget_text(self, widget) -> None:
        try:
            text = widget.cget("text")
        except Exception:
            return
        if text in (None, ""):
            return
        # Preserve the original source key so switching back to ENGLISH is
        # deterministic even after the widget currently displays German text.
        source = getattr(widget, "_i18n_source_text", None)
        if not source:
            source = str(text)
            try:
                setattr(widget, "_i18n_source_text", source)
            except Exception:
                pass
        translated = self._ui_text(str(source), str(source))
        try:
            widget.configure(text=translated)
        except Exception:
            pass

    def _translate_notebook_tabs(self, notebook: ttk.Notebook) -> None:
        try:
            tabs = list(notebook.tabs())
        except Exception:
            return
        source_texts = getattr(notebook, "_i18n_tab_source_texts", None)
        if not isinstance(source_texts, dict):
            source_texts = {}
            try:
                setattr(notebook, "_i18n_tab_source_texts", source_texts)
            except Exception:
                pass
        for tab_id in tabs:
            try:
                current = notebook.tab(tab_id, "text")
            except Exception:
                continue
            source = source_texts.get(str(tab_id)) or current
            source_texts[str(tab_id)] = source
            try:
                notebook.tab(tab_id, text=self._ui_text(str(source), str(source)))
            except Exception:
                pass

    def _translate_treeview_headings(self, tree: ttk.Treeview) -> None:
        source_headings = getattr(tree, "_i18n_heading_source_texts", None)
        if not isinstance(source_headings, dict):
            source_headings = {}
            try:
                setattr(tree, "_i18n_heading_source_texts", source_headings)
            except Exception:
                pass
        try:
            columns = list(tree.cget("columns") or [])
        except Exception:
            columns = []
        if not columns:
            columns = ["#0"]
        for column in columns:
            try:
                current = tree.heading(column).get("text", "")
            except Exception:
                continue
            source = source_headings.get(str(column)) or current or str(column)
            source_headings[str(column)] = source
            try:
                tree.heading(column, text=self._ui_text(str(source), str(source)))
            except Exception:
                pass

    def _translate_widget_tree(self, widget) -> None:
        self._translate_single_widget_text(widget)
        if isinstance(widget, ttk.Notebook):
            self._translate_notebook_tabs(widget)
        if isinstance(widget, ttk.Treeview):
            self._translate_treeview_headings(widget)
        try:
            for child in widget.winfo_children():
                self._translate_widget_tree(child)
        except Exception:
            pass

    def _apply_ui_locale(self) -> None:
        """Apply UI-language JSON translations to existing widgets.

        This affects interface labels/buttons/tabs only. It deliberately does
        not alter AI_LANGUAGE, generated prompt language, or export sidecars.
        """
        try:
            self._reload_ui_locale()
            self._translate_widget_tree(self)
        except Exception:
            pass

    def _export_generated_language(self) -> str:
        """Exports, generated prompts and machine sidecars are always English.

        AI_LANGUAGE remains untouched and only tells the receiving AI which
        language it should use in its own answer. Human-normalisation helpers
        may still call _human_prompt_text() without this override to vary text
        naturally according to AI_LANGUAGE.
        """
        return "ENGLISH"

    def _human_normalization_language(self) -> str:
        return self._human_prompt_locale()

    def _create_export_intelligence_value(self) -> str:
        var = getattr(self, "create_export_intelligence", None)
        raw_value = var.get() if var is not None else "medium"
        raw = str(raw_value or "medium").strip().lower()
        alias = {"low": "niedrig", "medium": "mittel", "mid": "mittel", "high": "hoch", "niedrig": "niedrig", "mittel": "mittel", "hoch": "hoch", "niederig": "niedrig"}
        return alias.get(raw, "mittel")

    def _create_high_export_intelligence_enabled(self) -> bool:
        return self._create_export_intelligence_value() == "hoch"

    def _create_export_absolute_paths_enabled(self) -> bool:
        var = getattr(self, "create_export_absolute_paths", None)
        try:
            return bool(var.get()) if var is not None else False
        except Exception:
            return False

    def _create_export_path_policy_payload(self, base: Path | str | None = None) -> dict:
        try:
            project_root = Path(str(base or self._create_working_dir())).resolve()
        except Exception:
            project_root = Path(str(base or "."))
        absolute_enabled = self._create_export_absolute_paths_enabled()
        return {
            "absolute_project_paths": absolute_enabled,
            "project_root": str(project_root),
            "compiled_path_format": "absolute_project_path" if absolute_enabled else "project_relative_path",
            "relative_traceability": "relative_* fields preserve project-relative originals when absolute_project_paths is true",
            "zip_member_policy": "ZIP members remain project-relative for portable archives; manifests/prompts may compile absolute project paths by checkbox",
        }

    def _compile_project_path_for_export(self, value: object, base: Path | str | None = None) -> str:
        text = str(value or "").replace("\\", "/").strip()
        if not text:
            return text
        if not self._create_export_absolute_paths_enabled():
            return text
        if text.startswith("@") or "://" in text:
            return text
        candidate = Path(text)
        if candidate.is_absolute():
            return str(candidate)
        try:
            root = Path(str(base or self._create_working_dir())).resolve()
        except Exception:
            root = Path(str(base or "."))
        clean = text.strip("/") or "."
        if clean == ".":
            return str(root)
        try:
            return str((root / clean).resolve())
        except Exception:
            return str(root / clean)

    def _compile_project_paths_for_export(self, values: object, base: Path | str | None = None) -> object:
        if isinstance(values, list):
            return [self._compile_project_path_for_export(item, base) for item in values]
        if isinstance(values, tuple):
            return [self._compile_project_path_for_export(item, base) for item in values]
        return self._compile_project_path_for_export(values, base)

    def _human_prompt_locale(self, language: str | None = None) -> str:
        lang_var = getattr(self, "ai_language", None)
        raw_value = language or (lang_var.get() if lang_var is not None else "GERMAN")
        raw = str(raw_value or "GERMAN").strip().upper()
        return "ENGLISH" if raw.startswith("EN") else "GERMAN"

    def _human_prompt_locale_rows(self, key: str) -> list[dict]:
        rows = self.schema.get(key, []) if isinstance(getattr(self, "schema", {}), dict) else []
        return [dict(item) for item in rows if isinstance(item, dict)]

    def _human_prompt_text(self, text_id: str, *, language: str | None = None, **values: object) -> str:
        locale = self._human_prompt_locale(language)
        fallback_locale = "ENGLISH"
        for item in self._human_prompt_locale_rows("human_prompt_texts"):
            if str(item.get("id") or "") != text_id:
                continue
            translations = item.get("translations", {}) if isinstance(item.get("translations"), dict) else {}
            template = str(translations.get(locale) or translations.get(fallback_locale) or item.get("text") or "").strip()
            if not template:
                break
            safe_values = {key: str(value) for key, value in values.items()}
            try:
                return self._with_brutally_honest_intro(text_id, template.format(**safe_values), language)
            except Exception:
                return self._with_brutally_honest_intro(text_id, template, language)
        defaults = {
            "prompt_intro": "This is a human-compiled Create prompt. Use the manifests as evidence, but execute according to this prompt.",
            "operator_confirm_then_execute": "List the active roles first and wait for confirmation before implementation.",
            "operator_start_immediately": "You may start directly with the selected roles.",
            "operator_sequential_roles": "Process roles and references sequentially and keep the order visible.",
            "research_required": "Research active roles and references before implementation and record reliable sources, or explain why no research was needed.",
            "research_not_required": "Mandatory per-role research is not enabled; still verify uncertain or time-sensitive facts.",
            "chain_intro": "The following schema chain is compiled as a human work reference. Use it as logic, not as raw configuration.",
            "validation_intro": "Accept the result only when goal, scope, changed files, validation, rollback and known gaps are traceable.",
        }
        return self._with_brutally_honest_intro(text_id, defaults.get(text_id, text_id).format(**{key: str(value) for key, value in values.items()}), language)

    def _export_human_prompt_text(self, text_id: str, **values: object) -> str:
        return self._human_prompt_text(text_id, language=self._export_generated_language(), **values)

    def _brutally_honest_intro_enabled(self) -> bool:
        var = getattr(self, "export_brutally_honest", None)
        try:
            return bool(var.get()) if var is not None else False
        except Exception:
            return False

    def _brutally_honest_intro_prefix(self, language: str | None = None) -> str:
        if not self._brutally_honest_intro_enabled():
            return ""
        locale = self._human_prompt_locale(language)
        if locale == "GERMAN":
            return "Sei brutal ehrlich: benenne Risiken, fehlende Evidenz, schwache Annahmen und Known Gaps ohne Beschönigung."
        return "Be brutally honest: name risks, missing evidence, weak assumptions and known gaps without softening them."

    def _is_human_api_intro_text_id(self, text_id: str) -> bool:
        token = str(text_id or "").lower()
        return token.endswith("_intro") or "intro" in token or token.startswith("surface_") or token in {
            "prompt_intro",
            "tab_control_intro",
            "prompt_builder_tab_context",
            "manifest_guided_intro",
            "recursive_manifest_processing",
            "role_planning_intro",
            "export_intelligence_context",
        }

    def _with_brutally_honest_intro(self, text_id: str, value: str, language: str | None = None) -> str:
        prefix = self._brutally_honest_intro_prefix(language)
        if prefix and self._is_human_api_intro_text_id(text_id) and value and not value.startswith(prefix):
            return f"{prefix} {value}"
        return value

    def _export_intelligence_profile(self, level: str | None = None) -> dict:
        level = str(level or self._create_export_intelligence_value()).strip().lower()
        for item in self._human_prompt_locale_rows("export_intelligence_profiles"):
            if str(item.get("id") or "").strip().lower() == level:
                return dict(item)
        defaults = {
            "niedrig": {"id": "niedrig", "label": "Low", "description": "Compact handoff with selected plan, declared manifest files and hard rules.", "chain_entry_limit": 1, "include_available_entries": False, "include_roles": False, "include_parameter_context": False, "include_tree_preview": False, "rule_limit": 6, "detail_limit": 2},
            "mittel": {"id": "mittel", "label": "Medium", "description": "Standard handoff with selected plan, roles, references, manifest purpose, scope recursion and validation text.", "chain_entry_limit": 8, "include_available_entries": False, "include_roles": True, "include_parameter_context": True, "include_tree_preview": True, "rule_limit": 10, "detail_limit": 4},
            "hoch": {"id": "hoch", "label": "High", "description": "Detailed handoff with manifest-faithful explanation, roles, references, recursive scope, parameters, validation and known-gap contract.", "chain_entry_limit": 30, "include_available_entries": False, "include_roles": True, "include_parameter_context": True, "include_tree_preview": True, "rule_limit": 20, "detail_limit": 8},
        }
        return defaults.get(level, defaults["mittel"])

    def _humanize_prompt_value(self, value: object) -> str:
        text = str(value or "").replace("\r", "").strip()
        replacements = {
            "{$write_project_mapping}": "Projekt-Mapping schreiben",
            "{$write_dependency_layer}": "Dependency-Layer schreiben",
            "{$compiler_run}": "run compiler or validation pass",
            "{$write_export_manifest}": "Export-Manifest schreiben",
            "{$apply_temp_tree_to_working_path}": "Temp-Baum kontrolliert auf den Arbeitsstand anwenden",
            "{$write_temp_project_tree}": "write temporary project tree",
            "{$ptb_schema_profile}": "PTB-Schema-Profil",
            "{$update_scope}": "Aktualisierungsumfang",
            "{$test_goal}": "Testziel",
            "{$test_framework_policy}": "Testframework-Regel",
            "{$resource_reuse_scope}": "Wiederverwendungs-Scope",
            "{$credit_project}": "Projektname",
            "{$credit_owner}": "Owner",
            "{$credit_year}": "Jahr",
            "{$credit_license}": "Lizenz",
            "{$credit_meta_summary}": "Kurzbeschreibung",
        }
        for raw, human in replacements.items():
            text = text.replace(raw, human)
        text = re.sub(r"\{\$([^}:|]+)(?::([^}]+))?\}", lambda m: (m.group(1) or "").replace("_", " "), text)
        text = text.replace("@backend/path", "Backend-Pfad").replace("@frontend/path", "Frontend-Pfad").replace("@wrapper/path", "Wrapper-Pfad").replace("@assets/path", "Assets-Pfad")
        return text.strip()

    def _human_list_lines(self, values: object, *, prefix: str = "-", limit: int = 6) -> list[str]:
        if isinstance(values, dict):
            iterable = [f"{key}: {value}" for key, value in values.items() if value not in (None, "", [], {})]
        elif isinstance(values, list):
            iterable = values
        elif values in (None, "", [], {}):
            iterable = []
        else:
            iterable = [values]
        lines: list[str] = []
        for item in iterable[:max(limit, 0)]:
            if isinstance(item, dict):
                label = item.get("label") or item.get("id") or item.get("name") or "Eintrag"
                rest = item.get("description") or item.get("purpose") or item.get("value") or ""
                text = f"{label}: {rest}" if rest else str(label)
            else:
                text = str(item)
            text = self._humanize_prompt_value(text)
            if text:
                lines.append(f"{prefix} {text}")
        return lines

    def _prompt_tab_mapping_chaining_enabled(self, config: dict | None = None) -> bool:
        """Return whether USER_PROMPT may include chain entries beyond the selected one.

        Export intelligence controls detail depth, not catalog activation.  Extra
        Feature/Refactor plan references are only legitimate when the Create tab
        provides an explicit Prompt-tab mapping chain.  Without that mapping the
        USER_PROMPT must stay scoped to the single selected catalog entry.
        """
        config = config if isinstance(config, dict) else {}
        truthy = {"1", "true", "yes", "yes", "on", "enabled", "active"}
        for key in (
            "prompt_tab_mapping_chaining",
            "prompt_mapping_chaining",
            "create_prompt_tab_mapping_chaining",
            "mapping_chaining_enabled",
            "prompt_builder_mapping_chaining",
            "include_available_chain_entries",
            "export_available_chain_entries",
        ):
            if key in config:
                value = config.get(key)
                if isinstance(value, bool):
                    return value
                if str(value).strip().lower() in truthy:
                    return True
        for key in ("prompt_tab_mapping", "prompt_builder_mapping", "create_prompt_tab_mapping"):
            payload = config.get(key)
            if isinstance(payload, dict):
                for flag in ("chain_enabled", "chaining_enabled", "mapping_chaining", "include_chain_entries", "enabled"):
                    value = payload.get(flag)
                    if isinstance(value, bool):
                        return value
                    if str(value).strip().lower() in truthy:
                        return True
        for attr in (
            "prompt_tab_mapping_chaining",
            "prompt_builder_mapping_chaining",
            "create_prompt_tab_mapping_chaining",
        ):
            var = getattr(self, attr, None)
            if var is None:
                continue
            try:
                value = var.get()
            except Exception:
                value = var
            if isinstance(value, bool):
                return value
            if str(value).strip().lower() in truthy:
                return True
        return False

    def _prompt_tab_mapped_chain_entry_ids(self, config: dict | None = None) -> list[str]:
        """Return explicitly mapped chain-entry ids from Prompt-tab chaining config."""
        config = config if isinstance(config, dict) else {}
        buckets: list[object] = []
        for key in (
            "prompt_tab_mapping_chain_entry_ids",
            "mapped_chain_entry_ids",
            "chain_entry_ids",
            "prompt_builder_chain_entry_ids",
        ):
            if key in config:
                buckets.append(config.get(key))
        for key in ("prompt_tab_mapping", "prompt_builder_mapping", "create_prompt_tab_mapping"):
            payload = config.get(key)
            if isinstance(payload, dict):
                for subkey in ("chain_entry_ids", "mapped_chain_entry_ids", "entries", "chains", "chain"):
                    if subkey in payload:
                        buckets.append(payload.get(subkey))
        ids: list[str] = []

        def add(value: object) -> None:
            if isinstance(value, dict):
                for key in ("id", "entry_id", "chain_entry_id", "source", "target"):
                    text = str(value.get(key) or "").strip()
                    if text:
                        ids.append(text)
                for nested_key in ("entries", "chain", "chains"):
                    nested = value.get(nested_key)
                    if nested is not value:
                        add(nested)
            elif isinstance(value, (list, tuple, set)):
                for item in value:
                    add(item)
            else:
                text = str(value or "").strip()
                if text:
                    for part in re.split(r"[,;\s]+", text):
                        clean = part.strip()
                        if clean:
                            ids.append(clean)

        for bucket in buckets:
            add(bucket)
        return self._dedupe_create_list(ids)

    def _human_selected_chain_entries(self, chain_schema: dict, selected_entry: dict | None, profile: dict, config: dict | None = None) -> list[dict]:
        entries = [entry for entry in chain_schema.get("boilerplates", []) if isinstance(entry, dict)] if isinstance(chain_schema, dict) else []
        selected_id = str((selected_entry or {}).get("id") or "").strip()
        if selected_entry:
            selected = [entry for entry in entries if str(entry.get("id") or "").strip() == selected_id] or [selected_entry]
        else:
            selected = []

        # USER_PROMPT is an execution handoff, not a catalog browser.  Even at
        # high export intelligence it must not export unrelated Feature/Refactor
        # catalog entries.  Additional chain references are only allowed when the
        # Create-tab Prompt-tab mapping explicitly chains concrete entry ids.
        if not self._prompt_tab_mapping_chaining_enabled(config):
            return selected[:1] if selected else []

        mapped_ids = [item for item in self._prompt_tab_mapped_chain_entry_ids(config) if item and item != selected_id]
        if not mapped_ids:
            return selected[:1] if selected else []
        by_id = {str(entry.get("id") or "").strip(): entry for entry in entries}
        mapped = [by_id[item] for item in mapped_ids if item in by_id]
        limit = max(int(profile.get("chain_entry_limit", 8) or 8), 1)
        return (selected[:1] + mapped)[:limit]

    def _compile_human_chain_entry_lines(self, entry: dict, *, profile: dict, selected: bool = False) -> list[str]:
        detail_limit = int(profile.get("detail_limit", 4) or 4)
        label = self._humanize_prompt_value(entry.get("display_name") or entry.get("label") or entry.get("id") or "Plan")
        entry_id = str(entry.get("id") or "").strip()
        header = f"### {'Selected plan' if selected else 'Plan reference'}: {label}"
        lines = [header]
        if entry_id:
            lines.append("- Manifest reference: the exact schema entry remains machine-readable in the declared manifest files; this section translates only the actually available fields into human work logic.")
        for key, title in [
            ("user_goal", "Ziel"),
            ("context_hint", "Kontexthinweis"),
            ("intent", "Absicht"),
            ("source_policy", "Source rule"),
        ]:
            value = self._humanize_prompt_value(entry.get(key) or "")
            if value:
                lines.append(f"- {title}: {value}")
        fields = entry.get("fields", []) if isinstance(entry.get("fields"), list) else []
        if fields:
            lines.append("- Required inputs:")
            for field in fields[:detail_limit]:
                if not isinstance(field, dict):
                    continue
                fid = self._humanize_prompt_value(field.get("id") or "Feld")
                desc = self._humanize_prompt_value(field.get("description") or field.get("label") or "")
                required = "pflicht" if field.get("required") else "optional"
                option_text = ""
                if isinstance(field.get("options"), list) and field.get("options"):
                    option_text = " Optionen: " + ", ".join(self._humanize_prompt_value(item) for item in field.get("options", [])[:6])
                lines.append(f"  - {fid} ({required})" + (f": {desc}" if desc else "") + option_text)
        for key, title in [
            ("context_alignment", "Kontextbindung"),
            ("context_resolution_order", "Context resolution order"),
            ("acceptance_criteria", "Akzeptanzkriterien"),
            ("validation_focus", "Validierungsfokus"),
            ("output_contract", "Ausgabe-/Exportvertrag"),
            ("non_goals", "Nicht-Ziele"),
            ("professional_guardrails", "Guardrails"),
            ("rules", "Regeln"),
            ("doc_structure", "Dokumentationsstruktur"),
            ("local_resource_detection", "Lokale Ressourcen-Erkennung"),
        ]:
            values = entry.get(key, [])
            item_lines = self._human_list_lines(values, prefix="  -", limit=detail_limit)
            if item_lines:
                lines.append(f"- {title}:")
                lines.extend(item_lines)
        for key, title in [
            ("ptb_schema_alignment", "PTB-/Schema-Ausrichtung"),
            ("update_plan_contract", "Aktualisierungsplan"),
            ("test_strategy", "Teststrategie"),
            ("resource_reuse_policy", "Ressourcen-Wiederverwendung"),
        ]:
            payload = entry.get(key, {})
            item_lines = self._human_list_lines(payload, prefix="  -", limit=detail_limit)
            if item_lines:
                lines.append(f"- {title}:")
                lines.extend(item_lines)
        template = self._humanize_prompt_value(entry.get("template") or "")
        if template and profile.get("id") == "hoch":
            lines.append("- Human-compiled template:")
            for line in template.splitlines()[:10]:
                clean = self._humanize_prompt_value(line)
                if clean:
                    lines.append(f"  {clean}")
        return lines

    def _declared_human_export_files(self, config: dict | None = None, profile: dict | None = None) -> list[tuple[str, str]]:
        """Return only real export files that the USER_PROMPT may mention.

        Create-specific context is consolidated into the existing EXPORT_MANIFEST.json
        and PROMPT_MANIFEST.json. Do not reintroduce duplicate create-specific sidecars
        for prompt, mapping, dependency, target or export data.
        """
        compact_var = getattr(self, "create_compact_export", None)
        zip_var = getattr(self, "create_export_as_zip", None)
        compact = bool(compact_var.get()) if compact_var is not None else False
        export_as_zip = bool(zip_var.get()) if zip_var is not None else False
        rows: list[tuple[str, str]] = []
        try:
            include_last_git = self._create_should_include_last_git_commit_reference(config if isinstance(config, dict) else None)
        except Exception:
            include_last_git = False
        if compact and export_as_zip:
            rows.append(("*_compact_context.zip", "contains the recursively assembled project files and control artifacts of the compact export"))
        rows.extend([
            ("USER_PROMPT.txt", "human-compiled work instruction; no raw configuration and no full ID list"),
            ("EXPORT_MANIFEST.json", "authoritative file, scope and export truth; contains consolidated Create export context instead of separate create-specific duplicate manifests"),
            ("PROMPT_MANIFEST.json", "machine-readable prompt, chain, role, target, mapping and dependency layer; technical details stay there and are only introduced readably in USER_PROMPT"),
            ("CMD.json", "compact machine-readable CMD contract for START, RESTART, REFACTOR, SKIP, EXTEND, SHRINK, FIX and STATUS"),
            ("PROMPT_EVAL_CHECKLIST.md", "checkable prompt and execution acceptance"),
        ])
        if compact:
            rows.extend([
                ("EXPORT_CONDITIONS.json", "maschinenlesbare Exportbedingungen, Kontextauswahl, Operator-Flow und Detailstufe des Kompakt-Exports"),
                ("ROLE_OPERATOR_BOILERPLATE_MANIFEST.json", "machine-readable role, reference, boilerplate and weighting assignment for execution"),
                ("PROJECT_TREE.md", "human-readable project-tree overview from the exported scope"),
                ("CREATE_WORKING_TREE.md", "human-readable Create working tree when a Create context is included in the compact export"),
            ])
        if include_last_git:
            rows.append(("LAST_GIT_COMMIT.json", "read-only Git reference with last commit, changed file titles and descriptions when LAST-GIT-COMMIT is enabled"))
        if self._prompt_builder_custom_task_text().strip():
            rows.append(("TASKS.TXT", "Prompt Builder CUSTOM_USER_PROMPT as normalized task/phase sidecar file outside the ZIP/folder output"))
        seen: set[str] = set()
        unique: list[tuple[str, str]] = []
        for name, description in rows:
            key = str(name).strip()
            if not key or key in seen:
                continue
            seen.add(key)
            unique.append((key, str(description).strip()))
        return unique

    def _manifest_names_for_human_prompt(self, config: dict | None = None, profile: dict | None = None) -> list[str]:
        return [name for name, _description in self._declared_human_export_files(config, profile) if name.endswith((".json", ".md", ".txt")) or "*" in name]

    def _schema_lookup_row(self, rows_key: str, item_id: str) -> dict:
        needle = str(item_id or "").strip()
        if not needle:
            return {}
        for row in self._human_prompt_locale_rows(rows_key):
            if str(row.get("id") or "").strip() == needle:
                return row
        return {}

    def _schema_row_human_summary(self, row: dict, *, profile: dict, kind: str) -> list[str]:
        label = self._humanize_prompt_value(row.get("label") or row.get("name") or row.get("id") or kind)
        category = self._humanize_prompt_value(row.get("category") or "")
        head = label + (f" ({category})" if category else "")
        lines = [f"  - {head}"]
        limit = max(1, int(profile.get("detail_limit", 4) or 4))
        if str(profile.get("id") or "") in {"mittel", "hoch"}:
            rules = row.get("rules") if isinstance(row.get("rules"), list) else []
            guardrails = row.get("guardrails") if isinstance(row.get("guardrails"), list) else []
            validation_focus = row.get("validation_focus") if isinstance(row.get("validation_focus"), list) else []
            source_refs = row.get("source_refs") if isinstance(row.get("source_refs"), list) else []
            for title, values, max_items in [
                ("Execution rule", rules, 2 if str(profile.get("id") or "") == "mittel" else min(limit, 4)),
                ("Guardrail", guardrails, 1 if str(profile.get("id") or "") == "mittel" else min(limit, 4)),
                ("Validierungsfokus", validation_focus, 1 if str(profile.get("id") or "") == "mittel" else min(limit, 4)),
            ]:
                clean_values = [self._humanize_prompt_value(item) for item in values[:max_items] if self._humanize_prompt_value(item)]
                if clean_values:
                    lines.append(f"    - {title}: " + "; ".join(clean_values))
            if str(profile.get("id") or "") == "hoch" and source_refs:
                labels = []
                for ref in source_refs[:3]:
                    if isinstance(ref, dict):
                        label = self._humanize_prompt_value(ref.get("label") or ref.get("url") or "")
                        authority = self._humanize_prompt_value(ref.get("authority") or "")
                        labels.append(label + (f" ({authority})" if authority else ""))
                if labels:
                    lines.append("    - Sourcenhinweis: " + "; ".join(labels))
        return lines

    def _human_role_reference_planning_lines(self, config: dict, profile: dict) -> list[str]:
        if not bool(profile.get("include_roles", False)):
            return []
        role_ids = [str(item).strip() for item in (config.get("roles", []) if isinstance(config, dict) else []) if str(item).strip()]
        ref_ids = [str(item).strip() for item in (config.get("references", []) if isinstance(config, dict) else []) if str(item).strip()]
        limit = max(1, int(profile.get("role_reference_limit", profile.get("detail_limit", 4)) or 4))
        lines = [
            "## Operator-, Rollen- und Referenzplanung",
            self._export_human_prompt_text("role_planning_intro"),
        ]
        if role_ids:
            lines.append(f"- Active roles: {len(role_ids)}. The following descriptions are compiled from the declared role schemas; the exact keys are in the manifest files.")
            for role_id in role_ids[:limit]:
                row = self._schema_lookup_row("operation_roles", role_id)
                if row:
                    lines.extend(self._schema_row_human_summary(row, profile=profile, kind="Rolle"))
                elif str(profile.get("id") or "") == "hoch":
                    lines.append("  - Unresolved role from manifest: treat as known gap, do not describe or invent.")
            if len(role_ids) > limit:
                lines.append(f"  - Additional {len(role_ids) - limit} roles are manifested and must be read from ROLE_OPERATOR_BOILERPLATE_MANIFEST.json if needed.")
        else:
            lines.append("- No active role resolved in the current export context; treat this as a known gap if the task requires role guidance.")
        if ref_ids:
            lines.append(f"- Active reference domains: {len(ref_ids)}. They serve as context and quality frame, not as invented additional requirements.")
            for ref_id in ref_ids[:limit]:
                row = self._schema_lookup_row("reference_domains", ref_id)
                if row:
                    lines.extend(self._schema_row_human_summary(row, profile=profile, kind="Referenz"))
                elif str(profile.get("id") or "") == "hoch":
                    lines.append("  - Unresolved reference from manifest: treat as known gap, do not describe or invent.")
            if len(ref_ids) > limit:
                lines.append(f"  - Additional {len(ref_ids) - limit} Referenzen sind manifestiert und bleiben in den Manifestdateien nachlesbar.")
        lines.append(self._export_human_prompt_text("declared_only_text_rule"))
        return lines

