    def _create_cmd_manifest_payload(self, config: dict | None = None) -> dict:
        """Build the machine-readable USER_PROMPT shortcut command manifest.

        CMD.json is an export hook, not a Create catalog entry. The receiving AI
        may apply these commands immediately, but the commands never expand
        safety, filesystem, tool, repository or validation boundaries.
        """
        commands = self._shortcut_command_definitions()
        return {
            "artifact": "CMD.json",
            "schema_version": "2026.create.cmd_manifest.v1",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "owner": "USER_PROMPT export hook",
            "not_create_catalog_entry": True,
            "not_user_selectable": True,
            "commands": commands,
            "command_names": [item.get("command") for item in commands],
            "shared_surfaces": [
                "USER_PROMPT.txt",
                "Prompt Builder preview",
                "Create Preview pipeline config",
                "EXPORT_MANIFEST.json",
                "PROMPT_MANIFEST.json",
                "CMD.json",
            ],
            "guardrails": [
                "Commands do not change tool rights, repository access, safety limits, scope or validation boundaries.",
                "Commands operate only on the current task, the last patch, or the actually available session context as declared per command.",
                "STATUS must never invent missing chat history, files or success metrics.",
            ],
            "selected_chain_entry": (config or {}).get("selected_create_chain_entry") if isinstance(config, dict) else None,
        }

    def _human_shortcut_command_contract_lines(self) -> list[str]:
        lines = [
            "Shortcuts are binding user CMDs in USER_PROMPT and mirrored machine-readably in CMD.json. When the user sends one of these commands, its meaning applies immediately to the next response or last patch; they still do not change access permissions, tool rights or validation boundaries.",
        ]
        for item in self._shortcut_command_definitions():
            lines.append(f"- {item.get('command')}: {item.get('instruction')} Guardrail: {item.get('guardrail')}")
        return lines

    def _human_operator_flow_lines(self, operator_flow: dict, profile: dict) -> list[str]:
        mode = str(operator_flow.get("execution_mode") or "confirm_then_execute")
        flow_key = {
            "confirm_then_execute": "operator_confirm_then_execute",
            "start_immediately": "operator_start_immediately",
            "sequential_roles": "operator_sequential_roles",
        }.get(mode, "operator_confirm_then_execute")
        lines = [
            "## Operator-Flow",
            f"- Mode: {mode}",
            "- " + self._export_human_prompt_text(flow_key),
        ]
        lines.append("- " + self._export_human_prompt_text("research_required" if operator_flow.get("sequential_schema_boilerplate_research") else "research_not_required"))
        lines.append("- " + self._export_human_prompt_text("operator_flow_manifest_contract"))
        if bool(profile.get("include_roles", False)):
            lines.append(f"- Confirmation before start: {'yes' if operator_flow.get('confirm_operators_before_start') else 'no'}")
            lines.append(f"- Sequenzielle Rollenverarbeitung: {'yes' if operator_flow.get('sequential_role_processing') else 'no'}")
            lines.append("- " + self._export_human_prompt_text("operator_mode_enforcement"))
        return lines

    def _normalize_create_target_relative_path(self, value: object) -> str:
        raw = str(value or "").replace("\\", "/").strip()
        if not raw:
            return "."
        if raw.startswith("@"):
            return raw
        try:
            candidate = Path(raw)
            if candidate.is_absolute():
                try:
                    return candidate.relative_to(self._create_working_dir()).as_posix() or "."
                except Exception:
                    return candidate.as_posix()
        except Exception:
            pass
        clean = raw.strip("/")
        return clean or "."

    def _active_target_title(self, path: str, path_type: str, ai_target: str = "") -> str:
        target = self._humanize_prompt_value(path_type or "target")
        rel = self._normalize_create_target_relative_path(path)
        label = "Projektwurzel" if rel == "." else rel
        ai = self._humanize_prompt_value(ai_target or "")
        return f"{target}: {label}" + (f" → {ai}" if ai else "")

    def _create_active_target_manifest_rows(self, config: dict | None = None, record: dict | None = None, base: Path | str | None = None) -> list[dict]:
        """Compile all active Generator/Create targets into one export contract.

        The human prompt must not collapse Create context to a single wrapper row.
        This helper merges the active WRITE_AI_RULES_TO rows, Create mapping
        detection, preview-tree roots and dependency-layer targets into a stable,
        manifest-safe list. It keeps project-relative traceability even when the
        export checkbox compiles absolute project paths for human-facing output.
        """
        config = config if isinstance(config, dict) else self._current_create_config()
        try:
            project_root = Path(str(base or self._create_working_dir())).resolve()
        except Exception:
            project_root = Path(str(base or "."))
        rows_by_key: dict[tuple[str, str], dict] = {}

        def as_list(value: object) -> list[str]:
            if isinstance(value, (list, tuple, set)):
                return [str(item).strip() for item in value if str(item).strip()]
            if value is None:
                return []
            text = str(value).strip()
            return [text] if text else []

        def merge_unique(target: dict, key: str, values: object, limit: int = 24) -> None:
            current = target.setdefault(key, [])
            if not isinstance(current, list):
                current = []
                target[key] = current
            for value in as_list(values):
                if value and value not in current:
                    current.append(value)
                if len(current) >= limit:
                    break

        def add_target(*, path: object = ".", path_type: object = "wrapper", ai_target: object = "", profiles: object = None, file_types: object = None, source: object = "", evidence: object = None, dependency_manifests: object = None, dependency_packages: object = None, role: object = "", boilerplate: object = "", enabled: bool = True) -> None:
            if enabled is False:
                return
            rel = self._normalize_create_target_relative_path(path)
            kind = str(path_type or "target").strip().lower() or "target"
            key = (rel, kind)
            row = rows_by_key.setdefault(key, {
                "id": "target_" + re.sub(r"[^a-z0-9_]+", "_", f"{kind}_{rel}".lower()).strip("_"),
                "title": self._active_target_title(rel, kind, str(ai_target or "")),
                "description": "Active target from Create/Generator/Mapping evidence; content and rules continue through the declared manifest files.",
                "path": self._compile_project_path_for_export(rel, project_root),
                "relative_path": rel,
                "path_type": kind,
                "build_target": str(config.get("build_target") or self.create_build_target.get() or kind),
                "ai_target": str(ai_target or config.get("ai_target") or self.ai_target_var.get() or "ChatGPT"),
                "enabled": True,
                "sources": [],
                "roles": [],
                "boilerplates": [],
                "boilerplate_profiles": [],
                "file_types": [],
                "dependency_manifests": [],
                "dependency_packages": [],
                "evidence": [],
                "manifest_contract": [
                    "PROMPT_MANIFEST.json contains the consolidated active target, tree boundary and dependency context.",
                    "EXPORT_MANIFEST.json declares which target files are actually exported.",
                ],
            })
            if str(ai_target or "").strip() and not str(row.get("ai_target") or "").strip():
                row["ai_target"] = str(ai_target).strip()
            merge_unique(row, "sources", source)
            merge_unique(row, "roles", role)
            merge_unique(row, "boilerplates", boilerplate)
            merge_unique(row, "boilerplate_profiles", profiles)
            merge_unique(row, "file_types", file_types)
            merge_unique(row, "dependency_manifests", dependency_manifests)
            merge_unique(row, "dependency_packages", dependency_packages)
            if isinstance(evidence, dict):
                ev = {str(k): v for k, v in evidence.items() if v not in (None, "", [], {})}
                if ev and ev not in row["evidence"]:
                    row["evidence"].append(ev)
            else:
                merge_unique(row, "evidence", evidence)

        add_target(
            path=config.get("path") or self.create_target_path.get() or ".",
            path_type=config.get("path_type") or config.get("build_target") or self.create_build_target.get() or "wrapper",
            ai_target=config.get("ai_target") or self.ai_target_var.get() or "ChatGPT",
            profiles=config.get("profiles", []),
            file_types=config.get("file_types", []),
            source="current_create_config",
            evidence={"stack": self.create_stack.get(), "mode": self.create_mode.get()},
        )

        for target in getattr(self, "targets", []) or []:
            try:
                enabled = bool(getattr(target, "enabled", True))
                add_target(
                    path=getattr(target, "path", "."),
                    path_type=getattr(target, "path_type", "target"),
                    ai_target=getattr(target, "ai_target", ""),
                    profiles=getattr(target, "boilerplate_profiles", []),
                    file_types=getattr(target, "file_types", []),
                    source="WRITE_AI_RULES_TO targets",
                    enabled=enabled,
                )
            except Exception:
                continue

        for item in getattr(self, "_create_detected_targets", []) or []:
            if not isinstance(item, dict):
                continue
            add_target(
                path=item.get("path") or ".",
                path_type=item.get("path_type") or item.get("target") or "target",
                ai_target=item.get("ai_target") or config.get("ai_target") or self.ai_target_var.get() or "ChatGPT",
                source="detected_create_project_targets",
                evidence={k: item.get(k) for k in ("stack", "evidence", "reason") if item.get(k)},
            )

        try:
            root_relations = self._create_target_root_relations()
        except Exception:
            root_relations = {}
        for target_name, info in (root_relations or {}).items():
            if not isinstance(info, dict):
                continue
            add_target(
                path=info.get("root_rel") or ("." if str(target_name).lower() == "wrapper" else target_name),
                path_type=target_name,
                ai_target=config.get("ai_target") or self.ai_target_var.get() or "ChatGPT",
                source="create_project_tree_preview_root",
                role=info.get("role"),
                boilerplate=info.get("boilerplate"),
            )

        try:
            dependency_layer = self._effective_dependency_layer(config)
        except Exception:
            dependency_layer = []
        for group in dependency_layer:
            if not isinstance(group, dict):
                continue
            target_name = str(group.get("target") or "generated").strip()
            info = root_relations.get(target_name.lower(), {}) if isinstance(root_relations, dict) else {}
            target_path = info.get("root_rel") or ("." if target_name.lower() in {"wrapper", "root"} else target_name)
            add_target(
                path=target_path,
                path_type=target_name or "dependency_target",
                source="PROMPT_MANIFEST.json",
                dependency_manifests=group.get("manifest_files", []),
                dependency_packages=group.get("dependencies", []),
                evidence={"ecosystem": group.get("ecosystem"), "install_token": group.get("install_token"), "validation_token": group.get("validation_token")},
            )

        rows = list(rows_by_key.values())
        def sort_key(row: dict) -> tuple[int, str, str]:
            kind = str(row.get("path_type") or "")
            order = {"wrapper": 0, "root": 0, "backend": 1, "frontend": 2, "assets": 3, "generated": 4}.get(kind, 9)
            return (order, str(row.get("relative_path") or ""), kind)
        rows.sort(key=sort_key)
        for row in rows:
            # Keep descriptions content-based but compact. High-intelligence
            # prompt rendering expands these fields; manifests keep all arrays.
            rel = str(row.get("relative_path") or ".")
            kind = str(row.get("path_type") or "target")
            files = row.get("file_types") if isinstance(row.get("file_types"), list) else []
            profile_names = row.get("boilerplate_profiles") if isinstance(row.get("boilerplate_profiles"), list) else []
            manifests = row.get("dependency_manifests") if isinstance(row.get("dependency_manifests"), list) else []
            pieces = [f"{kind}-Ziel `{rel}`"]
            if files:
                pieces.append("Dateitypen: " + ", ".join(files[:6]))
            if profile_names:
                pieces.append("Profile: " + ", ".join(profile_names[:6]))
            if manifests:
                pieces.append("Dependency details only through PROMPT_MANIFEST.json")
            row["description"] = "; ".join(pieces) + "."
        return rows

    def _create_active_targets_payload(self, config: dict | None = None, record: dict | None = None, base: Path | str | None = None) -> dict:
        rows = self._create_active_target_manifest_rows(config, record, base)
        return {
            "artifact": "PROMPT_MANIFEST.active_targets",
            "schema_version": "2026.create.active_targets.v1",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "mode": self.create_mode.get(),
            "stack": self.create_stack.get(),
            "export_intelligence": self._create_export_intelligence_value(),
            "path_policy": self._create_export_path_policy_payload(base or self._create_working_dir()),
            "target_count": len(rows),
            "targets": rows,
            "manifest_contract": [
                "USER_PROMPT.txt and Prompt Builder introduce every active target in human language when export intelligence is high.",
                "PROMPT_MANIFEST.json carries the active target, mapping and dependency context.",
                "EXPORT_MANIFEST.json remains the file-level export truth.",
            ],
        }

    def _human_active_target_lines(self, config: dict | None = None, profile: dict | None = None, record: dict | None = None) -> list[str]:
        profile = profile if isinstance(profile, dict) else self._export_intelligence_profile(self._create_export_intelligence_value())
        rows = self._create_active_target_manifest_rows(config, record)
        if not rows:
            return []
        high = str(profile.get("id") or "") == "hoch"
        wrapper_rows = [row for row in rows if str(row.get("path_type") or "").lower() in {"wrapper", "root"}]
        backend_rows = [row for row in rows if str(row.get("path_type") or "").lower() == "backend"]
        frontend_rows = [row for row in rows if str(row.get("path_type") or "").lower() == "frontend"]
        generated_rows = [row for row in rows if str(row.get("path_type") or "").lower() in {"assets", "generated"}]
        wrapper_path = str((wrapper_rows[0] if wrapper_rows else rows[0]).get("relative_path") or ".")
        lines = [
            "## Aktive Targets und Zielgrenzen",
            "This introduction replaces raw `Active target` dumps in the build prompt. It describes the default target structure readably and points technical lists to the manifests.",
            f"- Default target transition: `{wrapper_path}` ist die outer wrapper/project shell. Backend, frontend, assets and generated targets remain their own target boundaries and are not swallowed by the wrapper.",
            "- Tree reading: Wrapper → Frontend/Backend means a structural relationship in the Project Tree, not permission for broad changes across the entire project. Each active target section describes only its own scope boundary.",
            "- Manifest guidance: PROMPT_MANIFEST.json bundles target, mapping, role and dependency context; EXPORT_MANIFEST.json remains the file and scope truth. No separate create-specific duplicate manifests are generated anymore.",
            "- Dependency rule: Dependency packages, versions and install lists are not written out in the build prompt. The prompt references PROMPT_MANIFEST.json in readable form only.",
            "- CMD-Verweis: START, RESTART, REFACTOR, SKIP, EXTEND, SHRINK, FIX und STATUS sind in CMD.json maschinenlesbar gespiegelt.",
            f"- Aktive Targets: {len(rows)}; Backend: {len(backend_rows)}, Frontend: {len(frontend_rows)}, weitere/Generated: {len(generated_rows)}.",
        ]
        if not high:
            for row in rows[: int(profile.get("detail_limit", 4) or 4)]:
                lines.append(f"- {row.get('title')}: {row.get('path')} ({row.get('path_type')}).")
            return lines
        for row in rows:
            lines.extend([
                f"### {row.get('title')}",
                f"- Pfad: {row.get('path')}",
                f"- Relativer Ursprung: {row.get('relative_path')}",
                f"- Target-Art: {row.get('path_type')} / AI-Ziel: {row.get('ai_target') or '-'}",
                f"- Inhaltliche Einordnung: {row.get('description')}",
            ])
            for key, label in [
                ("sources", "Sourcen"),
                ("boilerplate_profiles", "Boilerplate-Profile"),
                ("file_types", "Dateitypen"),
                ("dependency_manifests", "Dependency-Manifeste"),
                ("roles", "Tree-Rollen"),
                ("boilerplates", "Tree-Boilerplates"),
            ]:
                values = row.get(key) if isinstance(row.get(key), list) else []
                if values:
                    if key == "dependency_manifests":
                        lines.append("- Dependency-Hinweis: Details stehen im maschinenlesbaren PROMPT_MANIFEST.json; Paketlisten werden im Build Prompt nicht ausgeschrieben.")
                    else:
                        lines.append(f"- {label}: " + ", ".join(str(item) for item in values[:8]))
            evidence = row.get("evidence") if isinstance(row.get("evidence"), list) else []
            if evidence:
                compact = []
                for item in evidence[:4]:
                    if isinstance(item, dict):
                        compact.append(", ".join(f"{k}={v}" for k, v in item.items() if v not in (None, "", [], {})))
                    else:
                        compact.append(str(item))
                compact = [item for item in compact if item]
                if compact:
                    lines.append("- Evidenz: " + " | ".join(compact))
            lines.append("- Manifest-Verweis: technische Target-, Mapping- und Dependency-Details stehen konsolidiert in PROMPT_MANIFEST.json; die exportierten files stehen in EXPORT_MANIFEST.json.")
        return lines

    def _human_manifest_reference_lines(self, config: dict, profile: dict, create_tree: dict | None = None) -> list[str]:
        """Human instructions for using only actually declared export files."""
        create_tree = create_tree or {}
        file_rows = self._declared_human_export_files(config, profile)
        is_low = str(profile.get("id") or "") == "niedrig"
        lines = [
            "## Manifest-Guided Project Processing",
            self._export_human_prompt_text("manifest_guided_intro"),
            self._export_human_prompt_text("declared_only_text_rule"),
        ]
        if is_low:
            manifest_names = ", ".join(name for name, _desc in file_rows[:4])
            lines.append(f"- Nutze nur die deklarierten Exportdateien: {manifest_names}.")
            lines.append("- Additional technische Details bleiben in diesen files; kopiere keine Rohlisten in die Antwort.")
        else:
            lines.append(self._export_human_prompt_text("declared_manifest_files_intro"))
            for name, description in file_rows:
                lines.append(f"- {name}: {description}.")
            lines.append("- Recursive project processing starts at the files and scope roots actually declared by EXPORT_MANIFEST.json, PROJECT_TREE.md and, if present, CREATE_WORKING_TREE.md.")
        lines.append("- " + self._export_human_prompt_text("recursive_manifest_processing"))
        if create_tree:
            files = int(create_tree.get("file_count", 0) or 0)
            dirs = int(create_tree.get("directory_count", 0) or 0)
            lines.append(f"- The current scope was compactly detected: {files} files und {dirs} directories. This number is an orientation; the actually exported manifest list remains authoritative.")
            if str(profile.get("id") or "") == "hoch":
                preview_files = create_tree.get("files") if isinstance(create_tree.get("files"), list) else []
                if preview_files:
                    lines.append("- Beispielhafte rekursive Scope-Einstiege aus dem deklarierten Working Tree:")
                    for rel in preview_files[:min(8, int(profile.get("detail_limit", 8) or 8))]:
                        lines.append(f"  - {self._humanize_prompt_value(rel)}")
        if str(profile.get("id") or "") == "hoch":
            lines.extend([
                "- In case of conflicts, the human task comes first, then operator flow, then declared manifest files, then project files as evidence.",
                "- Wenn eine manifestierte Datei fehlt oder nicht gelesen werden kann, dokumentiere das als Known Gap statt sie zu erfinden.",
            ])
        return lines

    def _human_cross_tab_control_lines(self, config: dict, profile: dict, record: dict | None = None) -> list[str]:
        """Compile the tab-spanning UI state into short human instructions."""
        record = record or {}
        detail_limit = int(profile.get("detail_limit", 4) or 4)
        lines = [
            f"- Export intelligence: {profile.get('label') or self._create_export_intelligence_value()} — {profile.get('description') or ''}".rstrip(),
            f"- Operator-Flow: {self._operator_flow_contract().get('execution_mode')}.",
            f"- Create-Modus: {self.create_mode.get()} / Stack: {self.create_stack.get()}.",
            f"- Project-Tree-Source: {'Create Working Dir' if self._use_create_working_dir_for_project_tree() else 'normaler Working Tree'}.",
            f"- Export-Scope: {'changed files only' if self.create_changed_files_only.get() else 'full resolved scope'}; Imports: {'include' if self.create_include_imports.get() else 'nicht automatisch include'}.",
            f"- Absolute Projektpfade: {'aktiv' if self._create_export_absolute_paths_enabled() else 'aus'}.",
            f"- Prompt Builder: nutzt dieselbe Export-Intelligenz und denselben Operator-Flow wie dieser Export.",
            f"- Last-Git-Commit-Referenz: {'aktiv' if self._create_should_include_last_git_commit_reference(config) else 'aus'}; Status: {self.create_git_reference_status.get()}.",
        ]
        selected = config.get("selected_create_chain_entry") if isinstance(config.get("selected_create_chain_entry"), dict) else {}
        if selected:
            label = self._humanize_prompt_value(selected.get("display_name") or selected.get("label") or selected.get("id") or "")
            lines.append(f"- Selected chain entry: {label}.")
        roots = self._create_context_roots(record)
        useful_roots = [f"{key}: {value}" for key, value in roots.items() if value]
        if useful_roots and bool(profile.get("include_tree_preview", False)):
            lines.append("- Resolved context roots:")
            lines.extend(self._human_list_lines(useful_roots, prefix="  -", limit=detail_limit))
        return lines

    def _strip_machine_dump_sections(self, text: str) -> str:
        """Remove machine-routing dumps from human prompt surfaces.

        The manifest files are the source of truth for exact project scope,
        reference routing, operator roles, hooks, weights and validation posture.
        Human-facing prompt text must explain how to use those manifests instead
        of embedding long id lists or generated routing tables.
        """
        raw = str(text or "").replace("\r", "")
        if not raw.strip():
            return ""
        blocked_heads = (
            "project scope:",
            "reference routing:",
            "operation roles:",
            "reference/admin rules:",
            "custom prompt support:",
            "prompt engineering 2026 controls:",
            "role boundary:",
            "access boundary:",
            "hard mindset:",
            "hook route:",
            "validation posture:",
            "how you should behave:",
            "remember:",
            "active hooks:",
            "active weight profiles:",
            "active file-type operators:",
        )
        kept: list[str] = []
        skipping = False
        for line in raw.splitlines():
            lower = line.strip().lower()
            if any(lower.startswith(head) for head in blocked_heads):
                skipping = True
                continue
            # Resume at a normal markdown heading that is not a blocked generated section.
            if skipping and line.startswith("#") and not any(lower.startswith(head) for head in blocked_heads):
                skipping = False
            if skipping:
                continue
            kept.append(line)
        cleaned = "\n".join(kept).strip()
        return cleaned if cleaned else raw.strip()

    def _sanitize_compiled_human_prompt(self, text: str) -> str:
        """Remove raw schema placeholders and machine dumps from human-facing surfaces."""
        cleaned = self._strip_machine_dump_sections(str(text or "").replace("\r", ""))
        cleaned = re.sub(r"(?ms)^Active target:\n.*?(?=^Operator voice:\n)", "Target context:\n- Use the human-readable section `Active targets and target boundaries` and PROMPT_MANIFEST.json; raw Active-Target dumps are not repeated here.\n\n", cleaned)
        cleaned = re.sub(r"(?ms)^Dependency groups:\n.*?(?=^(?:Package dependency layer|Micro tasks|Terminal timeline steps|Editable token map|Chainable mode boilerplates|Target match boilerplate|Feature modules|Refactor modules):\n|\Z)", "Dependency-Manifest-Verweis:\n- Dependency-Gruppen werden im Build Prompt nicht als Paketliste gezeigt; Details stehen in PROMPT_MANIFEST.json.\n\n", cleaned)
        cleaned = re.sub(r"(?ms)^Package dependency layer:\n.*?(?=^(?:Micro tasks|Terminal timeline steps|Editable token map|Chainable mode boilerplates|Target match boilerplate|Feature modules|Refactor modules):\n|\Z)", "Package dependency reference:\n- Package names, versions and install/validation tokens are exclusively in PROMPT_MANIFEST.json.\n\n", cleaned)
        cleaned = re.sub(r"\{\$([^}:|]+)(?::([^}]+))?\}", lambda m: (m.group(1) or "").replace("_", " "), cleaned)
        cleaned = re.sub(r"(?m)^\s*-\s*(?:[a-z0-9_]+(?:_[a-z0-9]+){2,})\s*(?:\||:).*$", "", cleaned)
        cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
        return cleaned.strip()
    def _has_human_prompt_builder_intro(self, text: str) -> bool:
        head = "\n".join(str(text or "").splitlines()[:8]).lower()
        return "human classification" in head or "human prompt builder context" in head

    def _strip_prompt_builder_inline_user_prompt_tail(self, text: str) -> str:
        """Remove the old custom-prompt tail from Prompt Builder preview output.

        TASKS.TXT is now the durable sidecar for the left Prompt-Builder input,
        and the preview intro already references that sidecar near the top. Keep
        the generated operator/weight/scope wrapper, but do not append the raw
        user task again at the end of the right-hand Prompt Builder output.
        """
        cleaned = str(text or "").replace("\r", "")
        if not cleaned.strip():
            return ""
        cleaned = cleaned.replace(
            "This section carries the user's own prompt into the active schema/weight/reference context.",
            "This section carries the Prompt-Builder TASKS.TXT reference into the active schema/weight/reference context.",
        )
        cleaned = cleaned.replace(
            "Do not treat this wrapper as a solution. Treat it as the next task prompt with guardrails.",
            "Do not treat this wrapper as a solution. Treat the TASKS.TXT hook above as the human task source with guardrails.",
        )
        cleaned = re.sub(
            r"(?m)^- Preserve the user's task text below; do not silently rewrite the intent\.\n?",
            "",
            cleaned,
        )
        cleaned = re.sub(
            r"(?ms)^## User prompt\n.*?(?=^## Expected behavior\n|\Z)",
            "",
            cleaned,
        )
        cleaned = re.sub(
            r"(?ms)^## Expected behavior\nAnswer the user prompt using the role above\. Do not solve outside the selected scope unless the user explicitly expands scope\.\s*",
            "",
            cleaned,
        )
        cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
        return cleaned.strip()

    def _wrap_human_prompt_builder_output(self, source_kind: str, prompt: str, *, prompt_type: str = "", custom_task: str = "", already_compiled: bool = False) -> str:
        """Add a localized human intro around Prompt Builder output.

        The underlying generator may still create operator-role or weighted prompt
        content. This wrapper makes the Prompt Builder reactive to Export-
        Intelligence and Operator Flow, so the preview text mirrors USER_PROMPT.txt
        instead of becoming a separate raw prompt surface.
        """
        body = self._sanitize_compiled_human_prompt(prompt)
        if source_kind == "custom_weighted_prompt":
            body = self._strip_prompt_builder_inline_user_prompt_tail(body)
        if not body:
            return body
        custom_task = custom_task or self._prompt_builder_custom_task_text()
        if self._has_human_prompt_builder_intro(body):
            if source_kind == "custom_weighted_prompt":
                body = self._strip_prompt_builder_inline_user_prompt_tail(body)
            return self._merge_prompt_builder_tasks_context(body, custom_task)
        profile = self._export_intelligence_profile(self._create_export_intelligence_value())
        operator_flow = self._operator_flow_contract()
        text_id = {
            "operator_role_preview": "surface_prompt_builder_operator_intro",
            "custom_weighted_prompt": "surface_prompt_builder_custom_intro",
            "shortcut_compile_custom": "surface_prompt_builder_shortcut_intro",
            "shortcut_compile_generated": "surface_prompt_builder_shortcut_intro",
        }.get(source_kind, "surface_prompt_builder_intro")
        lines = [
            "## Human Orientation for Prompt Builder",
            self._export_human_prompt_text(text_id),
            self._export_human_prompt_text("export_intelligence_context", level=profile.get("label") or self._create_export_intelligence_value(), description=profile.get("description") or ""),
            self._export_human_prompt_text(str(profile.get("human_contract_text_id") or "medium_intelligence_contract")),
            "",
            "### Operator Flow for this Prompt",
        ]
        flow_lines = self._human_operator_flow_lines(operator_flow, profile)
        # Drop the section heading to keep the Prompt Builder intro compact.
        lines.extend(flow_lines[1:] if flow_lines and flow_lines[0].startswith("##") else flow_lines)
        token_lines = self._prompt_builder_build_complete_token_lines(custom_task, profile=profile)
        if token_lines:
            lines.extend(["", *token_lines])
        lines.extend([
            "",
            "### Cross-Tab Prompt Context",
            self._export_human_prompt_text("prompt_builder_tab_context"),
            f"- Prompt-Typ: {self._humanize_prompt_value(prompt_type or source_kind)}.",
            f"- Shortcut-Compile: {'yes' if already_compiled else 'no'}.",
            f"- Create-Stack: {self.create_stack.get()}.",
            f"- Build-Ziel: {self.create_build_target.get()}.",
            f"- Changed-files-only: {'yes' if self.create_changed_files_only.get() else 'no'}.",
            f"- Absolute Projektpfade: {'yes' if self._create_export_absolute_paths_enabled() else 'no'}.",
        ])
        callback_contract = self._ai_response_callback_contract()
        progress_lines = self._human_progress_reference_lines(self._current_create_config(), profile)
        if progress_lines:
            prompt_progress_lines = [line.replace("## ", "### ", 1) if line.startswith("## ") else line for line in progress_lines]
            lines.extend(["", *prompt_progress_lines])
        current_config = self._current_create_config()
        target_lines = self._human_active_target_lines(current_config, profile)
        if target_lines:
            target_lines = list(target_lines)
            if target_lines and target_lines[0].startswith("## "):
                target_lines[0] = "### " + target_lines[0][3:]
            lines.extend(["", *target_lines])
        git_reference = self._last_git_commit_reference_for_manifest(current_config, reason="prompt_builder") if self._create_should_include_last_git_commit_reference(current_config) else getattr(self, "_create_git_reference_payload", {})
        if isinstance(git_reference, dict) and (git_reference.get("enabled") or git_reference.get("available")):
            lines.extend(["", "### Last-Git-Commit-Referenz"] + self._format_last_git_commit_reference_lines(git_reference, detail="full" if self._create_high_export_intelligence_enabled() else "summary")[1:])
        task_section = self._prompt_builder_tasks_context_section(custom_task) if str(profile.get("id")) != "niedrig" else ""
        if task_section:
            lines.extend(["", task_section])
        lines.extend(["", "### Kompilierter Prompt", body])
        return "\n".join(line.rstrip() for line in lines if line is not None).strip()

    def _prompt_builder_tasks_overlay_heading(self) -> str:
        return "## Prompt-Builder TASKS.TXT Input"

    def _extract_prompt_builder_task_overlay(self, text: str) -> str:
        raw = str(text or "").replace("\r", "").strip()
        if not raw:
            return ""
        heading = self._prompt_builder_tasks_overlay_heading()
        marker_index = raw.find(heading)
        if marker_index >= 0:
            overlay = raw[marker_index + len(heading):].strip()
            # Keep only the user overlay. A later generated heading means another
            # process has appended preview material, not user-authored TASK text.
            end_match = re.search(r"(?m)^(?:# TASKS\.TXT\b|##\s+(?:Menschlich kompilierter Create-Prompt|Prompt-Builder-TASKS\.TXT Hook|Kompilierter Prompt|Remember:)\b)", overlay)
            if end_match:
                overlay = overlay[:end_match.start()].strip()
            return overlay
        # If the left box already contains a generated Create contract and no
        # overlay marker, it is process context, not a user TASKS.TXT input.
        lower_head = "\n".join(raw.splitlines()[:6]).lower()
        generated_markers = (
            "human-compiled create prompt",
            "human classification for the prompt builder",
            "kompilierter prompt",
        )
        if any(marker in lower_head for marker in generated_markers):
            return ""
        return raw

    def _prompt_builder_custom_task_text(self) -> str:
        widget = getattr(self, "custom_prompt_text", None)
        if widget is None:
            return ""
        try:
            return self._extract_prompt_builder_task_overlay(widget.get("1.0", "end"))
        except Exception:
            return ""

    def _merge_prompt_builder_left_input_into_process(self, process_text: str, user_task_text: str | None) -> str:
        process = str(process_text or "").replace("\r", "").strip()
        task = self._extract_prompt_builder_task_overlay(user_task_text or "")
        if not task:
            return process
        heading = self._prompt_builder_tasks_overlay_heading()
        # Remove an older overlay from the process text before re-inserting the
        # current left input. This keeps auto-compile additive without duplicating
        # or overwriting the previous process contract.
        pattern = re.compile(r"(?ms)^" + re.escape(heading) + r"\n.*?\Z")
        process = pattern.sub("", process).strip()
        return (process + "\n\n" + heading + "\n" + task).strip()

    def _create_tasks_sidecar_payload(self, raw_text: str | None = None) -> dict:
        raw = (raw_text if raw_text is not None else self._prompt_builder_custom_task_text()) or ""
        raw = str(raw).replace("\r", "").strip()
        payload = {
            "artifact": "TASKS.TXT",
            "source": "Prompt Builder / left CUSTOM_USER_PROMPT input",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "parsed_as": "empty",
            "raw_text": raw,
            "task_phases": [],
        }
        if not raw:
            return payload
        try:
            parsed = json.loads(raw)
            payload["parsed_as"] = "json"
            if isinstance(parsed, dict):
                iterable = parsed.get("tasks") or parsed.get("task_phases") or parsed.get("phases") or []
                if isinstance(iterable, dict):
                    iterable = [{"id": key, "text": value} for key, value in iterable.items()]
                if not isinstance(iterable, list):
                    iterable = [parsed]
            elif isinstance(parsed, list):
                iterable = parsed
            else:
                iterable = [parsed]
            for index, item in enumerate(iterable, start=1):
                if isinstance(item, dict):
                    title = str(item.get("title") or item.get("id") or item.get("name") or f"Phase {index}").strip()
                    body = item.get("text") or item.get("task") or item.get("description") or item
                    subtasks = item.get("subtasks") or item.get("steps") or []
                else:
                    title = f"Phase {index}"
                    body = item
                    subtasks = []
                payload["task_phases"].append({"phase": index, "title": title, "text": str(body), "subtasks": [str(value) for value in subtasks] if isinstance(subtasks, list) else []})
            return self._enrich_tasks_sidecar_payload(payload)
        except Exception:
            pass
        phase_pattern = re.compile(r"(?m)^\s*((?:\d+[a-z]?|[a-z])\))\s*(.+?)\s*$")
        matches = list(phase_pattern.finditer(raw))
        if matches:
            payload["parsed_as"] = "numbered_list"
            for index, match in enumerate(matches, start=1):
                start = match.end()
                end = matches[index].start() if index < len(matches) else len(raw)
                rest = raw[start:end].strip()
                head = match.group(2).strip()
                text = head + (("\n" + rest) if rest else "")
                payload["task_phases"].append({"phase": index, "title": match.group(1), "text": text.strip(), "subtasks": []})
        else:
            payload["parsed_as"] = "plain_text"
            chunks = [chunk.strip() for chunk in re.split(r"\n\s*\n+", raw) if chunk.strip()] or [raw]
            for index, chunk in enumerate(chunks, start=1):
                payload["task_phases"].append({"phase": index, "title": f"Phase {index}", "text": chunk, "subtasks": []})
        return self._enrich_tasks_sidecar_payload(payload)

    def _tasks_boilerplate_context(self) -> dict:
        config = self._current_create_config()
        context = config.get("create_mode_context") or self._create_mode_context(config=config)
        raw_mode_catalog = self._create_mode_catalog(config)
        raw_chain_schema = raw_mode_catalog.get("chain_schema") or context.get("chain_schema") or config.get("create_chain_schema") or {} if isinstance(raw_mode_catalog, dict) else {}
        selected = config.get("selected_create_chain_entry") if isinstance(config.get("selected_create_chain_entry"), dict) else self._selected_create_chain_entry_from_schema(raw_chain_schema)
        selected = selected if isinstance(selected, dict) else {}
        profile = self._create_mode_parameter_profile()
        values = profile.get("values", {}) if isinstance(profile.get("values"), dict) else {}
        return {
            "mode": self.create_mode.get(),
            "stack": self.create_stack.get(),
            "build_target": self.create_build_target.get(),
            "selected_plan": self._humanize_prompt_value(selected.get("display_name") or selected.get("label") or selected.get("id") or "no selected plan"),
            "selected_plan_id": str(selected.get("id") or ""),
            "plan_intent": self._humanize_prompt_value(selected.get("intent") or selected.get("user_goal") or selected.get("context_hint") or ""),
            "source_policy": self._humanize_prompt_value(selected.get("source_policy") or ""),
            "weights": values,
            "changed_files_only": bool(self.create_changed_files_only.get()),
            "include_imports": bool(self.create_include_imports.get()),
        }

    def _format_task_weight_summary(self, context: dict | None = None) -> str:
        context = context if isinstance(context, dict) else self._tasks_boilerplate_context()
        values = context.get("weights") if isinstance(context.get("weights"), dict) else {}
        if not values:
            return "keine aktiven Feature-/Refactor-Weights"
        ordered = ["precision", "architecture", "documentation_level", "usability", "security", "weight"]
        parts = []
        for key in ordered:
            if key in values:
                parts.append(f"{self._humanize_prompt_value(key)} {values[key]}")
        for key, value in values.items():
            if key not in ordered:
                parts.append(f"{self._humanize_prompt_value(key)} {value}")
        return ", ".join(parts)

    def _compiled_task_phase_instruction(self, phase: dict, context: dict | None = None) -> str:
        context = context if isinstance(context, dict) else self._tasks_boilerplate_context()
        raw = self._sanitize_compiled_human_prompt(str(phase.get("text") or "")).strip()
        raw = raw[:800] + ("..." if len(raw) > 800 else "")
        plan = context.get("selected_plan") or "aktiver Boilerplate-Plan"
        intent = context.get("plan_intent") or "Use the active boilerplate context as the execution frame."
        source_policy = context.get("source_policy") or "Projekt-Scope, Export-Manifeste und aktive Pipeline-Konfiguration bleiben die Schreib- und Evidenzgrenze."
        weight_summary = self._format_task_weight_summary(context)
        scope_mode = "changed-files-only" if context.get("changed_files_only") else "resolved project scope"
        return (
            f"Treat this phase as a human-formulated work instruction for the plan '{plan}'. "
            f"Task: {raw or 'keine Detailaufgabe angegeben'}. "
            f"Boilerplate-Absicht: {intent}. "
            f"Weighting: {weight_summary}. "
            f"Scope: {scope_mode}; Imports {'include' if context.get('include_imports') else 'nicht automatisch include'}. "
            f"Source rule: {source_policy}. "
            "Result must Done-Condition, betroffene files, Validierung, Rollback und Known-Gaps sauber trennen."
        )

    def _enrich_tasks_sidecar_payload(self, payload: dict) -> dict:
        if not isinstance(payload, dict):
            return payload
        context = self._tasks_boilerplate_context()
        payload["human_intro"] = (
            "Diese Datei ist eine automatische Nebenfunktion des Prompt-Builder-Tabs. "
            "Sie übersetzt den linken CUSTOM_USER_PROMPT bei jedem Compile erneut in menschliche Tasknphasen, "
            "ohne den bestehenden Boilerplate-/Pipeline-Prozess zu überschreiben."
        )
        payload["boilerplate_context"] = {
            "mode": context.get("mode"),
            "stack": context.get("stack"),
            "build_target": context.get("build_target"),
            "selected_plan": context.get("selected_plan"),
            "selected_plan_id": context.get("selected_plan_id"),
            "plan_intent": context.get("plan_intent"),
            "source_policy": context.get("source_policy"),
            "changed_files_only": context.get("changed_files_only"),
            "include_imports": context.get("include_imports"),
        }
        payload["weight_context"] = context.get("weights")
        for phase in payload.get("task_phases") or []:
            if isinstance(phase, dict):
                phase["compiled_instruction"] = self._compiled_task_phase_instruction(phase, context)
        return payload

    def _prompt_builder_tasks_context_section(self, custom_task: str | None = None) -> str:
        raw = self._extract_prompt_builder_task_overlay(custom_task or "")
        if not raw:
            return ""
        payload = self._create_tasks_sidecar_payload(raw)
        lines = self._format_tasks_sidecar_reference_lines(payload)
        return "\n".join(lines).strip()

    def _merge_prompt_builder_tasks_context(self, prompt: str, custom_task: str | None = None) -> str:
        text = str(prompt or "").replace("\r", "").strip()
        raw = self._extract_prompt_builder_task_overlay(custom_task or "")
        section = self._prompt_builder_tasks_context_section(raw) if raw else ""
        pattern = re.compile(r"(?ms)^### Prompt-Builder-TASKS\.TXT Hook — menschlich kompilierte Taskn\n.*?(?=^### Kompilierter Prompt\n|\Z)")
        if pattern.search(text):
            text = pattern.sub(section, text).strip() if section else pattern.sub("", text).strip()
        elif section:
            marker = "\n### Kompilierter Prompt"
            if marker in text:
                text = text.replace(marker, "\n" + section + "\n" + marker, 1)
            else:
                text = (text + "\n\n" + section).strip()
        return text

    def _tasks_sidecar_text(self, payload: dict | None = None) -> str:
        payload = payload if isinstance(payload, dict) else self._create_tasks_sidecar_payload()
        context = payload.get("boilerplate_context") if isinstance(payload.get("boilerplate_context"), dict) else {}
        weight_context = payload.get("weight_context") if isinstance(payload.get("weight_context"), dict) else {}
        lines = [
            "# TASKS.TXT",
            "",
            str(payload.get("human_intro") or "The left Prompt Builder input was compiled into human task phases."),
            "",
            "## Origin",
            f"- Source: {payload.get('source')}",
            f"- Parser: {payload.get('parsed_as')}",
            f"- Erstellt: {payload.get('created_at')}",
            "- Behavior: automatische Prompt-Builder-Nebenfunktion; keine Create-Tab-Auswahl und kein Catalog Entry.",
            "",
            "## Boilerplate- und Weight-Kontext",
            f"- Mode: {context.get('mode') or '-'}",
            f"- Stack: {context.get('stack') or '-'}",
            f"- Build-Ziel: {context.get('build_target') or '-'}",
            f"- Aktiver Plan: {context.get('selected_plan') or '-'}",
            f"- Plan-ID: {context.get('selected_plan_id') or '-'}",
            f"- Planabsicht: {context.get('plan_intent') or '-'}",
            f"- Source rule: {context.get('source_policy') or 'Project scope and manifest evidence remain authoritative.'}",
            f"- Weights: {self._format_task_weight_summary({'weights': weight_context})}",
            f"- Changed-files-only: {'yes' if context.get('changed_files_only') else 'no'}",
            f"- Include imports: {'yes' if context.get('include_imports') else 'no'}",
            "",
            "## Original left input",
            str(payload.get("raw_text") or "").strip() or "- leer",
            "",
        ]
        phases = payload.get("task_phases") if isinstance(payload.get("task_phases"), list) else []
        for phase in phases:
            if not isinstance(phase, dict):
                continue
            lines.extend([
                f"## Phase {phase.get('phase')}: {phase.get('title')}",
                f"Original: {phase.get('text')}",
                "",
                "### Human-compiled instruction",
                str(phase.get("compiled_instruction") or self._compiled_task_phase_instruction(phase)),
            ])
            subtasks = phase.get("subtasks") if isinstance(phase.get("subtasks"), list) else []
            if subtasks:
                lines.append("")
                lines.append("### Unteraufgaben")
                lines.extend(f"- {item}" for item in subtasks)
            lines.append("")
        return "\n".join(str(line).rstrip() for line in lines).strip() + "\n"

    def _format_tasks_sidecar_reference_lines(self, payload: dict | None = None) -> list[str]:
        payload = payload if isinstance(payload, dict) else self._create_tasks_sidecar_payload()
        if not payload or not str(payload.get("raw_text") or "").strip():
            return []
        phases = payload.get("task_phases") if isinstance(payload.get("task_phases"), list) else []
        context = payload.get("boilerplate_context") if isinstance(payload.get("boilerplate_context"), dict) else {}
        lines = [
            "### Prompt-Builder TASKS.TXT hook — human-compiled tasks",
            "The left Prompt Builder input is recompiled as a TASKS.TXT sidecar on every compile. The existing boilerplate/pipeline process remains intact; this layer adds a human-formulated task instruction.",
            f"- Source: {payload.get('source')}",
            f"- Parser: {payload.get('parsed_as')}",
            f"- Phasen: {len(phases)}",
            f"- Aktiver Boilerplate-Plan: {context.get('selected_plan') or '-'}",
            f"- Weights: {self._format_task_weight_summary({'weights': payload.get('weight_context') if isinstance(payload.get('weight_context'), dict) else {}})}",
        ]
        for phase in phases[:8]:
            if isinstance(phase, dict):
                compiled = self._sanitize_compiled_human_prompt(str(phase.get("compiled_instruction") or self._compiled_task_phase_instruction(phase)))
                compiled = compiled[:360] + ("..." if len(compiled) > 360 else "")
                lines.append(f"- Phase {phase.get('phase')}: {phase.get('title')} — {compiled}")
        return lines

    def _write_tasks_sidecar_and_patch_manifest(self, export_dir: Path, payload: dict | None = None) -> None:
        payload = payload if isinstance(payload, dict) else self._create_tasks_sidecar_payload()
        if not payload or not str(payload.get("raw_text") or "").strip():
            return
        export_dir = Path(export_dir)
        export_dir.mkdir(parents=True, exist_ok=True)
        tasks_path = export_dir / "TASKS.TXT"
        tasks_path.write_text(self._tasks_sidecar_text(payload), encoding="utf-8")
        for manifest_name in ("EXPORT_MANIFEST.json", "EXPORT_MANIFEST.json", "PROMPT_MANIFEST.json"):
            manifest_path = export_dir / manifest_name
            if not manifest_path.exists():
                continue
            try:
                data = json.loads(manifest_path.read_text(encoding="utf-8"))
            except Exception:
                continue
            if isinstance(data, dict):
                data["tasks_sidecar"] = {
                    "file": "TASKS.TXT",
                    "source": payload.get("source"),
                    "parsed_as": payload.get("parsed_as"),
                    "phase_count": len(payload.get("task_phases") or []),
                    "outside_zip": True,
                }
                for key in ("outside_files", "artifacts", "allowed_files"):
                    values = data.get(key)
                    if isinstance(values, list) and "TASKS.TXT" not in values:
                        values.append("TASKS.TXT")
                if manifest_name == "EXPORT_MANIFEST.json":
                    data["zip_sidecar_policy"] = "Only the ZIP plus user-facing sidecars TASK.json, USER_PROMPT.json, CMD.json and PROGRESS.json remain outside after ZIP export; PROGRESS.json is also injected into the ZIP."
            manifest_path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    def _compile_human_create_prompt_text(self, config: dict | None = None, build_record: dict | None = None, *, surface: str = "user_prompt_export") -> str:
        config = config or self._current_create_config()
        context = config.get("create_mode_context") or self._create_mode_context(config=config)
        record = build_record or self._active_successful_create_build_for_current_stack() or {}
        raw_details = self.create_details_text.get("1.0", "end").strip() if hasattr(self, "create_details_text") else ""
        resolved_details = self._resolve_create_context_shortcuts(raw_details, record)
        operator_flow = self._operator_flow_contract()
        level = self._create_export_intelligence_value()
        profile = self._export_intelligence_profile(level)
        raw_mode_catalog = self._create_mode_catalog(config)
        evidence = raw_mode_catalog.get("evidence", {}) if isinstance(raw_mode_catalog, dict) else {}
        raw_chain_schema = raw_mode_catalog.get("chain_schema") or context.get("chain_schema") or config.get("create_chain_schema") or {}
        selected_entry = config.get("selected_create_chain_entry") if isinstance(config.get("selected_create_chain_entry"), dict) else self._selected_create_chain_entry_from_schema(raw_chain_schema)
        chain_entries = self._human_selected_chain_entries(raw_chain_schema, selected_entry, profile, config)
        target_path = str(config.get("path") or self.create_target_path.get() or ".")
        build_target = str(config.get("build_target") or self.create_build_target.get() or "wrapper")
        create_tree = self._compact_create_working_tree_context(self._create_export_base_for_record(record), config, record, self._scope_paths_for_worker()) if bool(profile.get("include_tree_preview", False)) else {}
        lines: list[str] = [
            "# Human-compiled Create prompt",
            "",
            self._export_human_prompt_text(f"surface_{surface}_intro") or self._export_human_prompt_text("prompt_intro"),
            "",
            self._export_human_prompt_text("export_intelligence_context", level=profile.get("label") or level, description=profile.get("description") or ""),
            self._export_human_prompt_text(str(profile.get("human_contract_text_id") or "medium_intelligence_contract")),
            "",
            "## Overview",
            f"- Date: {date.today().isoformat()}",
            f"- Project: {self.project_name.get().strip() or 'unnamed'}",
            f"- Mode: {self.create_mode.get()}",
            f"- Routine: {context.get('routine') or '-'}",
            f"- Stack: {self.create_stack.get()}",
            f"- Target path: {target_path}",
            f"- Build-Ziel: {build_target}",
            f"- Export intelligence: {profile.get('label') or level}",
            "- Machine manifests remain part of the export, but this text is the human-readable work instruction.",
            "",
        ]
        lines.extend(self._human_operator_flow_lines(operator_flow, profile))
        lines.extend(["", "## Cross-tab control"])
        lines.append(self._export_human_prompt_text("tab_control_intro"))
        lines.extend(self._human_cross_tab_control_lines(config, profile, record))
        active_target_lines = self._human_active_target_lines(config, profile, record)
        if active_target_lines:
            lines.extend(["", *active_target_lines])
        lines.extend(["", "## Task and user context"])
        lines.append(resolved_details or raw_details or "- No additional user description provided. Use the selected mode, stack and plan as the task frame.")
        tasks_payload = self._create_tasks_sidecar_payload()
        task_lines = self._format_tasks_sidecar_reference_lines(tasks_payload)
        if task_lines:
            lines.extend(["", *task_lines])
        if self._create_should_include_last_git_commit_reference(config):
            git_payload = self._last_git_commit_reference_for_manifest(config, reason="user_prompt_export")
            lines.extend(["", *self._format_last_git_commit_reference_lines(git_payload, detail="full" if self._create_high_export_intelligence_enabled() else "summary")])
        lines.extend(["", "## Shortcut commands"] + self._human_shortcut_command_contract_lines())
        lines.extend(["", "## Context and scope rules"])
        evidence_source = self._humanize_prompt_value(evidence.get("source") or "Create Mapping / Start project") if isinstance(evidence, dict) else "Create Mapping / Start project"
        callback_contract = self._ai_response_callback_contract()
        lines.extend([
            f"- Primary evidence source: {evidence_source}",
            f"- Create Working Dir: {self._create_working_dir()}",
            f"- Build/temp path: {record.get('temp_preview_dir') or self._completed_create_build_root_for_current_stack() or self._create_terminal_work_dir()}",
            f"- Changed-files-only: {'yes' if self.create_changed_files_only.get() else 'no'}",
            f"- Include imports: {'yes' if self.create_include_imports.get() else 'no'}",
            f"- Absolute Projektpfade im Export: {'yes' if self._create_export_absolute_paths_enabled() else 'no'}; ZIP-Mitgliedsnamen bleiben portabel projekt-relativ.",
            "- Use project tree, mapping, dependency layer and export manifest as evidence sources; do not invent files, commands or frameworks.",
            "- Write only inside the resolved target/scope area and document every deviation as a known gap.",
        ])
        if create_tree:
            lines.append(f"- Detected scope in Create working tree: {create_tree.get('file_count', 0)} files, {create_tree.get('directory_count', 0)} directories.")
            if str(profile.get("id") or "") == "hoch":
                lines.append("- Individual paths are not embedded as a raw dump in USER_PROMPT.txt. Use the manifest files for the complete recursive file list.")
        lines.extend(["", *self._human_manifest_reference_lines(config, profile, create_tree), "", "## Compiled schema chain"])
        lines.append(self._export_human_prompt_text("chain_intro"))
        if not chain_entries:
            lines.append("- No matching chain plan reference resolved.")
        else:
            selected_id = str((selected_entry or {}).get("id") or "")
            for entry in chain_entries:
                lines.append("")
                lines.extend(self._compile_human_chain_entry_lines(entry, profile=profile, selected=bool(selected_id and str(entry.get("id") or "") == selected_id)))
        parameter_profile = config.get("create_mode_parameters") or self._create_mode_parameter_profile()
        if bool(profile.get("include_parameter_context", False)) and isinstance(parameter_profile, dict):
            lines.extend(["", "## Weighting and decision priority"])
            values = parameter_profile.get("values", {}) if isinstance(parameter_profile.get("values"), dict) else {}
            for key, value in values.items():
                lines.append(f"- {self._humanize_prompt_value(key)}: {value}")
            for rule in parameter_profile.get("rules", [])[:int(profile.get("rule_limit", 10) or 10)]:
                lines.append(f"- {self._humanize_prompt_value(rule)}")
        role_reference_lines = self._human_role_reference_planning_lines(config, profile)
        if role_reference_lines:
            lines.extend(["", *role_reference_lines])
        progress_lines = self._human_progress_reference_lines(config, profile, record)
        if progress_lines:
            lines.extend(["", *progress_lines])
        lines.extend(["", "## Validation and response contract"])
        lines.append(self._export_human_prompt_text("validation_intro"))
        lines.extend([
            "- At the end, provide a short change summary with affected files.",
            "- Name executed tests or explain why tests were only possible as a manual gap.",
            "- Explicitly record rollback point, known gaps and unimplemented parts.",
            "- The declared export files remain the machine-readable evidence layer: " + ", ".join(self._manifest_names_for_human_prompt(config, profile)[:12]) + ".",
        ])
        lines.extend(["", "## Remember: binding execution flow", self._export_human_prompt_text("remember_execution_contract")])
        text = "\n".join(str(line).rstrip() for line in lines).strip()
        text = self._sanitize_compiled_human_prompt(text)
        # Guardrail: USER_PROMPT.txt must not leak raw schema token syntax.
        text = re.sub(r"\{\$([^}:|]+)(?::([^}]+))?\}", lambda m: (m.group(1) or "").replace("_", " "), text)
        return text

    def _create_export_prompt_text(self, config: dict | None = None, build_record: dict | None = None, *, surface: str = "user_prompt_export") -> str:
        """Return the human-facing USER_PROMPT.txt body.

        Machine-readable catalogs, manifests and raw schema JSON stay in their
        dedicated export files. USER_PROMPT.txt is deliberately compiled into
        natural instructions so the receiving AI sees a clear task prompt instead
        of a large schema dump.
        """
        return self._compile_human_create_prompt_text(config, build_record, surface=surface)

    def _progress_json_file_name(self) -> str:
        return "PROGRESS.json"

    def _progress_json_detail_mode(self, profile: dict | None = None) -> str:
        profile = profile or self._export_intelligence_profile(self._create_export_intelligence_value())
        level = str(profile.get("id") or self._create_export_intelligence_value() or "mittel").strip().lower()
        if level == "niedrig":
            return "compact"
        if level == "hoch":
            return "full"
        return "standard"

    def _progress_json_human_intro(self, profile: dict, callback_contract: dict) -> dict:
        """English human-readable introduction for PROGRESS.json.

        Export intelligence changes how much prose is embedded, never whether
        PROGRESS.json is written. AI_LANGUAGE is not used here because exports
        and generated artifacts are intentionally English-only.
        """
        detail_mode = self._progress_json_detail_mode(profile)
        base = {
            "title": "AI-CALLBACK response design",
            "export_intelligence": str(profile.get("label") or self._create_export_intelligence_value()),
            "detail_mode": detail_mode,
            "purpose": "PROGRESS.json describes the mathematical response design for AI status messages. It controls only response shape, not scope, tool rights, validation or file access.",
            "canvas_rule": "The AI must design its own clear text canvas and show the specified mathematical values visibly instead of hiding them in prose.",
            "active_selection": f"Status={callback_contract.get('template')}; Design={callback_contract.get('design_type')}",
        }
        if detail_mode == "compact":
            base["introduction"] = "Low export intelligence: USER_PROMPT reduces callback prose; PROGRESS.json remains the complete machine-readable sidecar."
            base["template_introduction_policy"] = "Compact: status and design type are described per entry; additional prose is reduced to the minimum."
        elif detail_mode == "full":
            base["introduction"] = "High export intelligence: every status template and design type is introduced in human-readable form so the AI understands the response design as a canvas task."
            base["template_introduction_policy"] = "Full: every status and design type includes an introduction, mathematical display rule and clear non-goals."
        else:
            base["introduction"] = "Medium export intelligence: PROGRESS.json explains the callback contract clearly and keeps all templates structurally available."
            base["template_introduction_policy"] = "Standard: every status and design type is introduced concisely; details remain in the template text."
        return base

    def _progress_status_intro(self, state: str) -> str:
        return {
            "IDLE": "Idle state: shows zero values, readiness and the next expected input without claiming progress.",
            "PENDING": "Pending state: shows queue/start values and separates planned units from completed units.",
            "PROGRESS": "Progress state: shows running percentages, counters or timeline values with the current phase and next verifiable step.",
            "ERROR": "Error state: shows error position, remaining open units and safe next action without claiming success.",
            "FINISH": "Finish state: shows 100% or finalized values, validation status and remaining gaps transparently.",
        }.get(str(state or "").upper(), "Status message: measurably describes the state the AI is communicating.")

    def _progress_design_intro(self, design: str) -> str:
        return {
            "PERCENT": "Percent design: represents task and total progress as computable percentages.",
            "NUMMERIC": "Numeric design: represents status as counters, indexes and totals.",
            "CHRONICAL": "Chronological design: organizes work into T0..Tn steps and handoffs.",
            "TIMELINE": "Timeline design: shows done, active and next step as linear stations.",
            "BARS": "Bars design: shows progress as text-based bars with done/total values.",
            "RADIAL-BAR": "Radial-bar design: describes ring/center logic textually for task and total progress.",
        }.get(str(design or "").upper(), "Design type: describes the mathematical display form of the callback canvas.")

    def _create_progress_json_payload(self, config: dict | None = None, build_record: dict | None = None) -> dict:
        config = config or self._current_create_config()
        record = build_record or self._active_successful_create_build_for_current_stack() or {}
        profile = self._export_intelligence_profile(self._create_export_intelligence_value())
        callback_contract = self._ai_response_callback_contract()
        matrix = self._ai_callback_template_matrix()
        detail_mode = self._progress_json_detail_mode(profile)
        templates: dict[str, dict] = {}
        for design in self._ai_callback_design_types():
            design_key = str(design).upper()
            state_map = matrix.get(design_key, {}) if isinstance(matrix, dict) else {}
            templates[design_key] = {
                "introduction": self._progress_design_intro(design_key),
                "states": {},
            }
            for state in self._ai_callback_states():
                state_key = str(state).upper()
                text = str(state_map.get(state_key) or "").strip()
                entry = {
                    "introduction": self._progress_status_intro(state_key),
                    "template": text,
                    "math_contract": "Display must be measurable: no invented completion claim, no unverifiable percentages, no scope expansion.",
                }
                if detail_mode == "compact":
                    entry = {
                        "introduction": entry["introduction"],
                        "template": text,
                    }
                templates[design_key]["states"][state_key] = entry
        payload = {
            "artifact": self._progress_json_file_name(),
            "schema_version": "2026.create.progress_callback.v1",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "source": "Prompt Builder AI-CALLBACK response design",
            "export_intelligence": self._create_export_intelligence_value(),
            "detail_mode": detail_mode,
            "human_introduction": self._progress_json_human_intro(profile, callback_contract),
            "active_callback": callback_contract,
            "status_order": self._ai_callback_states(),
            "design_type_order": self._ai_callback_design_types(),
            "templates": templates,
            "export_policy": {
                "outside_zip": True,
                "inside_zip": True,
                "low_intelligence_user_prompt_policy": "USER_PROMPT may reduce or omit verbose callback prose, but PROGRESS.json is still written outside and inside the ZIP.",
                "scope_boundary": "Response design only; does not change tools, repository access, safety limits, validation boundaries or task scope.",
            },
            "create_context": {
                "project": self.project_name.get().strip(),
                "mode": self.create_mode.get(),
                "stack": self.create_stack.get(),
                "build_target": config.get("build_target") or self.create_build_target.get(),
                "has_build_complete": bool(record.get("complete") if isinstance(record, dict) else False),
                "build_complete_id": record.get("id") if isinstance(record, dict) else None,
            },
        }
        return payload

    def _human_progress_reference_lines(self, config: dict | None = None, profile: dict | None = None, build_record: dict | None = None) -> list[str]:
        profile = profile or self._export_intelligence_profile(self._create_export_intelligence_value())
        payload = self._create_progress_json_payload(config, build_record)
        intro = payload.get("human_introduction", {}) if isinstance(payload.get("human_introduction"), dict) else {}
        active = payload.get("active_callback", {}) if isinstance(payload.get("active_callback"), dict) else {}
        level = str(profile.get("id") or self._create_export_intelligence_value() or "mittel").strip().lower()
        lines = [
            "## AI-CALLBACK / PROGRESS.json",
            f"- File: {self._progress_json_file_name()} is always exported, kept outside the ZIP and additionally written into the ZIP.",
            f"- Active template: {active.get('template')} / {active.get('design_type')}",
        ]
        if level == "niedrig":
            lines.append("- Low export intelligence: USER_PROMPT deliberately keeps this section short; the complete mathematical callback introduction is in PROGRESS.json.")
            return lines
        lines.extend([
            f"- Purpose: {intro.get('purpose')}",
            f"- Canvas rule: {intro.get('canvas_rule')}",
            "- Introduced states: " + ", ".join(payload.get("status_order", [])),
            "- Introduced design types: " + ", ".join(payload.get("design_type_order", [])),
            "- This requirement controls only response shape, not tool rights, scope or validation boundaries.",
        ])
        if level == "hoch":
            for design in payload.get("design_type_order", []):
                lines.append(f"- {design}: {self._progress_design_intro(str(design))}")
        return lines

    def _create_context_artifact_names(self, config: dict | None = None) -> list[str]:
        names = [
            "EXPORT_MANIFEST.json",
            "PROMPT_MANIFEST.json",
            "CMD.json",
            self._progress_json_file_name(),
            "PROMPT_EVAL_CHECKLIST.md",
        ]
        if self._create_should_include_last_git_commit_reference(config):
            names.append("LAST_GIT_COMMIT.json")
        seen: set[str] = set()
        unique: list[str] = []
        for name in names:
            if name and name not in seen:
                seen.add(name)
                unique.append(name)
        return unique

    def _write_json_alias_file(self, export_dir: Path, primary_name: str, alias_name: str, payload: dict) -> None:
        text = json.dumps(payload, indent=2, ensure_ascii=False) + "\n"
        (export_dir / primary_name).write_text(text, encoding="utf-8")
        if alias_name and alias_name != primary_name:
            (export_dir / alias_name).write_text(text, encoding="utf-8")

    def _register_create_context_artifacts_in_export_manifest(self, export_dir: Path, config: dict | None = None) -> None:
        manifest_path = Path(export_dir) / "EXPORT_MANIFEST.json"
        if not manifest_path.exists():
            return
        try:
            data = json.loads(manifest_path.read_text(encoding="utf-8"))
        except Exception:
            return
        if not isinstance(data, dict):
            return
        blocked = {
            "CREATE_" + "EXPORT_MANIFEST.json",
            "CREATE_" + "PROMPT_MANIFEST.json",
            "CREATE_" + "PROJECT_MAPPING.json",
            "CREATE_" + "DEPENDENCY_LAYER.json",
            "CREATE_" + "CMD_MANIFEST.json",
            "CREATE_" + "ACTIVE_TARGETS.json",
        }
        artifact_names = []
        for name in self._create_context_artifact_names(config):
            if name in blocked:
                continue
            if (Path(export_dir) / name).exists() and name not in artifact_names:
                artifact_names.append(name)
        data["create_context_artifacts"] = {
            "written": artifact_names,
            "cmd_manifest": "CMD.json" if "CMD.json" in artifact_names else None,
            "progress_manifest": self._progress_json_file_name() if self._progress_json_file_name() in artifact_names else None,
            "last_git_commit_manifest": "LAST_GIT_COMMIT.json" if "LAST_GIT_COMMIT.json" in artifact_names else None,
            "write_policy": "Create context is consolidated into EXPORT_MANIFEST.json and PROMPT_MANIFEST.json; PROGRESS.json is the dedicated callback-design sidecar.",
        }
        for key in ("outside_files", "allowed_files", "copied_files", "generated_files"):
            values = data.get(key)
            if isinstance(values, list):
                values[:] = [item for item in values if Path(str(item)).name not in blocked]
                use_abs = any(os.path.isabs(str(item)) for item in values)
                for name in artifact_names:
                    item = str((Path(export_dir) / name).resolve()) if use_abs and key == "outside_files" else name
                    if item not in values:
                        values.append(item)
        values = data.get("outside_files_relative")
        if isinstance(values, list):
            values[:] = [item for item in values if Path(str(item)).name not in blocked]
            for name in artifact_names:
                if name not in values:
                    values.append(name)
        manifest_path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    def _rewrite_zip_with_create_context_artifacts(self, export_dir: Path, config: dict | None = None) -> list[str]:
        export_dir = Path(export_dir)
        artifact_paths = [export_dir / name for name in self._create_context_artifact_names(config) if (export_dir / name).exists()]
        export_manifest_path = export_dir / "EXPORT_MANIFEST.json"
        if export_manifest_path.exists() and export_manifest_path not in artifact_paths:
            artifact_paths.append(export_manifest_path)
        if not artifact_paths:
            return []
        zip_paths = sorted(list(export_dir.glob("*_scope_clone.zip")) + list(export_dir.glob("*_compact_context.zip")))
        messages: list[str] = []
        for zip_path in zip_paths:
            if not zip_path.is_file():
                continue
            tmp_path = zip_path.with_suffix(zip_path.suffix + ".tmp")
            artifact_names = {path.name for path in artifact_paths}
            try:
                with zipfile.ZipFile(zip_path, "r") as source, zipfile.ZipFile(tmp_path, "w", compression=zipfile.ZIP_DEFLATED) as target:
                    for info in source.infolist():
                        if info.filename in artifact_names:
                            continue
                        target.writestr(info, source.read(info.filename))
                    for path in artifact_paths:
                        target.write(path, path.name)
                tmp_path.replace(zip_path)
                messages.append(f"ZIP   refreshed Create context artifacts in {zip_path.name}: {', '.join(sorted(artifact_names))}")
            except Exception as exc:
                try:
                    if tmp_path.exists():
                        tmp_path.unlink()
                except Exception:
                    pass
                messages.append(f"WARN  Create context artifacts not injected into {zip_path.name}: {exc}")
        return messages

    def _apply_create_zip_sidecar_contract(self, export_dir: Path, config: dict, tasks_payload: dict) -> list[str]:
        """Keep only the user-facing Create ZIP sidecars outside the export ZIP.

        PROGRESS.json is intentionally both an outside sidecar and a ZIP member,
        because the callback design is part of the runtime prompt contract and a
        portable export artifact.
        """
        export_dir = Path(export_dir)
        if not bool(self.create_export_as_zip.get()):
            return []
        zip_paths = sorted(list(export_dir.glob("*_scope_clone.zip")) + list(export_dir.glob("*_compact_context.zip")))
        if not zip_paths:
            return []
        prompt_text = self._create_export_prompt_text(config, self._active_successful_create_build_for_current_stack())
        progress_payload = self._create_progress_json_payload(config, self._active_successful_create_build_for_current_stack())
        user_prompt_payload = {
            "artifact": "USER_PROMPT.json",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "format": "human_prompt_text_wrapped_in_json",
            "text_file_alias": "USER_PROMPT.txt",
            "prompt_text": prompt_text,
            "ai_response_callback": self._ai_response_callback_contract(),
            "progress_manifest": self._progress_json_file_name(),
        }
        task_payload = dict(tasks_payload or {})
        task_payload["artifact"] = "TASK.json"
        cmd_payload = self._create_cmd_manifest_payload(config)
        sidecars = {
            "TASK.json": task_payload,
            "USER_PROMPT.json": user_prompt_payload,
            "CMD.json": cmd_payload,
            self._progress_json_file_name(): progress_payload,
        }
        for name, payload in sidecars.items():
            (export_dir / name).write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

        messages: list[str] = []
        allowed = set(sidecars.keys()) | {path.name for path in zip_paths}
        files_to_pack = [path for path in sorted(export_dir.iterdir(), key=lambda item: item.name) if path.is_file() and path.name not in {zp.name for zp in zip_paths}]
        for zip_path in zip_paths:
            tmp_path = zip_path.with_suffix(zip_path.suffix + ".tmp")
            try:
                with zipfile.ZipFile(zip_path, "r") as source, zipfile.ZipFile(tmp_path, "w", compression=zipfile.ZIP_DEFLATED) as target:
                    skip_names = {path.name for path in files_to_pack}
                    for info in source.infolist():
                        if info.filename in skip_names:
                            continue
                        target.writestr(info, source.read(info.filename))
                    for path in files_to_pack:
                        target.write(path, path.name)
                tmp_path.replace(zip_path)
                messages.append(f"ZIP   Create sidecar contract packed into {zip_path.name}")
            except Exception as exc:
                try:
                    if tmp_path.exists():
                        tmp_path.unlink()
                except Exception:
                    pass
                messages.append(f"WARN  Create sidecar contract not packed into {zip_path.name}: {exc}")
        for path in files_to_pack:
            if path.name not in allowed:
                try:
                    path.unlink()
                    messages.append(f"CLEAN outside sidecar moved into ZIP: {path.name}")
                except Exception as exc:
                    messages.append(f"WARN  outside sidecar cleanup skipped for {path.name}: {exc}")
        messages.extend(f"WRITE {export_dir / name}" for name in sidecars)
        return messages

    def _write_create_export_context_sidecars(self, base: Path, export_dir: Path, config: dict, build_record: dict | None = None) -> list[str]:
        self._write_create_export_context_files(base, export_dir, config, build_record)
        self._register_create_context_artifacts_in_export_manifest(export_dir, config)
        messages = [f"WRITE {Path(export_dir) / name}" for name in self._create_context_artifact_names(config) if (Path(export_dir) / name).exists()]
        messages.extend(self._rewrite_zip_with_create_context_artifacts(export_dir, config))
        return messages

    def _write_create_export_context_files(self, base: Path, export_dir: Path, config: dict, build_record: dict | None = None) -> None:
        export_dir.mkdir(parents=True, exist_ok=True)
        context = config.get("create_mode_context") or self._create_mode_context(config=config)
        record = build_record or {}
        tasks_payload = self._create_tasks_sidecar_payload()
        last_git_reference = self._last_git_commit_reference_for_manifest(config, reason="create_export_manifest")
        cmd_manifest = self._create_cmd_manifest_payload(config)
        progress_payload = self._create_progress_json_payload(config, record)
        active_target_payload = self._create_active_targets_payload(config, record, base)
        project_mapping_payload = self._create_project_mapping_payload(config)
        dependency_layer_payload = self._effective_dependency_layer(config)
        blocked = {
            "CREATE_" + "EXPORT_MANIFEST.json",
            "CREATE_" + "PROMPT_MANIFEST.json",
            "CREATE_" + "PROJECT_MAPPING.json",
            "CREATE_" + "DEPENDENCY_LAYER.json",
            "CREATE_" + "CMD_MANIFEST.json",
            "CREATE_" + "ACTIVE_TARGETS.json",
        }

        def read_json_object(path: Path) -> dict:
            try:
                data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
            except Exception:
                data = {}
            return data if isinstance(data, dict) else {}

        def clean_file_lists(data: dict) -> None:
            for key in ("outside_files", "outside_files_relative", "allowed_files", "copied_files", "generated_files", "artifacts"):
                values = data.get(key)
                if isinstance(values, list):
                    cleaned: list[object] = []
                    seen: set[str] = set()
                    for item in values:
                        name = Path(str(item)).name
                        if name in blocked:
                            continue
                        marker = str(item)
                        if marker in seen:
                            continue
                        seen.add(marker)
                        cleaned.append(item)
                    values[:] = cleaned

        export_context = {
            "mode": "create_tab_context_export",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "source_base": str(base),
            "create_working_dir": str(self._create_working_dir()),
            "create_export_dir": str(export_dir),
            "selected_stack": self.create_stack.get(),
            "selected_mode": self.create_mode.get(),
            "mode_context": context,
            "selected_chain_entry": config.get("selected_create_chain_entry"),
            "operator_flow": self._operator_flow_contract(),
            "operator_research_plan": self._create_operator_research_plan(config),
            "ai_response_callback": self._ai_response_callback_contract(),
            "progress_manifest": self._progress_json_file_name(),
            "source_clone": self._create_source_clone_manifest or None,
            "active_targets": active_target_payload.get("targets", []),
            "project_mapping": project_mapping_payload,
            "dependency_layer_summary": {
                "group_count": len(dependency_layer_payload) if isinstance(dependency_layer_payload, list) else 0,
                "targets": sorted({str(group.get("target") or "") for group in dependency_layer_payload if isinstance(group, dict) and str(group.get("target") or "").strip()}),
                "manifest_files": sorted({str(item) for group in dependency_layer_payload if isinstance(group, dict) for item in (group.get("manifest_files") or [])}),
            },
            "last_git_commit_reference": last_git_reference,
            "tasks_sidecar": {"file": "TASKS.TXT", "enabled": bool(str(tasks_payload.get("raw_text") or "").strip()), "parsed_as": tasks_payload.get("parsed_as"), "phase_count": len(tasks_payload.get("task_phases") or [])},
            "cmd_manifest": "CMD.json",
            "settings": {
                "project_tree_source_mode": "create_working_dir",
                "changed_files_only": bool(self.create_changed_files_only.get()),
                "include_imports": bool(self.create_include_imports.get()),
                "schema_mirror": bool(self.create_schema_mirror.get()),
                "create_export_as_zip": bool(self.create_export_as_zip.get()),
                "create_compact_export": bool(self.create_compact_export.get()),
                "export_intelligence": self._create_export_intelligence_value(),
                "last_git_commit_enabled": bool(self._create_should_include_last_git_commit_reference(config)),
                "absolute_project_paths": bool(self._create_export_absolute_paths_enabled()),
                "path_policy": self._create_export_path_policy_payload(base),
            },
            "write_policy": "No duplicate create-specific sidecars; create context is merged into EXPORT_MANIFEST.json and PROMPT_MANIFEST.json.",
        }
        prompt_context = {
            "mode": self.create_mode.get(),
            "stack": self.create_stack.get(),
            "routine": context.get("routine"),
            "profiles": config.get("profiles", []),
            "references": config.get("references", []),
            "roles": config.get("roles", []),
            "weights": config.get("create_weight_profiles", context.get("weights", [])),
            "prompt_essentials": context.get("prompt_essentials", []),
            "mode_boilerplate": config.get("create_mode_boilerplate", {}),
            "selected_chain_entry": config.get("selected_create_chain_entry"),
            "export_intelligence": self._create_export_intelligence_value(),
            "path_policy": self._create_export_path_policy_payload(base),
            "human_prompt_locale_source": "schema/human_prompt_locale.json",
            "mode_catalog": self._create_mode_catalog(config),
            "chain_schema": config.get("create_chain_schema") or self._create_chain_schema(self.create_mode.get(), [], config),
            "package_control": self._package_control_findings(config),
            "operator_flow": self._operator_flow_contract(),
            "operator_research_plan": self._create_operator_research_plan(config),
            "ai_response_callback": self._ai_response_callback_contract(),
            "progress_manifest": self._progress_json_file_name(),
            "context_shortcuts": self._create_shortcut_reference_rows(self.create_details_text.get("1.0", "end") if hasattr(self, "create_details_text") else "", record),
            "last_git_commit_reference": last_git_reference,
            "tasks_sidecar": {"file": "TASKS.TXT", "enabled": bool(str(tasks_payload.get("raw_text") or "").strip()), "parsed_as": tasks_payload.get("parsed_as"), "phase_count": len(tasks_payload.get("task_phases") or [])},
            "shortcut_command_contract": self._human_shortcut_command_contract_lines(),
            "cmd_manifest": cmd_manifest,
            "source_clone": self._create_source_clone_manifest or None,
            "active_targets": active_target_payload.get("targets", []),
            "project_mapping": project_mapping_payload,
            "dependency_layer": dependency_layer_payload,
            "create_mode_parameters": config.get("create_mode_parameters", self._create_mode_parameter_profile()),
            "create_parameter_boilerplates": config.get("create_parameter_boilerplates", self._create_mode_parameter_boilerplates(config.get("create_mode_parameters", self._create_mode_parameter_profile()))),
            "create_parameter_context": config.get("create_parameter_context", self._create_parameter_context_priority(config.get("create_mode_parameters", self._create_mode_parameter_profile()))),
            "write_policy": "Consolidated into PROMPT_MANIFEST.json; no duplicate create-specific sidecars for prompt, mapping, dependency or active-target context.",
        }

        export_manifest_path = export_dir / "EXPORT_MANIFEST.json"
        export_manifest = read_json_object(export_manifest_path)
        clean_file_lists(export_manifest)
        export_manifest["create_context"] = export_context
        export_manifest["create_context_artifacts"] = {
            "written": [name for name in self._create_context_artifact_names(config) if name not in blocked],
            "cmd_manifest": "CMD.json",
            "progress_manifest": self._progress_json_file_name(),
            "last_git_commit_manifest": "LAST_GIT_COMMIT.json" if self._create_should_include_last_git_commit_reference(config) else None,
            "write_policy": "Create context is consolidated into EXPORT_MANIFEST.json and PROMPT_MANIFEST.json; duplicate create-specific sidecars are not written. PROGRESS.json remains the dedicated callback-design sidecar.",
        }
        export_manifest_path.write_text(json.dumps(export_manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

        prompt_manifest_path = export_dir / "PROMPT_MANIFEST.json"
        prompt_manifest = read_json_object(prompt_manifest_path)
        clean_file_lists(prompt_manifest)
        prompt_manifest["create_prompt_context"] = prompt_context
        prompt_manifest_path.write_text(json.dumps(prompt_manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

        (export_dir / "CMD.json").write_text(json.dumps(cmd_manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        (export_dir / self._progress_json_file_name()).write_text(json.dumps(progress_payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        if self._create_should_include_last_git_commit_reference(config):
            (export_dir / "LAST_GIT_COMMIT.json").write_text(json.dumps(self._last_git_commit_manifest_payload(config, last_git_reference, base=base), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        eval_lines = [
            "# PROMPT EVAL CHECKLIST",
            "",
            "- [ ] Outcome is explicit and target-scoped.",
            "- [ ] Project evidence is separated from assumptions.",
            "- [ ] Generated files are discoverable from EXPORT_MANIFEST.json.",
            "- [ ] Shortcut CMDs are mirrored in CMD.json and do not expand access/safety boundaries.",
            "- [ ] AI callback designs are mirrored in PROGRESS.json, introduced with Human Text routine and exported inside plus outside ZIP.",
            "- [ ] No duplicate create-specific prompt/mapping/dependency/target/export sidecars are produced.",
            "- [ ] If enabled, LAST_GIT_COMMIT.json contains commit metadata and changed-file titles/descriptions.",
            "- [ ] If absolute project paths are enabled, relative originals remain traceable and ZIP members stay portable.",
            "- [ ] Dependencies are referenced through PROMPT_MANIFEST.json, not expanded as package lists in USER_PROMPT.txt.",
            "- [ ] Validation commands are listed or marked as not run with a reason.",
            "- [ ] Rollback point and changed-files-only policy are clear.",
        ]
        (export_dir / "PROMPT_EVAL_CHECKLIST.md").write_text("\n".join(eval_lines) + "\n", encoding="utf-8")
        (export_dir / "USER_PROMPT.txt").write_text(self._create_export_prompt_text(config, build_record) + "\n", encoding="utf-8")

    def _path_is_inside_any_selection(self, rel: str, selected_paths: list[str] | None) -> bool:
        selected = [str(item).replace("\\", "/").strip("/") or "." for item in (selected_paths or []) if str(item).strip()]
        if not selected:
            return True
        normalized = str(rel).replace("\\", "/").strip("/") or "."
        for selected_rel in selected:
            if selected_rel == "." or normalized == selected_rel or normalized.startswith(selected_rel.rstrip("/") + "/"):
                return True
        return False

    def _compact_create_working_tree_context(self, base: Path, config: dict, record: dict | None = None, selected_scope_paths: list[str] | None = None) -> dict:
        """Small, content-free Create Working Tree context for compact exports."""
        try:
            base_path = Path(base).resolve()
        except Exception:
            base_path = Path(str(base))
        files: list[str] = []
        dirs: list[str] = []
        ignore_names = {".git", "node_modules", "venv", ".venv", "dist", "build", "__pycache__", ".pytest_cache", ".mypy_cache"}
        selected_paths = [str(item).replace("\\", "/").strip("/") or "." for item in (selected_scope_paths or []) if str(item).strip()]
        try:
            for path in sorted(base_path.rglob("*")):
                try:
                    rel = path.relative_to(base_path).as_posix()
                except Exception:
                    continue
                if not rel or set(Path(rel).parts) & ignore_names:
                    continue
                if not self._path_is_inside_any_selection(rel, selected_paths):
                    continue
                if path.is_dir():
                    dirs.append(rel)
                elif path.is_file():
                    files.append(rel)
                if len(files) + len(dirs) >= 600:
                    break
        except Exception:
            pass
        absolute_paths = self._create_export_absolute_paths_enabled()
        return {
            "source": "create_working_dir",
            "base": str(base_path),
            "mode": self.create_mode.get(),
            "stack": self.create_stack.get(),
            "target_path": self._compile_project_path_for_export(str(config.get("path") or self.create_target_path.get() or "."), base_path),
            "relative_target_path": str(config.get("path") or self.create_target_path.get() or "."),
            "build_target": str(config.get("build_target") or self.create_build_target.get() or "wrapper"),
            "record_id": str(record.get("id") or "") if isinstance(record, dict) else "",
            "scope_policy": "selected_export_tree_first" if selected_paths else "full_create_working_tree_no_selection",
            "path_policy": self._create_export_path_policy_payload(base_path),
            "selected_scope_paths": self._compile_project_paths_for_export(selected_paths, base_path) if absolute_paths else selected_paths,
            "relative_selected_scope_paths": selected_paths if absolute_paths else [],
            "directory_count": len(dirs),
            "file_count": len(files),
            "directories": self._compile_project_paths_for_export(dirs[:300], base_path) if absolute_paths else dirs[:300],
            "relative_directories": dirs[:300] if absolute_paths else [],
            "files": self._compile_project_paths_for_export(files[:300], base_path) if absolute_paths else files[:300],
            "relative_files": files[:300] if absolute_paths else [],
            "truncated": len(files) + len(dirs) >= 600,
            "mapping": self._create_project_mapping_payload(config),
            "parameters": config.get("create_mode_parameters", self._create_mode_parameter_profile()),
        }

    def _prompt_builder_generated_prompt_text_for_export(self, fallback: str) -> str:
        widget = getattr(self, "prompt_text", None)
        if widget is None:
            return fallback
        try:
            manual = widget.get("1.0", "end").strip()
        except Exception:
            return fallback
        if not manual:
            return fallback
        # The right Prompt Builder box is allowed to be manually edited before
        # export.  Keep it only when it carries meaningful prompt content instead
        # of an empty/stale placeholder.
        if len(manual) >= 40 and ("Menschliche Einordnung" in manual or "Kompilierter Prompt" in manual or "You are now acting as" in manual or "##" in manual):
            return manual
        return fallback

    def _generate_create_export(self, build_record: dict | None = None) -> None:
        self._ensure_create_mode_matches_start_reference("create_export")
        selected_record_ready = False
        if build_record and build_record.get("temp_preview_dir"):
            try:
                selected_record_ready = Path(str(build_record.get("temp_preview_dir"))).exists() and bool(build_record.get("complete", True))
            except Exception:
                selected_record_ready = False
        if not selected_record_ready and not self._can_export_create_context():
            messagebox.showinfo("Create export not ready", "Export requires Build.complete for the current stack or a Start-tab project reference with target match.")
            self._refresh_create_export_button_visibility()
            return
        config = self._current_create_config()
        if self._create_should_include_last_git_commit_reference(config):
            self._ensure_create_last_git_commit_reference(reason="create_export", force=False)
        tasks_payload = self._create_tasks_sidecar_payload()
        record = build_record or self._selected_create_build_record()
        base = self._create_export_base_for_record(record)
        if not base.exists():
            messagebox.showerror("Create export failed", f"Export base does not exist:\n{base}")
            return
        export_dir = self._next_create_export_path()
        old_tree_source = self.project_tree_source_mode.get()
        self.project_tree_source_mode.set("create_working_dir")
        create_scope_paths = self._scope_paths_for_generation() if bool(self.create_include_imports.get()) else self._scope_paths_for_worker()
        # Context sidecars are written after the generator finishes so compact/ZIP
        # exports cannot clean them away. Non-compact folder exports are refreshed
        # there as well, keeping one authoritative write path.
        export_prompt = self._prompt_builder_generated_prompt_text_for_export(self._create_export_prompt_text(config, record))
        targets = [SaveTarget(config.get("path", "."), config.get("path_type", "wrapper"), config.get("ai_target", "ChatGPT"), config.get("profiles", []), config.get("file_types", []))]
        params = {
            "output_base": base,
            "ai_language": self.ai_language.get(),
            "project_name": self.project_name.get().strip(),
            "targets": targets,
            "overwrite": bool(self.overwrite.get()),
            "schema_dir": Path(self.schema_dir.get()),
            "copy_schema": self.copy_schema.get(),
            "create_log": self.create_log.get(),
            "role_date": self.role_date.get().strip() or None,
            "scope_paths": create_scope_paths,
            "export_as_zip": self.create_export_as_zip.get(),
            "export_dir": export_dir,
            "export_prompt_text": export_prompt,
            "selected_reference_ids": config.get("references", []),
            "selected_operation_role_ids": config.get("roles", []),
            "strict_selected_reference_routing": True,
            # Scope was already resolved from the Export tree selection above.
            # Do not run a second hidden import expansion in generate_files.
            "include_imports": False,
            # USER_PROMPT.txt is already the compiled human Create prompt.
            # Do not wrap it again with the generic custom weighted prompt, or the
            # sidecar prompt would reintroduce raw operator/schema scaffolding.
            "custom_prompt_text": "",
            "include_dependency_manifests": self.include_dependency_manifests.get(),
            "changed_files_only": self.create_changed_files_only.get(),
            "compact_export": self.create_compact_export.get(),
            "absolute_project_paths": self._create_export_absolute_paths_enabled(),
            "compact_export_context": {
                "source": "create",
                "export_path_policy": "stable <project>_create_stable when overwrite is ON; otherwise <project>_create_<timestamp>_<id>",
                "path_policy": self._create_export_path_policy_payload(base),
                "overwrite_existing_generated_files": bool(self.overwrite.get()),
                "create_mode": self.create_mode.get(),
                "selected_stack": self.create_stack.get(),
                "selected_chain_entry": config.get("selected_create_chain_entry"),
                "export_intelligence": self._create_export_intelligence_value(),
                "human_prompt_locale_source": "schema/human_prompt_locale.json",
                "chain_schema": config.get("create_chain_schema") or self._create_chain_schema(self.create_mode.get(), [], config),
                "package_control": self._package_control_findings(config),
                "operator_flow": self._operator_flow_contract(),
                "operator_research_plan": self._create_operator_research_plan(config),
                "ai_response_callback": self._ai_response_callback_contract(),
                "progress_manifest": self._progress_json_file_name(),
                "source_clone": self._create_source_clone_manifest or None,
                "last_git_commit_reference": self._last_git_commit_reference_for_manifest(config, reason="compact_export_context"),
                "tasks_sidecar": {"file": "TASKS.TXT", "enabled": bool(str(tasks_payload.get("raw_text") or "").strip()), "parsed_as": tasks_payload.get("parsed_as"), "phase_count": len(tasks_payload.get("task_phases") or [])},
                "shortcut_command_contract": self._human_shortcut_command_contract_lines(),
                "cmd_manifest": self._create_cmd_manifest_payload(config),
                "selected_export_tree_scope": list(create_scope_paths or []),
                "prompt_builder_right_prompt_used": export_prompt != self._create_export_prompt_text(config, record),
                "create_working_tree": self._compact_create_working_tree_context(base, config, record, list(create_scope_paths or [])),
            },
        }
        def worker():
            return generate_files(progress_callback=self._progress_callback, **params)
        def success(messages: list[str]) -> None:
            self.project_tree_source_mode.set("create_working_dir")
            try:
                messages.extend(self._write_create_export_context_sidecars(base, export_dir, config, record))
            except Exception as exc:
                messages.append(f"Create context sidecars skipped: {exc}")
            try:
                self._write_tasks_sidecar_and_patch_manifest(export_dir, tasks_payload)
                self._register_create_context_artifacts_in_export_manifest(export_dir, config)
                messages.extend(self._rewrite_zip_with_create_context_artifacts(export_dir, config))
                messages.extend(self._apply_create_zip_sidecar_contract(export_dir, config, tasks_payload))
            except Exception as exc:
                messages.append(f"TASKS/ZIP sidecar contract skipped: {exc}")
            self._show_text("\n".join(messages + [f"Create export context: {export_dir}"]))
            self._refresh_output_tree()
            self._refresh_project_tree()
            self.notebook.select(self.output_tab)
        def fail_restore(exc: Exception) -> None:
            self.project_tree_source_mode.set(old_tree_source)
            messagebox.showerror("Create export failed", str(exc))
        self._run_background_task("Create context export", worker, success, fail_restore)

    def _export_current_create_build_or_context(self) -> None:
        self._refresh_create_export_button_visibility()
        if not self._can_export_create_context():
            messagebox.showinfo("Create export not ready", "Export is hidden until Build.complete exists for the current stack or the Start tab contains a matching project target.")
            return
        # The inline Export button exports the current stack's completed build first.
        # Selection in the Builds tab is only used by the Builds-tab Export button.
        record = self._active_successful_create_build_for_current_stack()
        if record:
            self.project_tree_source_mode.set("create_working_dir")
            self._generate_create_export(record)
        else:
            self.project_tree_source_mode.set("create_working_dir")
            self._generate_create_export(None)

    def _export_selected_create_build(self) -> None:
        record = self._selected_create_build_record()
        if not record:
            messagebox.showinfo("No build", "No successful Create timeline build is available yet.")
            return
        self._generate_create_export(record)

    def _create_manual_context_summary_lines(self, config: dict | None = None) -> list[str]:
        config = config or self._current_create_config()
        details = self.create_details_text.get("1.0", "end").strip() if hasattr(self, "create_details_text") else ""
        placeholder_map = self._create_placeholder_map() if hasattr(self, "create_placeholder_text") else {}
        default_placeholders = {str(key): str(value) for key, value in dict(config.get("placeholders", {})).items()}
        manual_tokens = [key for key, value in placeholder_map.items() if key not in default_placeholders or str(default_placeholders.get(key, "")).strip() != str(value).strip()]
        catalog_entry = self._find_create_catalog_entry(config=config) if self.create_mode.get() in {"feature_for_existing_project", "refactor_existing_stack"} else None
        hook_tokens = [key for key in manual_tokens if key.startswith("{$hook[")]
        return [
            f"- Prompt details: {'manual text present' if details else 'none'}",
            f"- Selected catalog entry: {catalog_entry.get('display_name') or catalog_entry.get('label') or catalog_entry.get('id') if catalog_entry else 'none'}",
            f"- User/GUI token overrides: {', '.join(manual_tokens) if manual_tokens else 'none'}",
            f"- Hook tokens injected: {', '.join(hook_tokens) if hook_tokens else 'none'}",
            "- Highlight rule: yellow background marks values not auto-generated by the selected project setting.",
        ]

    def _create_contract_text(self, config: dict | None = None) -> str:
        config = config or self._current_create_config()
        details = self.create_details_text.get("1.0", "end").strip() if hasattr(self, "create_details_text") else ""
        clean = self.create_clean_project.get()
        do_not_normalize = self.create_do_not_normalize.get()
        hooks = self._create_matching_hooks(config) if self.create_schema_mirror.get() else []
        weight_ids = self._create_matching_weights(hooks)
        timeline = self._selected_create_timeline_lines()
        tree_rows = self._create_preview_tree_model()
        tree_lines = [f"[{row.get('effective_target') or 'ignored'}] {row.get('path')} ({row.get('role')}, {row.get('boilerplate')}, structure={row.get('code_structure_label') or 'none'})" for row in tree_rows] or self._editable_text_lines("create_project_tree_text", config.get("tree", []))
        placeholder_lines = self._editable_text_lines("create_placeholder_text", config.get("placeholders", {}))
        artifacts = list(config.get("artifacts", []))
        if self.create_zip_contract.get():
            for required in ["USER_PROMPT.txt", "EXPORT_MANIFEST.json", "PROMPT_MANIFEST.json"]:
                if required not in artifacts:
                    artifacts.append(required)
        return "\n".join([
            "# CREATE PROJECT MAPPING CONTRACT",
            f"Mode: {self.create_mode.get()}",
            f"Stack category: {config.get('category', self.create_stack_category.get())}",
            f"Stack: {self.create_stack.get()}",
            f"Target path: {config.get('path', self.create_target_path.get().strip() or '.')}",
            f"Create-only working path: {self._display_create_working_path()}",
            f"Create-only export dir: {self._display_create_export_dir()}",
            f"Build hook target: {config.get('build_target', self.create_build_target.get())}",
            f"Path type: {config.get('path_type', 'wrapper')}",
            f"AI target: {config.get('ai_target', 'ChatGPT')}",
            f"Version policy: {self.create_lts_policy.get()} — do not invent exact versions; use selected manifest/evidence or user-supplied versions.",
            f"Create mode routine: {(config.get('create_mode_context') or {}).get('routine', 'create_new_abstraction')}",
            f"Create mode weights: {', '.join(config.get('create_weight_profiles', [])) or 'schema/default weights'}",
            "Create mode parameter table:",
            *self._format_create_parameter_profile(config),
            f"NVM version: {self._normalize_nvm_version(self.create_nvm_version.get() or 'None') or 'None'}",
            f"NVM path: {self._selected_nvm_root_path_text() or 'auto'}",
            f"Gradle version: {self._normalize_gradle_version(self.create_gradle_version.get() or 'None') or 'None'}",
            f"Gradle path: {self._selected_runtime_path_text('gradle') or 'auto'}",
            f"Python version: {self._normalize_python_version(self.create_python_version.get() or 'None') or 'None'}",
            f"Python path: {self._selected_python_path_text() or 'auto'}",
            f"Flutter version/path: {self._normalize_generic_version(self.create_flutter_version.get()) or 'None'} / {self._selected_runtime_path_text('flutter') or 'auto'}",
            f".NET version/path: {self._normalize_generic_version(self.create_dotnet_version.get()) or 'None'} / {self._selected_runtime_path_text('dotnet') or 'auto'}",
            f"Go version/path: {self._normalize_generic_version(self.create_go_version.get()) or 'None'} / {self._selected_runtime_path_text('go') or 'auto'}",
            f"Rust version/path: {self._normalize_generic_version(self.create_rust_version.get()) or 'None'} / {self._selected_runtime_path_text('rust') or 'auto'}",
            f"Java version/path: {self._normalize_generic_version(self.create_yesva_version.get()) or 'None'} / {self._selected_runtime_path_text('yesva') or 'auto'}",
            f"CMake version/path: {self._normalize_generic_version(self.create_cmake_version.get()) or 'None'} / {self._selected_runtime_path_text('native') or 'auto'}",
            f"Dockerfile: {self._selected_runtime_path_text('docker') or 'auto'}",
            f"Compiler path: {self._selected_create_compiler_path_text() or 'none'}",
            f"File types: {', '.join(config.get('file_types', []))}",
            f"Boilerplate profiles: {', '.join(config.get('profiles', []))}",
            f"Reference domains: {', '.join(config.get('references', [])) or 'none selected'}",
            f"Operation roles: {', '.join(config.get('roles', [])) or 'none selected'}",
            f"AI operator execution mode: {self._operator_flow_contract().get('execution_mode')}",
            f"AI operator/references research: {'yes' if self._create_operator_research_plan(config).get('enabled') else 'no'}",
            f"Schema hooks: {', '.join(hook.get('id', '') for hook in hooks) if hooks else 'not mirrored / no matching hooks'}",
            f"Weight profiles: {', '.join(weight_ids) if weight_ids else 'not mirrored / no matching weights'}",
            "",
            "Manual/user-injected state:",
            *self._create_manual_context_summary_lines(config),
            "",
            "Project mapping:",
            *self._format_create_project_mapping(config),
            "",
            "Dependency groups:",
            *self._format_create_dependency_groups(config),
            "",
            "Package dependency layer:",
            *self._format_create_dependency_layer(config),
            "",
            "Micro tasks:",
            *self._format_create_micro_tasks(config),
            "",
            "Terminal timeline steps:",
            *[f"{index + 1}) {line}" for index, line in enumerate(timeline)],
            "",
            "Editable token map:",
            *(placeholder_lines or ["- none"]),
            "",
            "Chainable mode boilerplates:",
            *self._format_create_chain_boilerplates(config),
            "",
            "Target match boilerplate:",
            *self._format_stack_bound_modules("target_match_boilerplates", config),
            "",
            "Feature modules:",
            *self._format_stack_bound_modules("feature_modules", config),
            "",
            "Refactor modules:",
            *self._format_stack_bound_modules("refactor_modules", config),
            "",
            "Sequential operator/reference research plan:",
            *self._format_create_operator_research_plan(config),
            "",
            "Project tree blueprint:",
            *(tree_lines or ["- no tree blueprint supplied"]),
            "",
            "Output contract:",
            "- Generate only the files/artifacts required by this selected stack and target path.",
            "- Every command in the timeline must be target-scoped to wrapper, backend, frontend, assets or generated.",
            "- Package rows must land in the target-specific manifest and keep package, version, install token and validation token aligned.",
            "- Live-edited timeline tokens such as {$npm_run_build} and {$install_node[dependency_version]} stay explicit until the implementation target resolves them.",
            "- The editable project tree is compiled into a temp preview; Run keeps output in temp/export only.",
            "- Only one wrapper, backend and frontend root target may exist; structures outside a target-root parent are ignored.",
            "- ZIP export remains compatible: final ZIP, USER_PROMPT.txt and EXPORT_MANIFEST.json must describe the same artifact set.",
            "- Create-only export stays isolated from Generator/Project Tree export unless the user explicitly copies the path there.",
            "- Compile writes/refreshes temp preview state; Run never writes the Start working tree and executes checked timeline steps only in temp/export context.",
            "",
            "Generated/exported artifacts to track:",
            *[f"- {artifact}" for artifact in artifacts],
            "",
            "Non-goals:",
            "- No broad rewrite of unrelated tabs or generator internals.",
            "- No duplicate parallel schema structures when existing hooks/weights/references can be extended.",
            "- No invented commands, folders, frameworks, legal facts, physical constants or package versions.",
            "",
            "Special constraints:",
            f"- Clean Project: {'yes' if clean else 'no'} — remove/generated noise only through an explicit output contract.",
            f"- Do not normalize: {'yes' if do_not_normalize else 'no'} — preserve authoritative source terms, identifiers and domain distinctions.",
            f"- Include imports: {'yes' if self.create_include_imports.get() else 'no'}.",
            f"- Changed files only: {'yes' if self.create_changed_files_only.get() else 'no'}.",
            f"- Package control findings must be handled before implementation acceptance: {len(self._package_control_findings(config).get('missing', []))} missing / {len(self._package_control_findings(config).get('unused', []))} unused.",
            f"- Operator flow: {self._operator_flow_contract().get('export_instruction')}",
            f"- Operator/reference research gate: {self._operator_flow_contract().get('research_instruction')}",
            "- Acceptance requires changed files/artifacts, validation posture, rollback point and known gaps.",
            "",
            "User details:",
            details or "- No additional details supplied.",
        ])

    def _apply_create_context(self) -> None:
        config = self._current_create_config()
        self.path_var.set(config.get("path", self.create_target_path.get().strip() or "."))
        self.path_type_var.set(config.get("path_type", "wrapper"))
        self.ai_target_var.set(config.get("ai_target", "ChatGPT"))
        selected_profiles = set(config.get("profiles", []))
        if self.create_clean_project.get():
            selected_profiles.add("CleanProject")
        if self.create_do_not_normalize.get():
            selected_profiles.add("DoNotNormalize")
        for profile_id, var in self.profile_vars.items():
            var.set(profile_id in selected_profiles)
        selected_file_types = set(config.get("file_types", []))
        for file_type_id, var in self.file_type_vars.items():
            var.set(file_type_id in selected_file_types)
        # Libraries Editor selections are editor/preview state only. Do not mirror
        # Create-derived references/roles into those checkboxes; Create carries
        # its own routing config into the generated contract/export.
        selected_refs = set(config.get("references", []))
        if self.create_clean_project.get():
            selected_refs.add("clean_project_reference")
        if self.create_do_not_normalize.get():
            selected_refs.add("do_not_normalize_reference")
        if self.include_dependency_manifests.get() or "DependencyManifestExport" in selected_profiles:
            selected_refs.add("dependency_manifest_export_reference")
        selected_roles = set(config.get("roles", []))
        if self.include_dependency_manifests.get() or "DependencyManifestExport" in selected_profiles:
            selected_roles.add("dependency_manifest_export_operator")
        if self.create_zip_contract.get():
            self.create_export_as_zip.set(True)
            self.copy_schema.set(True)
        self._refresh_reference_preview()
        self._add_or_update_target()
        previous_left_input = self._prompt_builder_custom_task_text() if hasattr(self, "custom_prompt_text") else ""
        contract = self._create_export_prompt_text(config, self._active_successful_create_build_for_current_stack())
        if hasattr(self, "custom_prompt_text"):
            merged_contract = self._merge_prompt_builder_left_input_into_process(contract, previous_left_input)
            self.custom_prompt_text.delete("1.0", "end")
            self.custom_prompt_text.insert("1.0", merged_contract)
        if hasattr(self, "create_contract_preview"):
            self.create_contract_preview.delete("1.0", "end")
            self.create_contract_preview.insert("1.0", contract)
            self._apply_text_widget_theme()
            self._highlight_create_contract_manual_blocks()
        self._set_progress("Project mapping applied: target, schema selection, timeline and export contract resolved", 1, 1)

    def _build_create_prompt_preview(self) -> None:
        self._apply_create_context()
        self._build_custom_prompt_preview()


    # ---------- Micro Tasks Tab ----------
    def _build_micro_tasks_tab(self) -> None:
        root = self.micro_tasks_tab
        top = ttk.LabelFrame(root, text="Micro Tasks", padding=10)
        top.pack(fill="x")
        ttk.Label(
            top,
            text=(
                "Schema-backed micro tasks live inside Libraries. Select a task to inspect its full contract, then run it when "
                "the task has an exportable artifact. Generated content is written under the shared Custom Export Path."
            ),
            wraplength=1080,
        ).grid(row=0, column=0, columnspan=5, sticky="w", pady=(0, 8))
        ttk.Label(top, text="Custom Export Path").grid(row=1, column=0, sticky="w", pady=4)
        ttk.Entry(top, textvariable=self.export_dir, width=58).grid(row=1, column=1, sticky="ew", padx=(8, 8), pady=4)
        ttk.Button(top, text="Browse", command=self._browse_export_dir).grid(row=1, column=2, sticky="w", pady=4)
        ttk.Button(top, text="Run Selected TASK", command=self._run_selected_micro_task).grid(row=1, column=3, sticky="w", padx=(8, 0), pady=4)
        ttk.Button(top, text="Refresh", command=self._refresh_micro_tasks_catalog).grid(row=1, column=4, sticky="w", padx=(8, 0), pady=4)
        top.columnconfigure(1, weight=1)

        body = ttk.PanedWindow(root, orient="horizontal")
        body.pack(fill="both", expand=True, pady=(10, 0))
        left = ttk.LabelFrame(body, text="Schema create_micro_tasks", padding=8)
        right = ttk.LabelFrame(body, text="Task output", padding=8)
        body.add(left, weight=1)
        body.add(right, weight=1)

        columns = ("id", "phase", "outputs", "validation")
        task_frame = ttk.Frame(left)
        task_frame.pack(fill="both", expand=True)
        self.micro_tasks_tree = ttk.Treeview(task_frame, columns=columns, show="headings", height=18)
        for col, title, width in [
            ("id", "ID", 210),
            ("phase", "Phase", 110),
            ("outputs", "Outputs", 220),
            ("validation", "Validation", 220),
        ]:
            self.micro_tasks_tree.heading(col, text=title)
            self.micro_tasks_tree.column(col, width=width, stretch=True)
        yscroll = ttk.Scrollbar(task_frame, orient="vertical", command=self.micro_tasks_tree.yview)
        self.micro_tasks_tree.configure(yscrollcommand=yscroll.set)
        self.micro_tasks_tree.grid(row=0, column=0, sticky="nsew")
        yscroll.grid(row=0, column=1, sticky="ns")
        task_frame.rowconfigure(0, weight=1)
        task_frame.columnconfigure(0, weight=1)
        self.micro_tasks_output_text = self._pack_text_with_scrollbars(right, wrap="word", height=18)
        self.micro_tasks_tree.bind("<<TreeviewSelect>>", self._on_micro_task_selected, add="+")
        self._refresh_micro_tasks_catalog()

    def _refresh_micro_tasks_catalog(self) -> None:
        if not hasattr(self, "micro_tasks_tree"):
            return
        self.micro_tasks_tree.delete(*self.micro_tasks_tree.get_children())
        for task in self._micro_task_records():
            outputs = ", ".join(str(item) for item in task.get("outputs", [])[:4])
            validation = ", ".join(str(item) for item in task.get("validation", [])[:4])
            self.micro_tasks_tree.insert("", "end", values=(task.get("id", ""), task.get("phase", ""), outputs, validation))

    def _micro_task_records(self) -> list[dict]:
        records = []
        for task in self.schema.get("create_micro_tasks", []):
            if isinstance(task, dict):
                records.append(task)
        return records

    def _selected_micro_task(self) -> dict | None:
        tree = getattr(self, "micro_tasks_tree", None)
        if tree is None:
            return None
        try:
            selection = tree.selection()
            if not selection:
                return None
            values = tree.item(selection[0], "values") or []
            task_id = str(values[0] if values else "")
        except Exception:
            return None
        for task in self._micro_task_records():
            if str(task.get("id", "")) == task_id:
                return task
        return None

    def _micro_task_to_markdown(self, task: dict) -> str:
        lines = [
            f"# Mikro Task: {task.get('label') or task.get('id') or 'selected task'}",
            "",
            f"ID: `{task.get('id', '')}`",
            f"Phase: `{task.get('phase', '')}`",
            "",
            "## Purpose",
            str(task.get("purpose") or task.get("description") or "Schema-backed task contract from create_micro_tasks."),
            "",
        ]
        for key, title in [
            ("target_path_types", "Target path types"),
            ("timeline_tokens", "Timeline tokens"),
            ("tokens", "Tokens"),
            ("outputs", "Outputs"),
            ("validation", "Validation"),
            ("steps", "Steps"),
        ]:
            values = task.get(key)
            if isinstance(values, list) and values:
                lines.extend([f"## {title}"])
                lines.extend(f"- `{value}`" if "token" in key else f"- {value}" for value in values)
                lines.append("")
        lines.extend(["## Raw task JSON", "```json", json.dumps(task, indent=2, ensure_ascii=False), "```", ""])
        return "\n".join(lines)

    def _on_micro_task_selected(self, _event=None) -> None:
        task = self._selected_micro_task()
        if task is None:
            return
        try:
            self.micro_tasks_output_text.configure(state="normal")
        except Exception:
            pass
        self.micro_tasks_output_text.delete("1.0", "end")
        self.micro_tasks_output_text.insert("1.0", self._micro_task_to_markdown(task))
        self._apply_text_widget_theme()

    def _run_selected_micro_task(self) -> None:
        task = self._selected_micro_task()
        if task is None:
            messagebox.showinfo("Micro Tasks", "Select a micro task first.")
            return
        task_id = str(task.get("id") or "")
        exportable_tree_tokens = {"{$create_target[wrapper]}", "{$write_export_manifest}"}
        tokens = set(str(item) for item in task.get("timeline_tokens", []) + task.get("tokens", [])) if isinstance(task, dict) else set()
        outputs = " ".join(str(item).lower() for item in task.get("outputs", []))
        if task_id in {"task_create_target_tree", "project_to_markdown", "task_write_export_manifest"} or exportable_tree_tokens.intersection(tokens) or "project tree" in outputs or "artifact list" in outputs:
            self._run_micro_task_project_to_markdown()
            return
        export_dir = self._resolve_export_path(self.export_dir.get(), "custom-export")
        export_dir.mkdir(parents=True, exist_ok=True)
        safe_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", task_id or "selected_task").strip("._-") or "selected_task"
        out_file = export_dir / f"{safe_id}.md"
        content = self._micro_task_to_markdown(task)
        out_file.write_text(content, encoding="utf-8")
        self.micro_tasks_output_text.delete("1.0", "end")
        self.micro_tasks_output_text.insert("1.0", f"Task contract exported: {out_file}\n\n" + content[:12000])
        self._refresh_output_tree()
        self._apply_text_widget_theme()

    def _project_scope_to_markdown(self, scope: dict) -> str:
        files = scope.get("file_references", []) or []
        dirs = scope.get("directory_references", []) or []
        warnings = scope.get("warnings", []) or []
        lines = [
            "# Project Tree",
            "",
            f"Root: `{scope.get('root', '')}`",
            f"Mode: `{scope.get('mode', '')}`",
            f"Files counted: **{scope.get('file_count', len(files))}**",
            f"Directories counted: **{scope.get('directory_count', len(dirs))}**",
            f".gitignore respected: **{scope.get('gitignore_respected', True)}**",
            "",
            "## Directories",
        ]
        lines.extend(f"- `{item.get('path')}`" for item in dirs)
        lines.extend(["", "## Files"])
        for item in files:
            size = item.get("size_bytes")
            size_text = f" — {size} bytes" if size is not None else ""
            modified = item.get("modified_at")
            modified_text = f" — modified {modified}" if modified else ""
            lines.append(f"- `{item.get('path')}`{size_text}{modified_text}")
        if warnings:
            lines.extend(["", "## Warnings"])
            lines.extend(f"- {warning}" for warning in warnings)
        lines.append("")
        return "\n".join(lines)

    def _run_micro_task_project_to_markdown(self) -> None:
        base = self._active_project_tree_base().expanduser().resolve()
        export_dir = self._resolve_export_path(self.export_dir.get(), "custom-export")
        scope_paths = self._scope_paths_for_worker()

        def worker():
            scope = build_project_scope(base, scope_paths=scope_paths, export_dir=export_dir, progress_callback=self._progress_callback)
            out_dir = export_dir
            out_dir.mkdir(parents=True, exist_ok=True)
            out_file = out_dir / "PROJECT_TREE.md"
            out_file.write_text(self._project_scope_to_markdown(scope), encoding="utf-8")
            return out_file, scope

        def success(result) -> None:
            out_file, scope = result
            text = [
                f"PROJECT_TREE.md written: {out_file}",
                f"Files: {scope.get('file_count', 0)}",
                f"Directories: {scope.get('directory_count', 0)}",
                "",
                out_file.read_text(encoding="utf-8")[:12000],
            ]
            self.micro_tasks_output_text.delete("1.0", "end")
            self.micro_tasks_output_text.insert("1.0", "\n".join(text))
            self._refresh_output_tree()
            self._apply_text_widget_theme()

        self._run_background_task("Project to Markdown", worker, success)

