    def _patch_use_git_to_patch_enabled(self) -> bool:
        try:
            return bool(self.patch_use_git_to_patch.get())
        except Exception:
            return False

    def _patch_target_mode(self) -> str:
        raw = ""
        try:
            raw = str(self.patch_target_tree_mode.get() or "").strip()
        except Exception:
            raw = ""
        return raw if raw in {"create_temp", "working_project_tree"} else "create_temp"

    def _patch_target_label(self) -> str:
        return "Working/Project Tree" if self._patch_target_mode() == "working_project_tree" else "Create Temp Preview"

    def _patch_direct_project_live_root(self) -> Path | None:
        candidates: list[Path] = []
        ref = self._patch_reference_working_tree_root()
        if ref is not None:
            candidates.append(ref)
        try:
            candidates.append(self._create_working_dir())
        except Exception:
            pass
        seen: set[str] = set()
        for candidate in candidates:
            try:
                root = Path(candidate).expanduser().resolve()
                key = str(root)
                if key in seen:
                    continue
                seen.add(key)
                if root.exists() and root.is_dir() and not self._path_is_under_system_temp(root):
                    return root
            except Exception:
                continue
        return None

    def _patch_active_live_root(self, *, materialize: bool = False) -> Path | None:
        if self._patch_target_mode() == "working_project_tree":
            return self._patch_direct_project_live_root()
        return self._patch_create_temp_live_root(materialize=materialize)

    def _on_patch_target_tree_changed(self, _event=None) -> None:
        try:
            self.patch_target_tree_status.set(f"Patch target: {self._patch_target_label()}")
        except Exception:
            pass
        try:
            self._patch_session_root = None
            self._patch_live_root = None
            self._patch_stage_root = None
            self._patch_baseline_root = None
        except Exception:
            pass
        self._refresh_patch_status()

    def _patch_work_root(self) -> Path:
        """Return Patch metadata root for the selected Patch target.

        Staging metadata stays outside the user project. The cache key includes
        the selected target mode and resolved live root so Create-temp branches
        and direct Working/Project-Tree branches never share staged files.
        """
        raw = ""
        try:
            active = self._patch_active_live_root(materialize=False)
            raw = str(active or "")
        except Exception:
            raw = ""
        if not raw:
            try:
                raw = self.create_temp_preview_dir.get().strip()
            except Exception:
                raw = ""
        seed = f"{self._patch_target_mode()}::{raw}"
        key = hashlib.sha1(seed.encode("utf-8", errors="ignore")).hexdigest()[:12] if raw else f"no_{self._patch_target_mode()}"
        root = Path(tempfile.gettempdir()) / "prompt-guide-patch-work" / key
        root.mkdir(parents=True, exist_ok=True)
        return root

    def _patch_branch_slug(self, branch: str | None = None) -> str:
        raw = str(branch or self.patch_branch_name.get() or "main").strip() or "main"
        safe = re.sub(r"[^A-Za-z0-9._-]+", "-", raw).strip(".-_") or "main"
        return safe[:80]

    def _patch_branch_root(self) -> Path:
        root = self._patch_work_root() / "branches" / self._patch_branch_slug()
        root.mkdir(parents=True, exist_ok=True)
        return root

    def _patch_available_branches(self) -> list[str]:
        branches = {"main"}
        try:
            root = self._patch_work_root() / "branches"
            if root.exists():
                for child in root.iterdir():
                    if child.is_dir():
                        branches.add(child.name)
        except Exception:
            pass
        current = self._patch_branch_slug()
        branches.add(current)
        return sorted(branches, key=lambda item: (item != "main", item.lower()))

    def _refresh_patch_branch_ui(self) -> None:
        branch = self._patch_branch_slug()
        try:
            if self.patch_branch_name.get() != branch:
                self.patch_branch_name.set(branch)
        except Exception:
            pass
        try:
            self.patch_branch_stage_label.set(f"Stage branch: {branch}")
        except Exception:
            pass
        box = getattr(self, "patch_branch_box", None)
        if box is not None:
            try:
                box.configure(values=self._patch_available_branches())
            except Exception:
                pass

    def _on_patch_branch_changed(self, _event=None) -> None:
        self._refresh_patch_branch_ui()
        self._refresh_patch_status()

    def _patch_reference_working_tree_root(self) -> Path | None:
        """Read-only Start-tab Working Tree reference for optional git status.

        Patch never stages or commits into this path. External IDE changes may be
        visible through git status, but this tool does not write there.
        """
        try:
            start = self._normalize_start_working_tree().resolve()
            if start.exists() and start.is_dir() and not self._path_is_under_system_temp(start):
                return start
        except Exception:
            pass
        return None

    def _patch_create_temp_live_root(self, *, materialize: bool = False) -> Path | None:
        """Return the current Create temp build root that Patch is allowed to mutate."""
        candidates: list[Path] = []
        try:
            raw = self.create_temp_preview_dir.get().strip()
            if raw:
                candidates.append(Path(raw))
        except Exception:
            pass
        # Do not use Build.complete or the Start Working Tree here. Patch is only
        # allowed to mutate the active Create temp preview root.
        if materialize:
            try:
                if hasattr(self, "create_preview_tree") and self.create_preview_tree.get_children(""):
                    candidates.append(self._materialize_create_temp_tree(force=False, log=False))
            except Exception:
                pass
        for candidate in candidates:
            try:
                root = candidate.resolve()
                if root.exists() and root.is_dir() and self._path_is_under_system_temp(root) and "prompt-guide-create-preview" in str(root):
                    try:
                        self.create_temp_preview_dir.set(str(root))
                    except Exception:
                        pass
                    return root
            except Exception:
                continue
        return None

    def _patch_project_root(self) -> Path:
        """Backward-compatible alias for the selected Patch live target."""
        root = self._patch_active_live_root(materialize=False)
        if root is None:
            raise RuntimeError("Patch target is missing. Create a temp preview or assign a Working/Project Tree in the Start/Create tab.")
        return root

    def _patch_git_root(self, path: Path) -> Path | None:
        try:
            completed = subprocess.run(["git", "-C", str(path), "rev-parse", "--show-toplevel"], capture_output=True, text=True, timeout=2.5)
            if completed.returncode != 0:
                return None
            root = Path(completed.stdout.strip()).resolve()
            return root if root.exists() else None
        except Exception:
            return None

    def _patch_git_status_payload_for_root(self, root: Path | None) -> dict:
        if root is None:
            return {"available": False, "reason": "no Start working tree reference"}
        git_root = self._patch_git_root(root)
        if not git_root:
            return {"available": False, "reason": "no git repo"}
        try:
            root_resolved = root.resolve()
            # Only trust git if the selected Start/Project root is inside exactly that repo.
            root_resolved.relative_to(git_root)
        except Exception:
            return {"available": False, "reason": "working tree does not match git root", "git_root": str(git_root)}
        try:
            branch = subprocess.run(["git", "-C", str(git_root), "branch", "--show-current"], capture_output=True, text=True, timeout=2.5)
            status = subprocess.run(["git", "-C", str(git_root), "status", "--porcelain=v1", "--branch", "--untracked-files=normal"], capture_output=True, text=True, timeout=4.0)
            status_text = status.stdout.strip()
            status_lines = [line for line in status_text.splitlines() if line.strip()]
            changed_lines = [line for line in status_lines if not line.startswith("##")]
            return {
                "available": status.returncode == 0,
                "git_root": str(git_root),
                "branch": branch.stdout.strip() or "main",
                "status_porcelain_v1": status_text,
                "raw_status": status_text,
                "dirty": bool(changed_lines),
                "changed_entry_count": len(changed_lines),
                "returncode": status.returncode,
                "source": "patch_tab_git_reference",
                "read_only": True,
            }
        except Exception as exc:
            return {"available": False, "reason": str(exc), "git_root": str(git_root), "source": "patch_tab_git_reference", "read_only": True}

    def _last_commit_file_title(self, path: object) -> str:
        name = Path(str(path or "file").replace("\\", "/")).name or str(path or "file")
        stem = Path(name).stem or name
        title = re.sub(r"[_\-.]+", " ", stem).strip().title()
        return title or name

    def _last_commit_status_label(self, status: object) -> str:
        code = str(status or "").strip().upper()
        prefix = code[:1]
        labels = {
            "A": "added",
            "M": "modified",
            "D": "deleted",
            "R": "renamed",
            "C": "copied",
            "T": "type_changed",
            "U": "unmerged",
            "X": "unknown",
        }
        return labels.get(prefix, "changed")

    def _last_commit_file_description(self, status: object, path: object, old_path: object = "") -> str:
        label = self._last_commit_status_label(status)
        path_text = str(path or "").replace("\\", "/")
        old_text = str(old_path or "").replace("\\", "/")
        descriptions = {
            "added": f"Newly added in the last commit: {path_text}.",
            "modified": f"Changed in the last commit: {path_text}.",
            "deleted": f"Im letzten Commit entfernt: {path_text}.",
            "renamed": f"Im letzten Commit umbenannt von {old_text} nach {path_text}.",
            "copied": f"Im letzten Commit kopiert von {old_text} nach {path_text}.",
            "type_changed": f"File type/mode was changed in the last commit: {path_text}.",
            "unmerged": f"Im letzten Commit als Konflikt-/Merge-bezogen markiert: {path_text}.",
        }
        return descriptions.get(label, f"Touched in the last commit: {path_text}.")

    def _parse_last_commit_changed_files(self, status_text: str, base: Path | str | None = None) -> list[dict]:
        rows: list[dict] = []
        for raw_line in str(status_text or "").splitlines():
            line = raw_line.strip("\n")
            if not line.strip():
                continue
            parts = line.split("\t")
            status = parts[0].strip() if parts else ""
            old_path = ""
            path = ""
            if status.startswith(("R", "C")) and len(parts) >= 3:
                old_path = parts[1].strip()
                path = parts[2].strip()
            elif len(parts) >= 2:
                path = parts[1].strip()
            else:
                path = line.strip()
            if not path:
                continue
            row = {
                "status": status,
                "change_type": self._last_commit_status_label(status),
                "path": path.replace("\\", "/"),
                "title": self._last_commit_file_title(path),
                "description": self._last_commit_file_description(status, path, old_path),
            }
            if old_path:
                row["old_path"] = old_path.replace("\\", "/")
            if self._create_export_absolute_paths_enabled():
                row["relative_path"] = row["path"]
                row["path"] = self._compile_project_path_for_export(row["path"], base)
                if old_path:
                    row["relative_old_path"] = row.get("old_path", "")
                    row["old_path"] = self._compile_project_path_for_export(old_path, base)
            rows.append(row)
        return rows

    def _read_last_git_commit_reference(self, git_root: Path | str | None) -> dict:
        if git_root is None:
            return {"available": False, "reason": "no git root"}
        try:
            root = Path(str(git_root)).resolve()
        except Exception:
            return {"available": False, "reason": "invalid git root"}
        if not root.exists():
            return {"available": False, "reason": "git root does not exist", "git_root": str(root)}
        try:
            completed = subprocess.run(
                ["git", "-C", str(root), "log", "-1", "--date=iso-strict", "--format=%H%x1f%h%x1f%an%x1f%ae%x1f%aI%x1f%cn%x1f%cI%x1f%s"],
                capture_output=True,
                text=True,
                timeout=4.0,
            )
            if completed.returncode != 0:
                return {"available": False, "reason": completed.stderr.strip() or "git log failed", "git_root": str(root), "returncode": completed.returncode}
            parts = (completed.stdout.strip().split("\x1f") + [""] * 8)[:8]
            full_hash, short_hash, author_name, author_email, author_date_iso, committer_name, committer_date_iso, subject = [part.strip() for part in parts]
            if not full_hash:
                return {"available": False, "reason": "no commits found", "git_root": str(root)}

            body_completed = subprocess.run(
                ["git", "-C", str(root), "log", "-1", "--format=%B"],
                capture_output=True,
                text=True,
                timeout=4.0,
            )
            body = body_completed.stdout.strip() if body_completed.returncode == 0 else ""

            changed_completed = subprocess.run(
                ["git", "-C", str(root), "show", "--name-status", "--format=", "--find-renames", "--find-copies", "HEAD"],
                capture_output=True,
                text=True,
                timeout=4.0,
            )
            changed_status = changed_completed.stdout.strip() if changed_completed.returncode == 0 else ""
            changed_files = self._parse_last_commit_changed_files(changed_status, root)

            stat_completed = subprocess.run(
                ["git", "-C", str(root), "show", "--stat", "--summary", "--format=", "HEAD"],
                capture_output=True,
                text=True,
                timeout=4.0,
            )
            stat_summary = stat_completed.stdout.strip() if stat_completed.returncode == 0 else ""

            return {
                "available": True,
                "git_root": str(root),
                "hash": full_hash,
                "short_hash": short_hash,
                "author_name": author_name,
                "author_email": author_email,
                "author_date_iso": author_date_iso,
                "committer_name": committer_name,
                "committer_date_iso": committer_date_iso,
                "subject": subject,
                "body": body,
                "changed_file_count": len(changed_files),
                "changed_files": changed_files,
                "name_status": changed_status,
                "stat_summary": stat_summary,
            }
        except Exception as exc:
            return {"available": False, "reason": str(exc), "git_root": str(root)}

    def _last_git_commit_plan_ids(self) -> set[str]:
        return {
            "feature_last_git_commit_reference",
            "refactor_last_git_commit_hardening",
            "last_git_commit_feature_slice",
            "last_git_commit_hardening_slice",
        }

    def _entry_is_last_git_commit_plan(self, entry: dict | None = None) -> bool:
        if entry is None and hasattr(self, "create_catalog_entry"):
            entry = self._find_create_catalog_entry()
        if not isinstance(entry, dict):
            return False
        text = " ".join(str(entry.get(key) or "") for key in ("id", "label", "display_name", "intent", "template", "context_hint")).lower()
        return str(entry.get("id") or "").strip() in self._last_git_commit_plan_ids() or ("last" in text and "git" in text and "commit" in text)

    def _entry_mentions_git(self, entry: dict | None = None) -> bool:
        if entry is None and hasattr(self, "create_catalog_entry"):
            entry = self._find_create_catalog_entry()
        if not isinstance(entry, dict):
            return False
        text_parts = [str(entry.get(key) or "") for key in ("id", "label", "display_name", "intent", "template", "context_hint", "schema_family", "specialization", "specialization_label")]
        for key in ("tokens", "timeline_tokens", "validation_focus", "acceptance", "non_goals", "references"):
            value = entry.get(key)
            if isinstance(value, list):
                text_parts.extend(str(item) for item in value)
            elif isinstance(value, dict):
                text_parts.append(json.dumps(value, ensure_ascii=False))
            elif value:
                text_parts.append(str(value))
        text = " ".join(text_parts).lower()
        return "git" in text

    def _entry_requires_last_git_commit_export(self, entry: dict | None = None, config: dict | None = None) -> bool:
        if isinstance(config, dict) and entry is None:
            selected = config.get("selected_create_chain_entry")
            entry = selected if isinstance(selected, dict) else None
        if entry is None and hasattr(self, "create_catalog_entry"):
            entry = self._find_create_catalog_entry()
        if not isinstance(entry, dict):
            return False
        mode = str((config or {}).get("mode") or (self.create_mode.get() if hasattr(self, "create_mode") else ""))
        # Explicit Last-Git plans always require the artifact. In Feature mode,
        # every Git-related feature slice receives the same reference so the
        # downstream AI has the exact previous commit as context.
        return self._entry_is_last_git_commit_plan(entry) or (mode == "feature_for_existing_project" and self._entry_mentions_git(entry))

    def _sync_last_git_commit_export_checkbox(self, enabled: bool, *, reason: str = "catalog_selection") -> None:
        try:
            current = bool(self.create_export_last_git_commit.get())
            target = bool(enabled)
            if current != target:
                self.create_export_last_git_commit.set(target)
                state = "enabled" if target else "disabled"
                self._set_progress(f"LAST-GIT-COMMIT export auto-{state} ({reason})", 0)
        except Exception:
            pass

    def _create_should_include_last_git_commit_reference(self, config: dict | None = None) -> bool:
        try:
            if bool(self.create_export_last_git_commit.get()):
                return True
        except Exception:
            pass
        if isinstance(config, dict):
            selected = config.get("selected_create_chain_entry")
            return self._entry_requires_last_git_commit_export(selected if isinstance(selected, dict) else None, config=config)
        return self._entry_requires_last_git_commit_export()

    def _create_tab_git_status_signature(self) -> str:
        root = self._patch_reference_working_tree_root()
        return "|".join([
            str(root or ""),
            str(self.create_mode.get() if hasattr(self, "create_mode") else ""),
            str(self.create_stack.get() if hasattr(self, "create_stack") else ""),
            str(self.create_target_path.get() if hasattr(self, "create_target_path") else ""),
        ])

    def _ensure_create_tab_git_status_scan(self, reason: str = "create_tab_activated", *, force: bool = False) -> dict:
        """Scan Git status once when Create is opened, reusing the Patch-tab routine.

        The scan is read-only and stores repo/branch/dirty metadata for later
        reference. Last commit details are loaded only by the Last-Git-Commit
        plan or the export checkbox, so a passive Create-tab visit does not
        over-inject Referenz D into USER_PROMPT.
        """
        signature = self._create_tab_git_status_signature()
        if not force and self._create_tab_git_status_scan_signature == signature and isinstance(self._create_tab_git_status_payload, dict) and self._create_tab_git_status_payload:
            self._update_create_git_reference_status(self._create_tab_git_status_payload)
            return self._create_tab_git_status_payload
        payload = self._patch_git_status_payload_for_root(self._patch_reference_working_tree_root())
        payload = dict(payload)
        payload["enabled"] = False
        payload["scan_reason"] = reason
        payload["source"] = "patch_tab_git_reference"
        payload["read_only"] = True
        payload["last_commit"] = {"available": False, "reason": "loaded only when LAST-GIT-COMMIT is selected or exported"}
        payload["scanned_at"] = datetime.now().isoformat(timespec="seconds")
        self._create_tab_git_status_payload = payload
        self._create_tab_git_status_scan_signature = signature
        self._create_tab_git_status_last_reason = reason
        if not getattr(self, "_create_git_reference_payload", {}):
            self._update_create_git_reference_status(payload)
        return payload

    def _create_git_reference_signature(self) -> str:
        root = self._patch_reference_working_tree_root()
        return "|".join([
            str(root or ""),
            str(self.create_mode.get() if hasattr(self, "create_mode") else ""),
            str(self.create_stack.get() if hasattr(self, "create_stack") else ""),
            str(self.create_catalog_entry.get() if hasattr(self, "create_catalog_entry") else ""),
            str(self.create_target_path.get() if hasattr(self, "create_target_path") else ""),
        ])

    def _ensure_create_last_git_commit_reference(self, reason: str = "auto", *, force: bool = False) -> dict:
        signature = self._create_git_reference_signature()
        if not force and self._create_git_reference_scan_signature == signature and isinstance(self._create_git_reference_payload, dict) and self._create_git_reference_payload:
            return self._create_git_reference_payload
        status_payload = self._ensure_create_tab_git_status_scan(reason=reason, force=force)
        payload = dict(status_payload)
        payload["enabled"] = True
        payload["scan_reason"] = reason
        payload["source"] = "patch_tab_git_reference"
        payload["read_only"] = True
        payload["scanned_at"] = datetime.now().isoformat(timespec="seconds")
        if status_payload.get("available"):
            payload["last_commit"] = self._read_last_git_commit_reference(status_payload.get("git_root"))
        else:
            payload["last_commit"] = {"available": False, "reason": status_payload.get("reason", "git unavailable")}
        self._create_git_reference_payload = payload
        self._create_git_reference_scan_signature = signature
        self._create_git_reference_last_reason = reason
        self._update_create_git_reference_status(payload)
        return payload

    def _update_create_git_reference_status(self, payload: dict | None = None) -> None:
        payload = payload if isinstance(payload, dict) else getattr(self, "_create_git_reference_payload", {})
        try:
            if payload.get("available"):
                commit = payload.get("last_commit") if isinstance(payload.get("last_commit"), dict) else {}
                commit_text = commit.get("short_hash") if commit.get("available") else commit.get("reason", "no commit")
                dirty = "dirty" if payload.get("dirty") else "clean"
                self.create_git_reference_status.set(f"Last Git Commit: {payload.get('branch') or 'main'} · {dirty} · {commit_text}")
            elif payload:
                self.create_git_reference_status.set(f"Last Git Commit: {payload.get('reason', 'not available')}")
            else:
                self.create_git_reference_status.set("Last Git Commit: not scanned")
        except Exception:
            pass

    def _format_last_git_commit_reference_lines(self, payload: dict | None = None, *, detail: str = "summary") -> list[str]:
        payload = payload if isinstance(payload, dict) else getattr(self, "_create_git_reference_payload", {})
        if not payload:
            return []
        full_detail = str(detail or "summary").lower() == "full" or self._create_high_export_intelligence_enabled()
        lines = [
            "## Referenz D — Last Git Commit",
            "This reference was read-only through the Patch-tab Git routine from the Start working tree. It is context, not write authority.",
            "With high export intelligence, the full commit reference is additionally included as LAST_GIT_COMMIT.json.",
            f"- Repo erkannt: {'yes' if payload.get('available') else 'no'}",
        ]
        if payload.get("available"):
            lines.extend([
                f"- Git Root: {payload.get('git_root')}",
                f"- Branch: {payload.get('branch') or 'main'}",
                f"- Arbeitsbaumstatus: {'dirty' if payload.get('dirty') else 'clean'}",
                f"- Changed status entries in the working tree: {payload.get('changed_entry_count', 0)}",
            ])
            commit = payload.get("last_commit") if isinstance(payload.get("last_commit"), dict) else {}
            if commit.get("available"):
                lines.append(f"- Letzter Commit: {commit.get('short_hash')} · {commit.get('author_date_iso')} · {commit.get('subject')}")
                changed_files = commit.get("changed_files") if isinstance(commit.get("changed_files"), list) else []
                lines.append(f"- LAST_GIT_COMMIT.json: {'is included' if self._create_should_include_last_git_commit_reference() else 'only when checkbox/Last-Git plan is enabled'}; changed commit files: {len(changed_files)}.")
                if full_detail and changed_files:
                    lines.append("### Changed files in last commit")
                    for item in changed_files:
                        if not isinstance(item, dict):
                            continue
                        title = self._humanize_prompt_value(item.get("title") or item.get("path") or "Datei")
                        path = self._humanize_prompt_value(item.get("path") or "")
                        description = self._humanize_prompt_value(item.get("description") or "")
                        lines.append(f"- {title}: {description} Pfad: {path}")
            else:
                lines.append(f"- Last commit: not available ({commit.get('reason', 'unknown')})")
        else:
            lines.append(f"- Grund: {payload.get('reason', 'unknown')}")
        lines.append("- Usage: only for Git/feature/refactor context, not as proof of current file contents or permission for Git write operations.")
        return lines

    def _last_git_commit_manifest_payload(self, config: dict | None = None, payload: dict | None = None, *, base: Path | str | None = None) -> dict:
        payload = payload if isinstance(payload, dict) else self._last_git_commit_reference_for_manifest(config, reason="last_git_commit_manifest")
        commit = payload.get("last_commit") if isinstance(payload.get("last_commit"), dict) else {}
        return {
            "artifact": "LAST_GIT_COMMIT.json",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "source": "patch_tab_git_reference",
            "read_only": True,
            "enabled": bool(self._create_should_include_last_git_commit_reference(config)),
            "export_intelligence": self._create_export_intelligence_value(),
            "detail_level": "full" if self._create_high_export_intelligence_enabled() else "summary",
            "path_policy": self._create_export_path_policy_payload(base or payload.get("git_root") or self._create_working_dir()),
            "selected_chain_entry": (config or {}).get("selected_create_chain_entry") if isinstance(config, dict) else None,
            "repository": {
                "available": bool(payload.get("available")),
                "git_root": payload.get("git_root"),
                "branch": payload.get("branch"),
                "dirty": bool(payload.get("dirty")),
                "changed_entry_count": payload.get("changed_entry_count", 0),
                "status_porcelain_v1": payload.get("status_porcelain_v1") or payload.get("raw_status") or "",
            },
            "last_commit": commit if isinstance(commit, dict) else {"available": False, "reason": "missing commit payload"},
            "changed_files": commit.get("changed_files", []) if isinstance(commit, dict) else [],
            "prompt_builder_intro_contract": {
                "include_changed_file_title": True,
                "include_changed_file_description": True,
                "manifest_file": "LAST_GIT_COMMIT.json",
            },
            "guardrails": [
                "Read-only reference; does not grant Git write access.",
                "Commit metadata is contextual evidence, not proof that current files still match the commit.",
                "Relative path originals are preserved as relative_* when absolute_project_paths is enabled.",
            ],
        }

    def _last_git_commit_reference_for_manifest(self, config: dict | None = None, *, reason: str = "manifest") -> dict:
        enabled = self._create_should_include_last_git_commit_reference(config)
        if enabled:
            return self._ensure_create_last_git_commit_reference(reason=reason)
        payload = getattr(self, "_create_git_reference_payload", {}) or getattr(self, "_create_tab_git_status_payload", {})
        if isinstance(payload, dict) and payload:
            return {"enabled": False, "available": bool(payload.get("available")), "cached_reference": payload, "reason": "LAST-GIT-COMMIT export disabled and no selected Last-Git-Commit plan"}
        return {"enabled": False, "available": False, "reason": "LAST-GIT-COMMIT export disabled and no selected Last-Git-Commit plan"}

    def _patch_git_reference_root_for_patch(self, live: Path | None = None) -> Path | None:
        if self._patch_target_mode() == "working_project_tree":
            return live or self._patch_direct_project_live_root()
        return self._patch_reference_working_tree_root()

    def _copy_patch_apply_tree(self, source: Path, dest: Path) -> int:
        """Copy enough text files for git/patch engines, including manifests.

        Staging still filters generated manifests afterwards. This broader apply
        tree lets absolute-path `diff -ruN old new` patches apply cleanly even
        when they also contain generated manifest hunks that are not committed.
        """
        copied = 0
        try:
            src = Path(source).resolve()
            dst = Path(dest).resolve()
        except Exception:
            return copied
        if not src.exists() or not src.is_dir():
            return copied
        text_suffixes = {
            ".py", ".pyi", ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs", ".vue", ".svelte",
            ".html", ".css", ".scss", ".sass", ".less", ".json", ".yaml", ".yml", ".toml",
            ".md", ".txt", ".ini", ".cfg", ".yesva", ".kt", ".swift", ".cs", ".cpp", ".cc",
            ".cxx", ".h", ".hpp", ".rs", ".go", ".php", ".rb", ".sql", ".sh", ".bat", ".ps1", ".xml",
        }
        dst.mkdir(parents=True, exist_ok=True)
        for current, dirs, files in os.walk(src):
            dirs[:] = sorted(d for d in dirs if d not in self._patch_denied_path_parts())
            current_path = Path(current)
            try:
                rel_dir = current_path.relative_to(src).as_posix()
            except Exception:
                rel_dir = "."
            for filename in sorted(files):
                rel = filename if rel_dir == "." else f"{rel_dir}/{filename}"
                suffix = Path(filename).suffix.lower()
                if not (self._patch_allowed_project_file(rel) or filename in self._patch_denied_file_names() or suffix in text_suffixes or filename in {"Dockerfile", "Makefile"}):
                    continue
                file_path = current_path / filename
                try:
                    if file_path.stat().st_size > 5 * 1024 * 1024:
                        continue
                    target = dst / rel
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(file_path, target)
                    copied += 1
                except Exception:
                    continue
        return copied

    def _patch_normalize_diff_path(self, raw_path: str, *, diff_roots: list[str] | None = None, live_root: Path | None = None) -> str:
        text = str(raw_path or "").strip().split("\t", 1)[0].strip().strip('"')
        if not text or text == "/dev/null":
            return ""
        text = re.sub(r"^[ab]/", "", text.replace("\\", "/"))
        diff_roots = diff_roots or []
        for root in sorted({r.replace("\\", "/").rstrip("/") for r in diff_roots if r}, key=len, reverse=True):
            if text == root:
                return ""
            if text.startswith(root + "/"):
                rel = text[len(root) + 1:].strip("/")
                if not self._patch_allowed_project_file(rel):
                    continue
                if live_root is not None:
                    try:
                        if (live_root / rel).exists() or rel.startswith("schema/") or rel in {"prompt.py", "ai_json_generator.py", "ai_json_generator_core.py"}:
                            return rel
                    except Exception:
                        pass
                    continue
                return rel
        if text.startswith("/"):
            parts = [part for part in text.strip("/").split("/") if part]
            for index in range(len(parts)):
                rel = "/".join(parts[index:])
                if not self._patch_allowed_project_file(rel):
                    continue
                if live_root is not None:
                    try:
                        if (live_root / rel).exists() or rel.startswith("schema/") or rel in {"prompt.py", "ai_json_generator.py", "ai_json_generator_core.py"}:
                            return rel
                    except Exception:
                        pass
                if rel.startswith("schema/") or rel in {"prompt.py", "ai_json_generator.py", "ai_json_generator_core.py"}:
                    return rel
            return ""
        return text.strip("/")

    def _patch_diff_roots(self, text: str) -> list[str]:
        roots: list[str] = []
        for line in str(text or "").splitlines():
            if line.startswith("diff -ru"):
                parts = line.split()
                if len(parts) >= 4:
                    for value in parts[-2:]:
                        roots.append(str(Path(value).parent if Path(value).suffix else Path(value)).replace("\\", "/").rstrip("/"))
            elif line.startswith("--- ") or line.startswith("+++ "):
                value = line[4:].strip().split("\t", 1)[0].strip()
                if value and value != "/dev/null":
                    parent = str(Path(value.replace("\\", "/")).parent).replace("\\", "/").rstrip("/")
                    if parent:
                        # For /old/root/file and /old/root/schema/file collect both parent and one level up.
                        roots.append(parent)
                        if "/" in parent.strip("/"):
                            roots.append(str(Path(parent).parent).replace("\\", "/").rstrip("/"))
        return [root for root in roots if root and root != "."]

    def _patch_apply_levels_for_diff(self, text: str) -> list[int]:
        max_level = 10
        levels: list[int] = []
        for raw in str(text or "").splitlines():
            if not (raw.startswith("--- ") or raw.startswith("+++ ")):
                continue
            value = raw[4:].strip().split("\t", 1)[0].strip().replace("\\", "/")
            if not value or value == "/dev/null":
                continue
            parts = [part for part in value.strip("/").split("/") if part]
            # Prefer levels that leave common project paths such as prompt.py or schema/x.
            for index in range(len(parts)):
                rel = "/".join(parts[index:])
                if self._patch_allowed_project_file(rel) and (rel.startswith("schema/") or rel in {"prompt.py", "ai_json_generator.py", "ai_json_generator_core.py"}):
                    # git apply/patch -pN count the leading slash as a strip component for absolute paths.
                    levels.append(index + 1 if value.startswith("/") else index)
        levels.extend(range(0, max_level + 1))
        deduped: list[int] = []
        for level in levels:
            if level not in deduped and 0 <= level <= max_level:
                deduped.append(level)
        return deduped

    def _run_patch_engine_trials(self, patch_file: Path, source_root: Path, apply_root: Path, *, prefer_git: bool, strip_levels: list[int]) -> tuple[bool, str]:
        engines: list[tuple[str, list[str]]] = []
        if prefer_git:
            engines.append(("git apply", ["git", "apply", "--whitespace=nowarn"]))
        engines.append(("patch", ["patch", "--batch", "--forward", "-i", str(patch_file)]))
        diagnostics: list[str] = []
        for engine, base_cmd in engines:
            if engine == "git apply" and shutil.which("git") is None:
                diagnostics.append("git apply: git command not found")
                continue
            if engine == "patch" and shutil.which("patch") is None:
                diagnostics.append("patch: patch command not found")
                continue
            for level in strip_levels:
                shutil.rmtree(apply_root, ignore_errors=True)
                apply_root.mkdir(parents=True, exist_ok=True)
                self._copy_patch_apply_tree(source_root, apply_root)
                if engine == "git apply":
                    cmd = base_cmd + [f"-p{level}", str(patch_file)]
                else:
                    cmd = base_cmd[:1] + [f"-p{level}"] + base_cmd[1:]
                try:
                    completed = subprocess.run(cmd, cwd=str(apply_root), capture_output=True, text=True, timeout=12.0)
                    if completed.returncode == 0:
                        return True, f"{engine} -p{level}"
                    detail = (completed.stderr or completed.stdout or "").strip().splitlines()[:2]
                    diagnostics.append(f"{engine} -p{level}: {' | '.join(detail) if detail else 'returncode ' + str(completed.returncode)}")
                except Exception as exc:
                    diagnostics.append(f"{engine} -p{level}: {exc}")
        return False, "\n".join(diagnostics[-12:])

    def _patch_ensure_version_roots(self, *, materialize: bool = False) -> tuple[Path, Path, Path]:
        live = self._patch_active_live_root(materialize=materialize)
        if live is None:
            if self._patch_target_mode() == "working_project_tree":
                raise RuntimeError("Patch target Working/Project Tree is missing. Select a valid project folder in the Start tab or Create tab.")
            raise RuntimeError("Patch target Create Temp is missing. Create a project/build in the Create tab first or switch the patch target to Working/Project Tree.")
        self._refresh_patch_branch_ui()
        session = self._patch_branch_root()
        stage = session / "stage"
        baseline = session / "baseline"
        previous_live = getattr(self, "_patch_live_root", None)
        live_changed = False
        try:
            live_changed = previous_live is None or Path(previous_live).resolve() != live.resolve()
        except Exception:
            live_changed = True
        if live_changed and stage.exists():
            # Never carry staged files across Create builds.
            shutil.rmtree(stage, ignore_errors=True)
        if live_changed and baseline.exists():
            shutil.rmtree(baseline, ignore_errors=True)
        if not baseline.exists():
            baseline.mkdir(parents=True, exist_ok=True)
            self._copy_project_code_tree(live, baseline)
        stage.mkdir(parents=True, exist_ok=True)
        self._patch_session_root = session
        self._patch_live_root = live
        self._patch_stage_root = stage
        self._patch_baseline_root = baseline
        return live, stage, baseline

    def _patch_denied_path_parts(self) -> set[str]:
        return {
            ".git", ".hg", ".svn", "node_modules", "venv", ".venv", "env", "__pycache__",
            "build", "dist", ".next", ".nuxt", ".gradle", "target", "Pods", "DerivedData",
            "output", "export", ".zip_export_staging", "prompts",
        }

    def _patch_denied_file_names(self) -> set[str]:
        return {
            "EXPORT_MANIFEST.json", "AI_MANAGER.json", "AI-RULES.json", "AI_GENERATION_LOG.json",
            "PROCESS_LOG.md", "SUMMARY.md", "LIBRARY.log", "PROMPT_MANIFEST.json",
            "PROMPT_QUALITY_REPORT.md", "PROMPT_EVAL_CHECKLIST.md", "PROJECT_METADATA.json",
            "USER_PROMPT.txt", "ROLE_OPERATOR_BOILERPLATE_MANIFEST.json", "EXPORT_CONDITIONS.json",
            "EXPORT_MANIFEST.json", "PROMPT_MANIFEST.json", "CREATE_SOURCE_CLONE_MANIFEST.json",
            "CREATE_PREVIEW_TREE.json", "PATCH_REVIEW.json", "PATCH_DELETE_MANIFEST.json", ".patch_delete_manifest.json",
        }

    def _patch_allowed_project_file(self, rel: str) -> bool:
        rel = str(rel or "").replace("\\", "/").strip("/")
        if not rel or rel.startswith("../") or rel == ".." or "/../" in rel:
            return False
        parts = [part for part in rel.split("/") if part]
        if any(part in self._patch_denied_path_parts() for part in parts):
            return False
        name = parts[-1] if parts else rel
        if name in self._patch_denied_file_names():
            return False
        if name.startswith(".") and name not in {".env.example", ".gitignore", ".dockerignore", ".editorconfig", ".prettierrc", ".eslintrc"}:
            return False
        allowed_suffixes = {
            ".py", ".pyi", ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs", ".vue", ".svelte",
            ".html", ".css", ".scss", ".sass", ".less", ".json", ".yaml", ".yml", ".toml",
            ".md", ".txt", ".dockerfile", ".env", ".ini", ".cfg", ".yesva", ".kt", ".swift",
            ".cs", ".cpp", ".cc", ".cxx", ".h", ".hpp", ".rs", ".go", ".php", ".rb",
            ".sql", ".sh", ".bat", ".ps1", ".xml",
        }
        if name in {"Dockerfile", "Makefile", "package.json", "requirements.txt", "pyproject.toml", "setup.py", "vite.config.ts", "tsconfig.json"}:
            return True
        suffix = Path(name).suffix.lower()
        return suffix in allowed_suffixes

    def _copy_project_code_tree(self, source: Path, dest: Path) -> int:
        copied = 0
        try:
            src = Path(source).resolve()
            dst = Path(dest).resolve()
        except Exception:
            return copied
        if not src.exists() or not src.is_dir():
            return copied
        dst.mkdir(parents=True, exist_ok=True)
        for current, dirs, files in os.walk(src):
            dirs[:] = sorted(dirs)
            files = sorted(files)
            current_path = Path(current)
            try:
                rel_dir = current_path.relative_to(src).as_posix()
            except Exception:
                rel_dir = "."
            dirs[:] = [d for d in dirs if d not in self._patch_denied_path_parts()]
            for filename in files:
                rel = filename if rel_dir == "." else f"{rel_dir}/{filename}"
                if not self._patch_allowed_project_file(rel):
                    continue
                target = dst / rel
                try:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(current_path / filename, target)
                    copied += 1
                except Exception:
                    continue
        return copied

    def _patch_delete_manifest_path(self) -> Path | None:
        try:
            _live, stage, _baseline = self._patch_ensure_version_roots(materialize=False)
            return stage / ".patch_delete_manifest.json"
        except Exception:
            return None

    def _patch_deleted_paths(self) -> set[str]:
        manifest = self._patch_delete_manifest_path()
        if manifest is None or not manifest.exists():
            return set()
        try:
            payload = json.loads(manifest.read_text(encoding="utf-8", errors="ignore"))
            return {str(item).replace("\\", "/").strip("/") for item in payload.get("delete", []) if self._patch_allowed_project_file(str(item))}
        except Exception:
            return set()

    def _patch_file_hash(self, path: Path) -> str:
        try:
            h = hashlib.sha1()
            with path.open("rb") as fh:
                for chunk in iter(lambda: fh.read(1024 * 64), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return ""

    def _patch_relative_files(self, root: Path) -> dict[str, Path]:
        result: dict[str, Path] = {}
        try:
            base = Path(root).resolve()
        except Exception:
            return result
        if not base.exists():
            return result
        for current, dirs, files in os.walk(base):
            dirs[:] = sorted(d for d in dirs if d not in self._patch_denied_path_parts())
            for filename in sorted(files):
                path = Path(current) / filename
                try:
                    rel = path.relative_to(base).as_posix()
                except Exception:
                    continue
                if self._patch_allowed_project_file(rel):
                    result[rel] = path
        return result

    def _patch_compute_status(self) -> dict[str, str]:
        live, stage, baseline = self._patch_ensure_version_roots(materialize=False)
        base_files = self._patch_relative_files(baseline)
        live_files = self._patch_relative_files(live)
        stage_files = self._patch_relative_files(stage)
        status: dict[str, str] = {}
        for rel, path in live_files.items():
            if rel not in base_files:
                status[rel] = "A"
            elif self._patch_file_hash(path) != self._patch_file_hash(base_files[rel]):
                status[rel] = "M"
        for rel in base_files:
            if rel not in live_files:
                status[rel] = "D"
        for rel, path in stage_files.items():
            if rel not in live_files:
                status[rel] = "A*"
            elif self._patch_file_hash(path) != self._patch_file_hash(live_files[rel]):
                status[rel] = "M*"
        for rel in self._patch_deleted_paths():
            if rel in live_files:
                status[rel] = "D*"
        self._patch_virtual_status = status
        return status

    def _register_patch_drop_target(self, widget) -> None:
        """Best-effort native TkDND registration for Patch inputs.

        Tkinter itself has no file drop API. If tkdnd/tkinterdnd2 is installed,
        this wires the widget to Patch import. If not, normal Browse/Load still works.
        """
        if widget is None:
            return
        try:
            self.tk.call("package", "require", "tkdnd")
        except Exception:
            pass
        registered = False
        try:
            self.tk.call("tkdnd::drop_target", "register", str(widget), "DND_Files")
            registered = True
        except Exception:
            try:
                widget.drop_target_register("DND_Files")
                registered = True
            except Exception:
                registered = False
        if registered:
            try:
                widget.bind("<<Drop>>", self._on_patch_drop, add="+")
            except Exception:
                pass

    def _parse_drop_file_list(self, data: str) -> list[str]:
        try:
            values = list(self.tk.splitlist(data))
        except Exception:
            values = re.findall(r"\{([^}]+)\}|\S+", data or "")
        cleaned: list[str] = []
        for value in values:
            if isinstance(value, tuple):
                value = next((part for part in value if part), "")
            text = str(value).strip().strip("{}\"'")
            if text:
                cleaned.append(text)
        return cleaned

    def _on_patch_drop(self, event) -> str:
        paths = self._parse_drop_file_list(getattr(event, "data", ""))
        if not paths:
            return "break"
        self.patch_input_path.set(paths[0])
        self._load_patch_paths([Path(path).expanduser() for path in paths], reset_stage=True)
        return "break"

    def _browse_patch_input(self) -> None:
        path = filedialog.askopenfilename(title="Patch / ZIP / TAR / single replacement file")
        if not path:
            folder = filedialog.askdirectory(title="Or choose unpacked patch folder")
            path = folder or ""
        if path:
            self.patch_input_path.set(path)

    def _refresh_patch_status(self) -> None:
        try:
            live, stage, baseline = self._patch_ensure_version_roots(materialize=False)
        except Exception as exc:
            ref_root = self._patch_git_reference_root_for_patch(None)
            git_payload = self._patch_git_status_payload_for_root(ref_root) if self.patch_use_git_status.get() else {"available": False, "reason": "disabled"}
            self._patch_git_status_payload = git_payload
            if git_payload.get("available"):
                self.patch_git_status.set(f"Git ref: {git_payload.get('branch') or 'main'} · repo {git_payload.get('git_root')}")
            else:
                self.patch_git_status.set(f"Git ref fallback: {git_payload.get('reason', 'no git')}")
            message = str(exc)
            self.patch_status.set("Patch: target missing")
            try:
                self.patch_target_tree_status.set(f"Patch target: {self._patch_target_label()} · missing")
            except Exception:
                pass
            if hasattr(self, "patch_status_text"):
                self.patch_status_text.delete("1.0", "end")
                self.patch_status_text.insert(
                    "1.0",
                    "Patch-Ziel fehlt.\n"
                    + message
                    + "\n\nGit reference:\n"
                    + str(git_payload.get("raw_status") or git_payload.get("reason") or "not available"),
                )
                self._apply_text_widget_theme()
            return
        ref_root = self._patch_git_reference_root_for_patch(live)
        git_payload = self._patch_git_status_payload_for_root(ref_root) if self.patch_use_git_status.get() else {"available": False, "reason": "disabled"}
        self._patch_git_status_payload = git_payload
        branch = self._patch_branch_slug()
        git_branch = git_payload.get("branch") or "main"
        if git_payload.get("available"):
            self.patch_git_status.set(f"Git ref: {git_branch} · repo {git_payload.get('git_root')}")
        else:
            self.patch_git_status.set(f"Git ref fallback: {git_payload.get('reason', 'no git')}")
        status = self._patch_compute_status()
        try:
            self.patch_target_tree_status.set(f"Patch target: {self._patch_target_label()} · {live}")
        except Exception:
            pass
        try:
            live_box = getattr(self, "patch_live_box", None)
            if live_box is not None:
                live_box.configure(text=f"{self._patch_target_label()} Live Tree / {branch}")
        except Exception:
            pass
        use_git = self._patch_use_git_to_patch_enabled()
        lines = [
            f"target: {self._patch_target_label()}",
            f"branch: {branch}",
            f"live target: {live}",
            f"stage temp: {stage}",
            f"baseline: {baseline}",
            f"USE-GIT-TO-PATCH: {'on' if use_git else 'off'}",
            "",
            "Git status reference:",
            str(git_payload.get("raw_status") or git_payload.get("reason") or "clean / not available"),
            "",
            "fallback status for selected target:",
        ]
        if status:
            lines.extend(f"{code:>2} {rel}" for rel, code in sorted(status.items()))
        else:
            lines.append("clean")
        if hasattr(self, "patch_status_text"):
            self.patch_status_text.delete("1.0", "end")
            self.patch_status_text.insert("1.0", "\n".join(lines))
            self._apply_text_widget_theme()
        self.patch_status.set(f"Patch: {len(status)} staged/live change(s)")
        self._render_patch_trees()

    def _load_patch_input(self) -> None:
        raw = self.patch_input_path.get().strip().strip('"')
        if not raw:
            messagebox.showwarning("Patch", self._ui_text("Select a patch, ZIP, TAR, folder or file.", "Select a patch, ZIP, TAR, folder or file."))
            return
        self._load_patch_paths([Path(raw).expanduser()], reset_stage=True)

    def _load_patch_paths(self, paths: list[Path], *, reset_stage: bool) -> None:
        valid_paths = [Path(path).expanduser() for path in paths if Path(path).expanduser().exists()]
        if not valid_paths:
            messagebox.showerror("Patch", self._ui_text("No valid patch/ZIP/TAR/folder/file source found.", "No valid patch/ZIP/TAR/folder/file source found."))
            return
        try:
            _live, stage, _baseline = self._patch_ensure_version_roots(materialize=True)
        except Exception as exc:
            messagebox.showwarning("Patch", str(exc))
            self._refresh_patch_status()
            return
        if reset_stage and stage.exists():
            shutil.rmtree(stage, ignore_errors=True)
        stage.mkdir(parents=True, exist_ok=True)
        imported = 0
        skipped = 0
        try:
            for path in valid_paths:
                if path.is_dir():
                    add, skip = self._import_patch_directory(path, stage)
                elif path.suffix.lower() == ".zip":
                    add, skip = self._import_patch_zip(path, stage)
                elif path.suffix.lower() in {".tar", ".gz", ".tgz", ".bz2", ".xz"} or path.name.lower().endswith((".tar.gz", ".tar.bz2", ".tar.xz")):
                    add, skip = self._import_patch_tar(path, stage)
                elif path.suffix.lower() in {".patch", ".diff"}:
                    add, skip = self._import_patch_diff_manifest(path, stage)
                else:
                    rel = path.name
                    if self._patch_allowed_project_file(rel):
                        dst = stage / rel
                        dst.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(path, dst)
                        add, skip = 1, 0
                    else:
                        add, skip = 0, 1
                imported += add
                skipped += skip
        except Exception as exc:
            messagebox.showerror("Patch import failed", str(exc))
            return
        label = ", ".join(path.name for path in valid_paths[:3]) + (" …" if len(valid_paths) > 3 else "")
        self.patch_status.set(f"Patch loaded into {self._patch_branch_slug()}: {imported} project file(s), {skipped} skipped item(s) · {label}")
        self._refresh_patch_status()

    def _safe_patch_member_rel(self, raw_name: str) -> str:
        rel = str(raw_name or "").replace("\\", "/").lstrip("/")
        parts = [p for p in rel.split("/") if p and p != "."]
        # Drop common archive wrapper folder when it clearly contains exported manifests.
        if len(parts) > 1 and parts[0].lower().startswith(("prompt-guide", "export", "output")):
            parts = parts[1:]
        return "/".join(parts)

    def _import_patch_directory(self, source: Path, stage: Path) -> tuple[int, int]:
        imported = skipped = 0
        base = source.resolve()
        for current, dirs, files in os.walk(base):
            dirs[:] = sorted(d for d in dirs if d not in self._patch_denied_path_parts())
            for filename in sorted(files):
                src = Path(current) / filename
                try:
                    rel = src.relative_to(base).as_posix()
                except Exception:
                    skipped += 1
                    continue
                rel = self._safe_patch_member_rel(rel)
                if not self._patch_allowed_project_file(rel):
                    skipped += 1
                    continue
                dst = stage / rel
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, dst)
                imported += 1
        return imported, skipped

    def _import_patch_zip(self, archive_path: Path, stage: Path) -> tuple[int, int]:
        imported = skipped = 0
        with zipfile.ZipFile(archive_path) as archive:
            for member in archive.infolist():
                if member.is_dir():
                    continue
                rel = self._safe_patch_member_rel(member.filename)
                if not self._patch_allowed_project_file(rel):
                    skipped += 1
                    continue
                dst = stage / rel
                dst.parent.mkdir(parents=True, exist_ok=True)
                with archive.open(member) as src, dst.open("wb") as out:
                    shutil.copyfileobj(src, out)
                imported += 1
        return imported, skipped

    def _import_patch_tar(self, archive_path: Path, stage: Path) -> tuple[int, int]:
        imported = skipped = 0
        with tarfile.open(archive_path) as archive:
            for member in archive.getmembers():
                if not member.isfile():
                    continue
                rel = self._safe_patch_member_rel(member.name)
                if not self._patch_allowed_project_file(rel):
                    skipped += 1
                    continue
                extracted = archive.extractfile(member)
                if extracted is None:
                    skipped += 1
                    continue
                dst = stage / rel
                dst.parent.mkdir(parents=True, exist_ok=True)
                with dst.open("wb") as out:
                    shutil.copyfileobj(extracted, out)
                imported += 1
        return imported, skipped

    def _import_patch_diff_manifest(self, patch_file: Path, stage: Path) -> tuple[int, int]:
        text = patch_file.read_text(encoding="utf-8", errors="ignore")
        live, _stage, _baseline = self._patch_ensure_version_roots()
        diff_roots = self._patch_diff_roots(text)
        resolved_paths: list[str] = []
        for line in text.splitlines():
            if line.startswith("+++ ") or line.startswith("--- "):
                candidate = self._patch_normalize_diff_path(line[4:], diff_roots=diff_roots, live_root=live)
                if candidate and self._patch_allowed_project_file(candidate):
                    resolved_paths.append(candidate)
            elif line.startswith("diff --git "):
                pieces = line.split()
                if len(pieces) >= 4:
                    candidate = self._patch_normalize_diff_path(pieces[3], diff_roots=diff_roots, live_root=live)
                    if candidate and self._patch_allowed_project_file(candidate):
                        resolved_paths.append(candidate)
            elif line.startswith("diff -ru"):
                pieces = line.split()
                if len(pieces) >= 4:
                    candidate = self._patch_normalize_diff_path(pieces[-1], diff_roots=diff_roots, live_root=live)
                    if candidate and self._patch_allowed_project_file(candidate):
                        resolved_paths.append(candidate)

        apply_root = self._patch_work_root() / "diff_apply"
        shutil.rmtree(apply_root, ignore_errors=True)
        apply_root.mkdir(parents=True, exist_ok=True)
        git_ref_root = self._patch_git_reference_root_for_patch(live)
        git_payload = self._patch_git_status_payload_for_root(git_ref_root) if self.patch_use_git_status.get() else {"available": False, "reason": "disabled"}
        self._patch_git_status_payload = git_payload
        prefer_git = bool(self._patch_use_git_to_patch_enabled() and git_payload.get("available"))
        strip_levels = self._patch_apply_levels_for_diff(text)
        applied, engine_note = self._run_patch_engine_trials(patch_file, live, apply_root, prefer_git=prefer_git, strip_levels=strip_levels)

        if applied:
            before = self._patch_relative_files(live)
            after = self._patch_relative_files(apply_root)
            imported = 0
            changed_paths: list[str] = []
            delete_paths: list[str] = []
            for rel, src in after.items():
                if rel not in before or self._patch_file_hash(src) != self._patch_file_hash(before[rel]):
                    dst = stage / rel
                    dst.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(src, dst)
                    imported += 1
                    changed_paths.append(rel)
            for rel in before:
                if rel not in after and self._patch_allowed_project_file(rel):
                    delete_paths.append(rel)
            if delete_paths:
                delete_manifest = stage / ".patch_delete_manifest.json"
                delete_manifest.write_text(json.dumps({"delete": sorted(set(delete_paths))}, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            import_manifest = {
                "kind": "unified_diff_import",
                "source": str(patch_file),
                "target_mode": self._patch_target_mode(),
                "target_root": str(live),
                "engine": engine_note,
                "use_git_to_patch": self._patch_use_git_to_patch_enabled(),
                "git_reference_available": bool(git_payload.get("available")),
                "resolved_paths": sorted(set(resolved_paths)),
                "imported_files": sorted(changed_paths),
                "staged_files": sorted(self._patch_relative_files(stage).keys()),
                "deleted_files": sorted(set(delete_paths)),
            }
            try:
                (self._patch_branch_root() / "PATCH_IMPORT_MANIFEST.json").write_text(json.dumps(import_manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            except Exception:
                pass
            shutil.rmtree(apply_root, ignore_errors=True)
            return imported + len(delete_paths), 0

        # Fallback: safe review mode. Paths are normalized so the user can still
        # open the exact target files even when no engine can apply the diff.
        review_path = stage / ".patch_review.json"
        review_payload = {
            "kind": "unified_diff_review",
            "source": str(patch_file),
            "target_mode": self._patch_target_mode(),
            "use_git_to_patch": self._patch_use_git_to_patch_enabled(),
            "git_reference_available": bool(git_payload.get("available")),
            "resolved_paths": sorted(set(resolved_paths)),
            "note": "No patch engine could apply the diff cleanly. Resolved paths are normalized for manual review; import a replacement ZIP/folder or edit staged files manually before Commit.",
            "engine_diagnostics": engine_note,
            "diff_preview": text[:50000],
        }
        review_path.write_text(json.dumps(review_payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        return 0, 0

    def _render_patch_trees(self) -> None:
        try:
            live, stage, _baseline = self._patch_ensure_version_roots(materialize=False)
            status = self._patch_compute_status()
        except Exception:
            for tree in (getattr(self, "patch_live_tree", None), getattr(self, "patch_stage_tree", None)):
                try:
                    tree.delete(*tree.get_children(""))
                except Exception:
                    pass
            return
        self._render_patch_tree_widget(getattr(self, "patch_live_tree", None), live, status, live_tree=True)
        self._render_patch_tree_widget(getattr(self, "patch_stage_tree", None), stage, status, live_tree=False, live_root=live)

    def _render_patch_tree_widget(self, tree: ttk.Treeview | None, root: Path, status: dict[str, str], *, live_tree: bool, live_root: Path | None = None) -> None:
        if tree is None:
            return
        try:
            tree.delete(*tree.get_children(""))
        except Exception:
            pass
        nodes: dict[str, str] = {}
        def ensure(rel: str, kind: str = "dir", code: str = "") -> str:
            rel = rel.strip("/") or "."
            if rel in nodes:
                return nodes[rel]
            if rel == ".":
                parent = ""
                text = f"{self.patch_branch_name.get().strip() or 'main'}"
            else:
                parent_rel = "/".join(rel.split("/")[:-1]) or "."
                parent = ensure(parent_rel, "dir")
                text = rel.split("/")[-1]
            tags: tuple[str, ...] = ()
            if code:
                tags = ("user_input",)
            iid = tree.insert(parent, "end", text=text, values=(code or kind, rel), tags=tags)
            nodes[rel] = iid
            return iid
        if live_tree:
            files = self._patch_relative_files(root)
            deleted_paths: set[str] = set()
        else:
            # The Patch Tree is the pending branch stage only. The live project is
            # already visible in the first tree, so this tree must stay empty until
            # a real patch/replacement has been loaded or edited.
            files = self._patch_relative_files(root)
            deleted_paths = self._patch_deleted_paths()
            if not files and not deleted_paths:
                return
        ensure(".", "dir")
        dirs = {"."}
        for rel in files:
            pieces = rel.split("/")[:-1]
            for i in range(1, len(pieces) + 1):
                dirs.add("/".join(pieces[:i]))
        for rel in deleted_paths:
            pieces = rel.split("/")[:-1]
            for i in range(1, len(pieces) + 1):
                dirs.add("/".join(pieces[:i]))
        for d in sorted(dirs, key=lambda x: (x.count("/"), x)):
            ensure(d or ".", "dir")
        for rel in sorted(files):
            if rel in deleted_paths and not live_tree:
                code = "D*"
            elif live_tree:
                code = status.get(rel, "")
            else:
                code = status.get(rel, "")
            ensure(rel, "file", code)
        for rel in sorted(deleted_paths):
            ensure(rel, "file", "D*")
        try:
            tree.item(nodes["."], open=True)
        except Exception:
            pass

    def _patch_selected_stage_rel_paths(self) -> list[str]:
        tree = getattr(self, "patch_stage_tree", None)
        if tree is None:
            return []
        result = []
        for item in tree.selection():
            try:
                rel = str(tree.set(item, "path") or "")
                if rel and rel != ".":
                    result.append(rel)
            except Exception:
                continue
        return sorted(set(result))

    def _on_patch_stage_tree_select(self, _event=None) -> None:
        self._open_selected_patch_stage_file()

    def _on_patch_live_tree_select(self, _event=None) -> None:
        tree = getattr(self, "patch_live_tree", None)
        if tree is None or not tree.selection():
            return
        try:
            rel = str(tree.set(tree.selection()[0], "path") or "")
        except Exception:
            return
        try:
            live, _stage, _baseline = self._patch_ensure_version_roots()
        except Exception:
            return
        path = live / rel
        self.patch_selected_path.set(f"live:{rel}")
        self._load_patch_editor_path(path, editable=False)

    def _open_selected_patch_stage_file(self) -> None:
        rels = self._patch_selected_stage_rel_paths()
        if not rels:
            return
        rel = rels[0]
        try:
            live, stage, _baseline = self._patch_ensure_version_roots()
        except Exception:
            return
        staged_path = stage / rel
        live_path = live / rel
        self.patch_selected_path.set(rel)
        if staged_path.exists() and staged_path.is_file():
            self._load_patch_editor_path(staged_path, editable=True)
        elif live_path.exists() and live_path.is_file():
            # The staged tree is a full overlay. Opening an unchanged file loads
            # the Create temp version, and Save creates a staged replacement.
            self._load_patch_editor_path(live_path, editable=True)
        else:
            self._load_patch_editor_path(staged_path, editable=True)

    def _load_patch_editor_path(self, path: Path, *, editable: bool) -> None:
        if not hasattr(self, "patch_editor_text"):
            return
        self.patch_editor_text.configure(state="normal")
        self.patch_editor_text.delete("1.0", "end")
        if not path.exists() or not path.is_file():
            self.patch_editor_text.insert("1.0", "Select a file to preview/edit.")
        else:
            try:
                raw = path.read_bytes()
                truncated = len(raw) > 500_000
                if truncated:
                    raw = raw[:500_000]
                text = raw.decode("utf-8", errors="ignore")
                if truncated:
                    text += "\n\n--- preview truncated at 500KB ---\n"
                self.patch_editor_text.insert("1.0", text)
            except Exception as exc:
                self.patch_editor_text.insert("1.0", f"Could not read file: {exc}")
        if not editable:
            self.patch_editor_text.configure(state="disabled")
        self._apply_text_widget_theme()

    def _save_patch_editor_file(self) -> None:
        rel = self.patch_selected_path.get().strip()
        if not rel or rel.startswith("live:"):
            messagebox.showwarning("Patch", self._ui_text("Select a staged file first.", "Select a staged file first."))
            return
        if not self._patch_allowed_project_file(rel):
            messagebox.showerror("Patch", self._ui_text("This path is not an allowed project-code path.", "This path is not an allowed project-code path."))
            return
        try:
            _live, stage, _baseline = self._patch_ensure_version_roots()
        except Exception as exc:
            messagebox.showwarning("Patch", str(exc))
            return
        path = stage / rel
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            text = self.patch_editor_text.get("1.0", "end-1c")
            path.write_text(text, encoding="utf-8")
        except Exception as exc:
            messagebox.showerror("Patch save failed", str(exc))
            return
        self.patch_status.set(f"Saved staged file: {rel}")
        self._refresh_patch_status()

    def _remove_selected_patch_stage_items(self) -> None:
        rels = self._patch_selected_stage_rel_paths()
        if not rels:
            return
        try:
            _live, stage, _baseline = self._patch_ensure_version_roots()
        except Exception as exc:
            messagebox.showwarning("Patch", str(exc))
            return
        deleted = self._patch_deleted_paths()
        changed = 0
        for rel in rels:
            target = stage / rel
            try:
                if target.is_dir():
                    shutil.rmtree(target, ignore_errors=True)
                    changed += 1
                elif target.exists():
                    target.unlink()
                    changed += 1
            except Exception:
                pass
            if rel in deleted:
                deleted.discard(rel)
                changed += 1
        manifest = stage / ".patch_delete_manifest.json"
        try:
            if deleted:
                manifest.write_text(json.dumps({"delete": sorted(deleted)}, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            elif manifest.exists():
                manifest.unlink()
        except Exception:
            pass
        self.patch_selected_path.set("")
        if hasattr(self, "patch_editor_text"):
            self.patch_editor_text.delete("1.0", "end")
        self.patch_status.set(f"Removed {changed} staged change(s)")
        self._refresh_patch_status()

    def _reset_patch_stage(self) -> None:
        try:
            _live, stage, _baseline = self._patch_ensure_version_roots()
        except Exception as exc:
            messagebox.showwarning("Patch", str(exc))
            self._refresh_patch_status()
            return
        shutil.rmtree(stage, ignore_errors=True)
        stage.mkdir(parents=True, exist_ok=True)
        self.patch_selected_path.set("")
        if hasattr(self, "patch_editor_text"):
            self.patch_editor_text.delete("1.0", "end")
        self.patch_status.set("Patch stage reset")
        self._refresh_patch_status()

    def _commit_patch_stage(self) -> None:
        try:
            live, stage, baseline = self._patch_ensure_version_roots()
        except Exception as exc:
            messagebox.showwarning("Patch", str(exc))
            self._refresh_patch_status()
            return
        files = self._patch_relative_files(stage)
        deleted_paths = sorted(self._patch_deleted_paths())
        if not files and not deleted_paths:
            messagebox.showinfo("Patch", self._ui_text("No staged files to commit.", "No staged files to commit."))
            return
        committed = 0
        for rel in deleted_paths:
            target = live / rel
            try:
                if target.exists() and target.is_file():
                    target.unlink()
                    committed += 1
            except Exception:
                pass
        for rel, src in files.items():
            if not self._patch_allowed_project_file(rel):
                continue
            dst = live / rel
            try:
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, dst)
                committed += 1
            except Exception:
                continue
        # Commit in the fallback VC means: staged files become live and the new main baseline.
        shutil.rmtree(baseline, ignore_errors=True)
        baseline.mkdir(parents=True, exist_ok=True)
        self._copy_project_code_tree(live, baseline)
        shutil.rmtree(stage, ignore_errors=True)
        stage.mkdir(parents=True, exist_ok=True)
        meta = {
            "branch": self._patch_branch_slug(),
            "committed_at": datetime.now().isoformat(timespec="seconds"),
            "files": sorted(files),
            "deleted_files": deleted_paths,
            "git_status_reference_only": self._patch_git_status_payload,
            "target_mode": self._patch_target_mode(),
            "target_root": str(live),
            "use_git_to_patch": self._patch_use_git_to_patch_enabled(),
            "mode": f"{self._patch_target_mode()}-git-reference" if self._patch_git_status_payload.get("available") else f"{self._patch_target_mode()}-fallback-versioning",
        }
        try:
            (self._patch_branch_root() / "PATCH_COMMIT_MANIFEST.json").write_text(json.dumps(meta, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        except Exception:
            pass
        self.patch_status.set(f"Committed {committed} file(s) to temp branch {self._patch_branch_slug()}")
        self._refresh_patch_status()

    def _build_schema_tab(self) -> None:
        root = self.schema_tab
        top = ttk.Frame(root)
        top.pack(fill="x")
        ttk.Button(top, text="Reload schema", command=self._reload_schema).pack(side="left")
        ttk.Button(top, text="Open schema folder", command=self._open_schema_folder).pack(side="left", padx=(8, 0))
        ttk.Button(top, text="Refresh JSON outline", command=self._refresh_schema_outline).pack(side="left", padx=(8, 0))
        ttk.Label(top, text="Schema files are flat JSON arrays with id fields. The outline tree can be expanded/collapsed for large JSON structures.").pack(side="left", padx=(12, 0))

        body = ttk.PanedWindow(root, orient="horizontal")
        body.pack(fill="both", expand=True, pady=(10, 0))

        left = ttk.Frame(body)
        right = ttk.Frame(body)
        body.add(left, weight=1)
        body.add(right, weight=3)

        files_box = ttk.LabelFrame(left, text="Schema files", padding=6)
        files_box.pack(fill="both", expand=True)
        self.schema_files_tree = ttk.Treeview(files_box, columns=("file",), show="headings", height=10)
        self.schema_files_tree.heading("file", text="Schema file")
        self.schema_files_tree.pack(fill="both", expand=True)
        self.schema_files_tree.bind("<<TreeviewSelect>>", self._load_schema_file_to_editor)

        outline_box = ttk.LabelFrame(left, text="JSON outline", padding=6)
        outline_box.pack(fill="both", expand=True, pady=(8, 0))
        outline_buttons = ttk.Frame(outline_box)
        outline_buttons.pack(fill="x", pady=(0, 4))
        ttk.Button(outline_buttons, text="Expand JSON tree", command=lambda: self._expand_tree(self.schema_outline_tree)).pack(side="left")
        ttk.Button(outline_buttons, text="Collapse JSON tree", command=lambda: self._collapse_tree(self.schema_outline_tree)).pack(side="left", padx=(6, 0))
        self.schema_outline_tree = ttk.Treeview(outline_box, columns=("detail",), show="tree headings", height=12)
        self.schema_outline_tree.heading("#0", text="Node")
        self.schema_outline_tree.heading("detail", text="Type / value")
        self.schema_outline_tree.column("#0", width=190, stretch=True)
        self.schema_outline_tree.column("detail", width=180, stretch=True)
        self.schema_outline_tree.pack(fill="both", expand=True)

        self.schema_text = self._pack_text_with_scrollbars(right, wrap="none")

        schema_buttons = ttk.Frame(right)
        schema_buttons.pack(fill="x", pady=(8, 0))
        ttk.Button(schema_buttons, text="Save JSON file", command=self._save_schema_text).pack(side="left")
        ttk.Button(schema_buttons, text="Create new JSON file", command=self._new_schema_file).pack(side="left", padx=(8, 0))
        ttk.Button(schema_buttons, text="Refresh JSON outline", command=self._refresh_schema_outline).pack(side="left", padx=(8, 0))

