        ttk.Label(form, text="Keywords").grid(row=2, column=4, sticky="w", padx=(8, 0), pady=(6, 0))
        ttk.Entry(form, textvariable=self.plugin_keywords, width=34).grid(row=2, column=5, sticky="ew", padx=(8, 0), pady=(6, 0))

        actions = ttk.Frame(form)
