        self.prompt_builder_operator_flow_box.grid(row=1, column=1, sticky="ew", padx=(8, 0), pady=(8, 0))
        self.prompt_builder_operator_flow_box.bind("<<ComboboxSelected>>", self._on_operator_flow_changed)
