    def _default_info_settings(self) -> dict:
        return {
            "schema_version": "2026.prompt-guide.info-settings.v4",
            "ui_language": "ENGLISH",
            "show_startup_donation": True,
            "project_title": APP_NAME,
            "credit_owner": "Eric Heidrich",
            "credit_handle": "Nrwx",
            "github_url": "https://github.com/Nrwx",
            "paypal_url": "https://paypal.com/paypalme/actata",
            "donation_heading": "Support Prompt Guide Development",
            "donation_body": self._default_info_donation_body(),
            "disclaimer": self._default_info_disclaimer(),
            "app_settings": {},
        }

    def _locked_info_setting_keys(self) -> set[str]:
        return {
            "project_title",
            "credit_owner",
            "credit_handle",
            "github_url",
            "paypal_url",
            "donation_heading",
            "donation_body",
            "disclaimer",
        }

    def _load_app_settings(self) -> dict:
        defaults = self._default_info_settings()
        locked_defaults = {key: defaults[key] for key in self._locked_info_setting_keys() if key in defaults}
        path = self._app_settings_path()
        try:
            if path.exists():
                loaded = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    for key, value in loaded.items():
                        if key in defaults and key not in locked_defaults:
                            defaults[key] = value
        except Exception:
            pass
        if not isinstance(defaults.get("app_settings"), dict):
            defaults["app_settings"] = {}
        defaults.update(locked_defaults)
        return defaults

