    def _build_export_settings_group(self, parent: ttk.Frame, source: str) -> None:
        """Render the only user-facing export option group for a tree source."""
        is_create = source == "create"
        flow_row = ttk.Frame(parent)
        flow_row.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 6))
        ttk.Label(flow_row, text="Operator flow").pack(side="left")
        flow_box = ttk.Combobox(
            flow_row,
            textvariable=self.ai_operator_execution_mode,
            values=["confirm_then_execute", "start_immediately", "sequential_roles"],
            state="readonly",
            width=24,
        )
        flow_box.pack(side="left", padx=(8, 0))
        flow_box.bind("<<ComboboxSelected>>", self._on_operator_flow_changed)
        ttk.Label(flow_row, text="Point of Truth for exported operator execution.").pack(side="left", padx=(10, 0))
        intelligence_row = ttk.Frame(parent)
        intelligence_row.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(0, 6))
        ttk.Label(intelligence_row, text="Export-Intelligenz").pack(side="left")
        intelligence_box = ttk.Combobox(
            intelligence_row,
            textvariable=self.create_export_intelligence,
            values=["low", "medium", "high"],
            state="readonly",
            width=12,
        )
        intelligence_box.pack(side="left", padx=(8, 0))
        intelligence_box.bind("<<ComboboxSelected>>", self._on_export_intelligence_changed)
        ttk.Label(intelligence_row, text="Controls how much human-compiled context is placed into USER_PROMPT.txt.").pack(side="left", padx=(10, 0))
        fields = [
            ("Overwrite existing generated files", self.overwrite, self._on_export_setting_changed),
            ("Create ZIP" if is_create else "Worktree ZIP", self.create_export_as_zip if is_create else self.export_as_zip, self._on_export_setting_changed),
            ("Compact export", self.create_compact_export if is_create else self.compact_export, self._on_export_setting_changed),
            ("Include imports", self.create_include_imports if is_create else self.include_imports, self._on_include_imports_changed),
            ("Include dependency manifests in export", self.include_dependency_manifests, self._on_export_setting_changed),
            ("Copy schema folder into export", self.copy_schema, self._on_export_setting_changed),
            ("Write JSON generation log", self.create_log, self._on_export_setting_changed),
            ("Changed files only", self.create_changed_files_only if is_create else self.changed_files_only, self._on_export_setting_changed),
            ("Sequential role/reference search", self.ai_research_schemas_boilerplates, self._on_export_setting_changed),
            ("Brutally honest introductions", self.export_brutally_honest, self._on_export_setting_changed),
        ]
        if is_create:
            fields.extend([
                ("Do not normalize", self.create_do_not_normalize, self._on_export_setting_changed),
                ("Mirror schema hooks", self.create_schema_mirror, self._on_export_setting_changed),
                ("LAST-GIT-COMMIT in USER_PROMPT + Manifest", self.create_export_last_git_commit, self._on_last_git_commit_export_setting_changed),
                ("Absolute project paths in export", self.create_export_absolute_paths, self._on_export_setting_changed),
            ])
        start_row = 2
        for index, (label, variable, command) in enumerate(fields):
            ttk.Checkbutton(parent, text=label, variable=variable, command=command).grid(row=start_row + index // 2, column=index % 2, sticky="w", padx=(0 if index % 2 == 0 else 12, 0), pady=2)
        policy = (
            "Overwrite ON keeps a stable export folder and replaces generated files there. "
            "Overwrite OFF creates a fresh timestamped export folder per run."
        )
        if is_create:
            ttk.Label(parent, text="Create exports use the Create working/build tree. " + policy, wraplength=520).grid(row=start_row + (len(fields)+1)//2, column=0, columnspan=2, sticky="w", pady=(6, 0))
        else:
            ttk.Label(parent, text="Worktree exports use the normal working tree. " + policy, wraplength=520).grid(row=start_row + (len(fields)+1)//2, column=0, columnspan=2, sticky="w", pady=(6, 0))

    def _active_tree_include_imports(self) -> bool:
        return bool(self.create_include_imports.get() if self._use_create_working_dir_for_project_tree() else self.include_imports.get())

    def _schedule_prompt_builder_flow_refresh(self, *, take_focus: bool = False) -> None:
        if getattr(self, "_prompt_builder_flow_refresh_after", None):
            try:
                self.after_cancel(self._prompt_builder_flow_refresh_after)
            except Exception:
                pass
            self._prompt_builder_flow_refresh_after = None
        def callback() -> None:
            self._prompt_builder_flow_refresh_after = None
            if not hasattr(self, "prompt_text"):
                return
            try:
                if not self._active_generator_targets():
                    return
            except Exception:
                return
            # Operator flow is exported into metadata and changes the Remember block.
            # Rebuild the generated operator prompt so Prompt Builder always mirrors
            # the Export-tab point of truth after a flow switch.
            try:
                self._build_prompt_preview(select_prompt_tab=take_focus)
            except Exception as exc:
                self._set_progress(f"Prompt Builder: Operator-flow refresh skipped: {exc}", 0)
        try:
            self._prompt_builder_flow_refresh_after = self.after(120, callback)
        except Exception:
            callback()

    def _on_operator_flow_changed(self, _event=None) -> None:
        self._refresh_export_settings_visibility()
        self._update_project_tree_status()
        self._schedule_prompt_builder_flow_refresh()
        if self._use_create_working_dir_for_project_tree():
            self._schedule_create_preview_refresh()

    def _on_export_intelligence_changed(self, _event=None) -> None:
        """Keep Prompt Builder and Create Preview reactive to Export-Intelligence.

        Export-Intelligence is a point-of-truth like Operator Flow: changing it
        must update every human compiled preview, not only the final ZIP export.
        """
        self._refresh_export_settings_visibility()
        self._update_project_tree_status()
        self._schedule_prompt_builder_flow_refresh()
        try:
            self._schedule_create_preview_refresh()
        except Exception:
            pass

    def _on_last_git_commit_export_setting_changed(self) -> None:
        if self.create_export_last_git_commit.get():
            self._ensure_create_last_git_commit_reference(reason="export_checkbox", force=True)
        self._on_export_setting_changed()

    def _on_export_setting_changed(self) -> None:
        self._refresh_export_settings_visibility()
        self._update_project_tree_status()
        self._schedule_prompt_builder_flow_refresh()
        try:
            self._schedule_create_preview_refresh()
        except Exception:
            pass
        if self._use_create_working_dir_for_project_tree():
            self._schedule_create_preview_refresh()

    def _refresh_export_settings_visibility(self) -> None:
        use_create = self._use_create_working_dir_for_project_tree()
        path_frame = getattr(self, "custom_export_path_frame", None)
        if path_frame is not None:
            try:
                path_frame.grid()
            except Exception:
                pass
        for frame, show in [
            (getattr(self, "worktree_export_settings_frame", None), not use_create),
            (getattr(self, "create_export_settings_frame", None), use_create),
        ]:
            if frame is None:
                continue
            try:
                if show and not frame.winfo_ismapped():
                    frame.pack(fill="x")
                elif not show and frame.winfo_ismapped():
                    frame.pack_forget()
            except Exception:
                pass
        button = getattr(self, "active_tree_export_button", None)
        if button is not None:
            try:
                button.configure(text=self._ui_text("Run Create Export" if use_create else "Run Worktree Export", "Run Create Export" if use_create else "Run Worktree Export"))
            except Exception:
                pass
        status = getattr(self, "project_tree_export_settings_status", None)
        if status is not None:
            overwrite_label = "stable overwrite folder" if bool(self.overwrite.get()) else "fresh export ID folder"
            source_label = "Create Working Dir" if use_create else "Normal Worktree"
            honesty_label = "Brutally honest introductions ON" if self._brutally_honest_intro_enabled() else "Brutally honest introductions OFF"
            status.set(f"{source_label} selected. Both Worktree and Create exports use the shared Custom Export Path with {overwrite_label}. {honesty_label}: {self._resolve_export_path(self.export_dir.get(), 'custom-export')}")

    def _export_active_tree_source(self) -> None:
        """Run the single export action that matches the active tree source."""
        if self._use_create_working_dir_for_project_tree():
            self._export_current_create_build_or_context()
        else:
            self._generate()

    def _build_project_tree_tab(self) -> None:
        root = self.project_tree_tab
        actions = ttk.LabelFrame(root, text="Export", padding=10)
        actions.pack(fill="x")
        ttk.Label(actions, text=(
            "Export controls live here only. Select Normal Worktree or Create Working Dir first; "
            "only the settings for that tree source are shown."
        ), wraplength=1080).grid(row=0, column=0, columnspan=10, sticky="w", pady=(0, 8))

        ttk.Label(actions, text="Tree source").grid(row=1, column=0, sticky="w")
        self.project_tree_source_box = ttk.Combobox(actions, textvariable=self.project_tree_source_mode, values=self._project_tree_source_values(), state="readonly", width=22)
        source_box = self.project_tree_source_box
        source_box.grid(row=1, column=1, sticky="w", padx=(8, 0))
        source_box.bind("<<ComboboxSelected>>", self._on_project_tree_source_mode_changed)
        ttk.Button(actions, text="Refresh tree preview", command=lambda: self._refresh_project_tree(force_scan=True, reason="manual_refresh")).grid(row=1, column=2, sticky="w", padx=(12, 0))
        ttk.Button(actions, text="Select all tree items", command=self._select_all_project_tree).grid(row=1, column=3, sticky="w", padx=(8, 0))
        ttk.Button(actions, text="Clear tree selection", command=self._clear_project_tree_selection).grid(row=1, column=4, sticky="w", padx=(8, 0))
        ttk.Button(actions, text="Expand preview tree", command=lambda: self._expand_tree(self.project_tree)).grid(row=1, column=5, sticky="w", padx=(8, 0))
        ttk.Button(actions, text="Collapse preview tree", command=lambda: self._collapse_tree(self.project_tree)).grid(row=1, column=6, sticky="w", padx=(8, 0))
        ttk.Checkbutton(actions, text="Show dependency folders", variable=self.project_tree_show_dependency_storage, command=self._rerender_project_tree_from_cache).grid(row=1, column=7, sticky="w", padx=(8, 0))

        self.custom_export_path_frame = ttk.Frame(actions)
        self.custom_export_path_frame.grid(row=2, column=0, columnspan=10, sticky="ew", pady=(10, 0))
        ttk.Label(self.custom_export_path_frame, text="Custom Export Path").pack(side="left")
        ttk.Entry(self.custom_export_path_frame, textvariable=self.export_dir).pack(side="left", fill="x", expand=True, padx=(8, 0))
        ttk.Button(self.custom_export_path_frame, text="Choose", command=self._browse_export_dir).pack(side="left", padx=(8, 0))
        ttk.Button(self.custom_export_path_frame, text="Reset", command=self._reset_export_dir_to_project).pack(side="left", padx=(8, 0))
        self.active_tree_export_button = ttk.Button(self.custom_export_path_frame, text="Run Worktree Export", command=self._export_active_tree_source)
        self.active_tree_export_button.pack(side="left", padx=(12, 0))
        actions.columnconfigure(9, weight=1)

        self.project_tree_status = tk.StringVar(value="Tree not loaded yet.")
        ttk.Label(root, textvariable=self.project_tree_status).pack(anchor="w", pady=(8, 4))

        pane = ttk.PanedWindow(root, orient="horizontal")
        pane.pack(fill="both", expand=True)
        left = ttk.Frame(pane)
        pane.add(left, weight=2)
        self.project_tree = ttk.Treeview(left, columns=("type", "path"), show="tree headings", selectmode="extended")
        self.project_tree.heading("#0", text="Name")
        self.project_tree.heading("type", text="Type")
        self.project_tree.heading("path", text="Project path")
        self.project_tree.column("#0", width=260)
        self.project_tree.column("type", width=80)
        self.project_tree.column("path", width=520)
        yscroll = ttk.Scrollbar(left, orient="vertical", command=self.project_tree.yview)
        xscroll = ttk.Scrollbar(left, orient="horizontal", command=self.project_tree.xview)
        self.project_tree.configure(yscrollcommand=yscroll.set, xscrollcommand=xscroll.set)
        self.project_tree.grid(row=0, column=0, sticky="nsew")
        yscroll.grid(row=0, column=1, sticky="ns")
        xscroll.grid(row=1, column=0, sticky="ew")
        left.rowconfigure(0, weight=1)
        left.columnconfigure(0, weight=1)
        self.project_tree.bind("<<TreeviewSelect>>", self._on_project_tree_selection)
        self.project_tree.bind("<Button-1>", self._remember_project_tree_selection_for_toggle, add="+")
        self.project_tree.bind("<<TreeviewOpen>>", self._restore_project_tree_selection_after_toggle, add="+")
        self.project_tree.bind("<<TreeviewClose>>", self._restore_project_tree_selection_after_toggle, add="+")
        self._make_tree_manual_tags(self.project_tree)

        right = ttk.Frame(pane)
        pane.add(right, weight=1)
        settings_box = ttk.LabelFrame(right, text="Export settings for selected tree", padding=8)
        settings_box.pack(fill="x")
        self.project_tree_export_settings_status = tk.StringVar(value="Select a tree source to edit export settings.")
        ttk.Label(settings_box, textvariable=self.project_tree_export_settings_status, wraplength=440).pack(anchor="w", pady=(0, 6))

        self.worktree_export_settings_frame = ttk.Frame(settings_box)
        self.create_export_settings_frame = ttk.Frame(settings_box)
        self._build_export_settings_group(self.worktree_export_settings_frame, source="worktree")
        self._build_export_settings_group(self.create_export_settings_frame, source="create")

        preview_pane = ttk.PanedWindow(right, orient="horizontal")
        self.project_tree_preview_pane = preview_pane
        preview_pane.pack(fill="both", expand=True, pady=(10, 0))
        scope_box = ttk.LabelFrame(preview_pane, text="Selected scope preview", padding=8)
        preview_box = ttk.LabelFrame(preview_pane, text="Clicked file preview / import matches", padding=8)
        preview_pane.add(scope_box, weight=1)
        preview_pane.add(preview_box, weight=1)
        self.project_scope_text = self._pack_text_with_scrollbars(scope_box, wrap="none", height=18)
        self.project_scope_text.bind("<KeyRelease>", self._schedule_project_scope_preview_sync, add="+")
        self.project_scope_text.bind("<FocusOut>", self._apply_project_scope_preview_text_selection, add="+")
        ttk.Button(scope_box, text="Apply typed scope", command=self._apply_project_scope_preview_text_selection).pack(anchor="w", pady=(6, 0))
        self.project_file_preview_text = self._pack_text_with_scrollbars(preview_box, wrap="none", height=18)
        self._refresh_export_settings_visibility()
        self._apply_text_widget_theme()

    def _build_output_tab(self) -> None:
        root = self.output_tab
        actions = ttk.Frame(root)
        actions.pack(fill="x")
        ttk.Button(actions, text="Refresh output list", command=self._refresh_output_tree).pack(side="left")
        ttk.Button(actions, text="Scan metadata", command=self._scan_metadata_to_output).pack(side="left", padx=(8, 0))

        pane = ttk.PanedWindow(root, orient="horizontal")
        pane.pack(fill="both", expand=True, pady=(10, 0))

        self.output_tree = ttk.Treeview(pane, columns=("path",), show="headings")
        self.output_tree.heading("path", text="Generated output")
        self.output_tree.column("path", width=360)
        self.output_tree.bind("<<TreeviewSelect>>", self._preview_selected_output)
        pane.add(self.output_tree, weight=1)

        output_text_frame = ttk.Frame(pane)
        self.output_text = self._pack_text_with_scrollbars(output_text_frame, wrap="none")
        pane.add(output_text_frame, weight=3)

    # ---------- Dynamic Controls ----------
    def _rebuild_dynamic_controls(self) -> None:
        if hasattr(self, "file_type_frame"):
            for widget in self.file_type_frame.winfo_children():
                widget.destroy()
        if hasattr(self, "profile_frame"):
            for widget in self.profile_frame.winfo_children():
                widget.destroy()
        for frame_name in (
            "reference_frame",
            "operation_role_frame",
            "default_reference_frame",
            "default_operation_role_frame",
            "plugin_reference_frame",
            "plugin_operation_role_frame",
        ):
            frame = getattr(self, frame_name, None)
            if frame is not None:
                for widget in frame.winfo_children():
                    widget.destroy()

        self.file_type_vars = {ft["id"]: tk.BooleanVar(value=False) for ft in self.schema.get("file_types", [])}
        default_profiles = set(default_profile_ids(self.schema))
        self.profile_vars = {profile["id"]: tk.BooleanVar(value=profile["id"] in default_profiles) for profile in self.schema.get("boilerplate_profiles", []) if profile.get("id")}
        self.reference_vars = {ref["id"]: tk.BooleanVar(value=False) for ref in self.schema.get("reference_domains", []) if ref.get("id")}
        self.operation_role_vars = {role["id"]: tk.BooleanVar(value=False) for role in self.schema.get("operation_roles", []) if role.get("id")}

        if hasattr(self, "file_type_frame"):
            for ft in self.schema.get("file_types", []):
                label = f"{ft['id']}  ({', '.join(ft.get('extensions', []))})"
                ttk.Checkbutton(self.file_type_frame, text=label, variable=self.file_type_vars[ft["id"]]).pack(anchor="w")

        if hasattr(self, "profile_frame"):
            for profile in self.schema.get("boilerplate_profiles", []):
                name = profile.get("id")
                if name in self.profile_vars:
                    label = f"{name} — {profile.get('purpose', profile.get('label', ''))}"
                    ttk.Checkbutton(self.profile_frame, text=label, variable=self.profile_vars[name]).pack(anchor="w")

        for ref in self.schema.get("reference_domains", []):
            name = ref.get("id")
            if name in self.reference_vars:
                label = f"{name} — {ref.get('label', '')}"
                frame = getattr(self, "plugin_reference_frame" if self._is_plugin_reference_domain(ref) else "default_reference_frame", None)
                if frame is not None:
                    ttk.Checkbutton(frame, text=label, variable=self.reference_vars[name], command=self._on_reference_selection_changed).pack(anchor="w")

        for role in self.schema.get("operation_roles", []):
            name = role.get("id")
            if name in self.operation_role_vars:
                label = f"{name} — {role.get('label', '')}"
                frame = getattr(self, "plugin_operation_role_frame" if self._is_plugin_operation_role(role) else "default_operation_role_frame", None)
                if frame is not None:
                    ttk.Checkbutton(frame, text=label, variable=self.operation_role_vars[name], command=self._on_reference_selection_changed).pack(anchor="w")

        if hasattr(self, "path_type_box"):
            self.path_type_box.configure(values=self.schema["supported_path_types"])
        if hasattr(self, "ai_target_box"):
            self.ai_target_box.configure(values=self.schema["supported_ai_targets"])
        if hasattr(self, "prompt_type_box"):
            self.prompt_type_box.configure(values=self._prompt_type_values())
        if hasattr(self, "plugin_kind_box"):
            self.plugin_kind_box.configure(values=["reference_domain", "operation_role"])

    def _apply_default_file_types(self) -> None:
        defaults = set(default_file_types_for_path_type(self.path_type_var.get(), self.schema))
        for key, var in self.file_type_vars.items():
            var.set(key in defaults)

    def _selected_file_types(self) -> list[str]:
        selected = [name for name, var in self.file_type_vars.items() if var.get()]
        return selected or default_file_types_for_path_type(self.path_type_var.get(), self.schema)

    def _selected_profiles(self) -> list[str]:
        return [name for name, var in self.profile_vars.items() if var.get()]

